        public static string Localize(string text)
        {
            return MultilingualTranslationRuntime.TranslateToLanguage(text, Language.BrazilianPortuguese);
        }

        public static void RegisterGeneratedCardName(string name)
        {
            if (string.IsNullOrEmpty(name)) return;
            int separator = name.IndexOf('-');
            if (separator <= 0 || separator >= name.Length - 1) return;
            string left = name.Substring(0, separator);
            string right = name.Substring(separator + 1);
            if (!P03InKayceesModMod.CardParts.TryGetValue(left, out string translatedLeft) ||
                !P03InKayceesModMod.CardParts.TryGetValue(right, out string translatedRight)) return;
            string localized = translatedLeft + "-" + translatedRight;
            Translate(GUID, null, name, localized, Language.BrazilianPortuguese);
            if (name.ToLowerInvariant().Contains("skel-e"))
                Translate(GUID, null, "Skel-E-" + name.Replace(" ", "-"), localized + " Esqueleto", Language.BrazilianPortuguese);
            else
                Translate(GUID, null, "Skele " + name, localized + " Exoesqueleto", Language.BrazilianPortuguese);
            Translate(GUID, null, "Beta " + name, "Beta " + localized, Language.BrazilianPortuguese);
            Translate(GUID, null, "Lesser " + name, "Menor " + localized, Language.BrazilianPortuguese);
            Translate(GUID, null, "Elder " + name, "Ancião " + localized, Language.BrazilianPortuguese);
            for (int score = 0; score <= 100; score++)
            {
                string suffix = score.ToString() + ".0";
                Translate(GUID, null, name + " " + suffix, localized + " " + suffix, Language.BrazilianPortuguese);
            }
        }

