                    foreach (Ability ability in value.Abilities)
                    {
                        text4 = text4 + ", " + AbilitiesUtil.GetInfo(ability).rulebookName;
                        text4Loc = text4Loc + ", " + BrazilianPortugueseLanguagePack.Localize(AbilitiesUtil.GetInfo(ability).rulebookName);
                    }
                    text4 += ".";
                    text4Loc += ".";
                    text3 = string.Format("An {0} is defined as: {1} Power, {2} Health", value.DisplayedName, value.Attack, value.Health) + text4;
                    text3Loc = string.Format("{0}: {1} de poder, {2} de vida", value.DisplayedNameLocalized, value.Attack, value.Health) + text4Loc;
                }
                string text5 = string.Concat(new string[] { text2, " ", value.DisplayedName, " is created in your hand. ", text3 });
                string text5LocCardName = value.DisplayedNameLocalized;
                string text5Loc = string.Concat(new string[] { text2Loc, " ", text5LocCardName, " aparecerá em sua mão. ", text3Loc });
                Translate(GUID, null, text5, text5Loc, Language.BrazilianPortuguese);
                Translate(GUID, null, "While " + value.DisplayedNameLocalized + " is on the board, remove ally Terrain and Pelt cards and transform the rest into random Apostles.", "Enquanto " + value.DisplayedNameLocalized + " estiver no tabuleiro, remova as cartas aliadas de Terreno e Pele e transforme as demais em Apóstolos aleatórios.", Language.BrazilianPortuguese);
                Translate(GUID, null, "[c:bR]The Clock[c:] and your [c:bR]" + value.DisplayedNameLocalized + "[c:] will remain in that abandoned time.", "[c:bR]O Relógio[c:] e sua carta [c:bR]" + value.DisplayedNameLocalized + "[c:] permanecerão naquele tempo abandonado.", Language.BrazilianPortuguese);
                Translate(GUID, null, "False " + value.DisplayedNameLocalized, "Falso " + value.DisplayedNameLocalized, Language.BrazilianPortuguese);
                Translate(GUID, null, "[c:bB]That " + value.DisplayedNameLocalized + " costs more energy than you have.[c:]", "[c:bB]Você não tem energia suficiente para jogar " + value.DisplayedNameLocalized + ".[c:]", Language.BrazilianPortuguese);
            }
            if (source == null)
            for (int max = 1; max <= 10; max++)
            {
                Translate(GUID, null, "[c:bB]Do you still not get it? It costs " + max.ToString() + " energy and you don't have enough.[c:]", "[c:bB]Ainda não entendeu? Custa " + max.ToString() + " de energia, e você não tem o suficiente.[c:]", Language.BrazilianPortuguese);
                for (int count = 0; count < max; count++)
                {
                    Translate(GUID, null, "[c:bB]That costs " + max.ToString() + " energy and you have " + count.ToString() + ".[c:]", "[c:bB]Isso custa " + max.ToString() + " de energia e você tem " + count.ToString() + ".[c:]", Language.BrazilianPortuguese);
                }
            }


            // LifeCostAPI
            if (source == null) Debug.Log("Post Register Translations for LifeCostAPI");
            foreach (var value in cards)
            {
                if (!value.HasDisplayedNameEnglish) continue;
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your [c:bG]Scales[c:] are too tipped to play [c:bG]" + value.DisplayedNameLocalized + "[c:].", "Sua [c:bG]balança[c:] está inclinada demais para jogar [c:bG]" + value.DisplayedNameLocalized + "[c:].", Language.BrazilianPortuguese);
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bG]" + value.DisplayedNameLocalized + "[c:] requires you to pay in life, in which you can not fullfill without killing yourself.", "[c:bG]" + value.DisplayedNameLocalized + "[c:] exige vida como pagamento, e você não pode pagar sem morrer.", Language.BrazilianPortuguese);
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You would kill yourself if you played [c:bG]" + value.DisplayedNameLocalized + "[c:]. Your [c:bG]Scales[c:] are too tipped", "Jogar [c:bG]" + value.DisplayedNameLocalized + "[c:] mataria você. Sua [c:bG]balança[c:] está inclinada demais.", Language.BrazilianPortuguese);
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your [c:bG]Scales[c:] are too tipped and you lack the [c:gray]Foils[c:] to play " + value.DisplayedNameLocalized + ".", "Sua [c:bG]balança[c:] está inclinada demais e faltam [c:gray]metalizadas[c:] para jogar " + value.DisplayedNameLocalized + ".", Language.BrazilianPortuguese);
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You lack the foils to play that [c:gray]" + value.DisplayedNameLocalized + "[c:].", "Você não tem metalizadas suficientes para jogar [c:gray]" + value.DisplayedNameLocalized + "[c:].", Language.BrazilianPortuguese);
                for (int count = 0; count <= 20; count++)
                {
                    Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:gray]" + value.DisplayedNameLocalized + "[c:] requires you pay it's cost in [c:gray]foils[c:], that which you have [c:gray]" + count.ToString() + "[c:].", "O custo de [c:gray]" + value.DisplayedNameLocalized + "[c:] é pago em [c:gray]metalizadas[c:]; você tem [c:gray]" + count.ToString() + "[c:].", Language.BrazilianPortuguese);
                    Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That [c:gray]" + value.DisplayedNameLocalized + "[c:] has the cost of [c:gray]" + count.ToString() + "[c:] foils, which you do not have.", "[c:gray]" + value.DisplayedNameLocalized + "[c:] custa [c:gray]" + count.ToString() + "[c:] metalizadas, e você não tem o suficiente.", Language.BrazilianPortuguese);
                }
            }

            // Sire_MoDeers
            if (source == null) Debug.Log("Post Register Translations for Sire_MoDeers");
            foreach (var value in cards)
            {
                if (!value.HasDisplayedNameEnglish) continue;
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, value.DisplayedName + "'s Protector", "Protetor de " + value.DisplayedNameLocalized, Language.BrazilianPortuguese);
            }

            if (source == null) Debug.Log("Post Register Translations Ended");
            stopwatch.Stop();
            if (source == null) Debug.Log($"PostRegisterTranslations 执行时间: {stopwatch.ElapsedMilliseconds} ms");
        }

        private static List<PostRegisterCardData> CachePostRegisterCardData(IEnumerable<CardInfo> source)
        {
            var cards = new List<PostRegisterCardData>();
            foreach (var card in source)
            {
                if (card.SafeIsUnityNull()) continue;
                cards.Add(new PostRegisterCardData(card, card.IsBaseGameCard()));
            }
            return cards;
        }

        private sealed class PostRegisterCardData
        {
            public PostRegisterCardData(CardInfo card, bool isBaseGameCard)
            {
                IsBaseGameCard = isBaseGameCard;
                DisplayedNameEnglish = card.DisplayedNameEnglish;
                DisplayedNameLocalized = card.DisplayedNameLocalized;
                DisplayedName = card.displayedName;
                Description = card.description;
                Name = card.name;
                Attack = card.Attack;
                Health = card.Health;
                Abilities = card.Abilities?.ToArray() ?? Array.Empty<Ability>();
            }

            public bool IsBaseGameCard { get; }
            public string DisplayedNameEnglish { get; }
            public string DisplayedNameLocalized { get; }
            public string DisplayedName { get; }
            public string Description { get; }
            public string Name { get; }
            public int Attack { get; }
            public int Health { get; }
            public Ability[] Abilities { get; }
            public bool HasDisplayedNameEnglish => DisplayedNameEnglish != null;
            public bool HasDisplayedName => DisplayedName != null;
        }
        private static bool NameStartsWithVowel(string name)
        {
            if (string.IsNullOrEmpty(name))
            {
                return false;
            }
            char c = name.ToLowerInvariant()[0];
            return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
        }

    }

