            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This option will allow you to see what cards are left in your deck.", "Esta opção permite ver quais cartas restam no seu baralho.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This option will disable all effects that might cause motion sickness and other visually jarring effects.", "Esta opção desativa todos os efeitos que possam causar enjoo de movimento e outros efeitos visualmente desconfortáveis.", Language.BrazilianPortuguese);
