    public class MagnificusMod
    {
        public static Dictionary<string, string> Cards = new();
        public static Dictionary<string, List<KeyValuePair<string, string>>> CardsDescription = new();

        public static Dictionary<string, string> Abilities = new();

        public static void RegisterCard(string en, string zh, string desen, string deszh)
        {
            if (!Cards.ContainsKey(en))
            {
                Cards.Add(en, zh);
            }
            if (!CardsDescription.ContainsKey(en))
            {
                CardsDescription[en] = new List<KeyValuePair<string, string>>();
            }
            CardsDescription[en].Add(new KeyValuePair<string, string>(desen, deszh));
        }

        public static void RegisterAbility(string en, string zh)
        {
            Abilities.Add(en, zh);
        }

        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Magnificus Mod");
            // SetText
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "New Magnificus Run", "NOVA PARTIDA COM MAGNIFICUS", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NEW MAGNIFICUS RUN", "NOVA PARTIDA COM MAGNIFICUS", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "View Deck", "Ver Baralho", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TOWER OF MAGICKS", "TORRE DAS MAGIAS", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GOO DUNGEON", "MASMORRA DE GOSMA", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LAVA DUNGEON", "MASMORRA DE LAVA", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "VOID DUNGEON", "MASMORRA DO VAZIO", Language.BrazilianPortuguese);

            // Config
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Automatically unlocks every challenge and starter deck in Magnificus' Kaycees Mod. This does NOT change your magnificus challenge point value. If you have a change of heart and decide to unlock the challenges fairly, your challenge points will remain the same.", "Desbloqueia automaticamente todos os desafios e baralhos iniciais do Mod da Kaycee do Magnificus. Isso NÃO altera seus pontos de desafio do Magnificus. Se mudar de ideia e quiser desbloquear os desafios de forma justa, seus pontos de desafio continuarão iguais.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Base wizard cards from act 2 will keep their original statlines.", "As cartas básicas de mago do Ato 2 mantêm seus atributos originais.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Use the old 2D flat card designs instead of the new 3D models.", "Usa os designs antigos de cartas planas em 2D em vez dos novos modelos 3D.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Add paint splashes to the background of every card (like in the original magnificus finale).", "Adiciona respingos de tinta ao fundo de todas as cartas, como no final original do Magnificus.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Third person perspective for magnificus' game. Disable if you want the classic first person experience.", "Perspectiva em terceira pessoa para o jogo do Magnificus. Desative para a experiência clássica em primeira pessoa.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Show a grid around the player in tabletop mode.", "Mostra uma grade ao redor do jogador no modo de mesa.", Language.BrazilianPortuguese);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blank Mox", "Mox em Branco", Language.BrazilianPortuguese);
            RegisterAbility("Blank Mox", "Mox em Branco");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is drawn, it will materialize into a random Mox Crystal. \n When on another card, the card will generate a random Mox Crystal.", "Quando uma carta que possua este selo é comprada, ela se materializa em um Cristal de Mox aleatório.\n Quando está em outra carta, o selo faz essa carta gerar um Cristal de Mox aleatório.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undecided Mox", "Mox Indefinido", Language.BrazilianPortuguese);
            RegisterAbility("Undecided Mox", "Mox Indefinido");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, select a mox type for this card to provide.", "Quando uma carta que possua este selo entra em jogo, escolha o tipo de mox que ela vai fornecer.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruby Heart", "Coração de Rubi", Language.BrazilianPortuguese);
            RegisterAbility("Ruby Heart", "Coração de Rubi");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it creates a Ruby Mox in its place.", "Quando uma carta que possua este selo morre, cria um Mox de Rubi no seu lugar.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sapphire Heart", "Coração de Safira", Language.BrazilianPortuguese);
            RegisterAbility("Sapphire Heart", "Coração de Safira");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it creates a Sapphire Mox in its place.", "Quando uma carta que possua este selo morre, cria um Mox de Safira no seu lugar.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Marrow", "Medula Óssea", Language.BrazilianPortuguese);
            RegisterAbility("Bone Marrow", "Medula Óssea");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When one of your non-gem cards perishes, a card bearing this sigil gains 1 power, maxing out at 5.", "Quando uma das suas cartas que não seja de joia morre, uma carta que possua este selo ganha 1 de poder, até o máximo de 5.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stimulation", "Estimulação", Language.BrazilianPortuguese);
            RegisterAbility("Stimulation", "Estimulação");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of every turn, a card bearing this sigil gains 1 power, maxing out at 4.", "Ao fim de cada turno, uma carta que possua este selo ganha 1 de poder, até o máximo de 4.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stimulation (Health)", "Estimulação (Vida)", Language.BrazilianPortuguese);
            RegisterAbility("Stimulation (Health)", "Estimulação (Vida)");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of every turn, a card bearing this sigil gains 2 health, maxes out at 10.", "Ao fim de cada turno, uma carta que possua este selo ganha 2 de vida, até o máximo de 10.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead Draw", "Saque Mortal", Language.BrazilianPortuguese);
            RegisterAbility("Dead Draw", "Saque Mortal");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a non-gem card dies, draw a card from your deck.", "Quando uma carta que não seja de joia morre, compre uma carta do seu baralho.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Heart", "Coração de Esmeralda", Language.BrazilianPortuguese);
            RegisterAbility("Emerald Heart", "Coração de Esmeralda");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it creates an Emerald Mox in its place.", "Quando uma carta que possua este selo morre, cria um Mox de Esmeralda no seu lugar.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gooey", "Gosmento", Language.BrazilianPortuguese);
            RegisterAbility("Gooey", "Gosmento");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is struck, the striker loses 1 attack.", "Quando uma carta que possua este selo é atingida, o atacante perde 1 de ataque.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mental Gemnastics", "Gemologia", Language.BrazilianPortuguese);
            RegisterAbility("Mental Gemnastics", "Gemologia");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, draw cards from your deck based on how many Gems are on the board.", "Quando uma carta que possua este selo entra em jogo, compre cartas do seu baralho em quantidade igual ao número de joias no tabuleiro.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loot", "Espólios", Language.BrazilianPortuguese);
            RegisterAbility("Loot", "Espólios");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil deals direct damage, draw cards from your deck based on how much damage was dealt.", "Quando uma carta que possua este selo causa dano direto, compre cartas do seu baralho em quantidade igual ao dano causado.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Life Steal", "Roubo de Vida", Language.BrazilianPortuguese);
            RegisterAbility("Life Steal", "Roubo de Vida");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil deals direct damage, the amount dealt will be healed to the owner of this card.", "Quando uma carta que possua este selo causa dano direto, seu dono recupera vida igual ao dano causado.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Knockback Hit", "Golpe de Repulsão", Language.BrazilianPortuguese);
            RegisterAbility("Knockback Hit", "Golpe de Repulsão");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil hits an opposing card, the opposing card will be kicked in the direction inscrybed in the sigil.", "Quando uma carta que possua este selo atinge uma carta adversária, empurra o alvo na direção indicada pelo selo.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Impaled", "Empalado", Language.BrazilianPortuguese);
            RegisterAbility("Impaled", "Empalado");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it creates a Spear in its placed. A spear is defined as Sharp, 0 power, 3 health.", "Quando uma carta que possua este selo morre, cria uma Lança no seu lugar. A Lança tem Espinhos Afiados, 0 de poder e 3 de vida.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magnus Mox", "Megamox", Language.BrazilianPortuguese);
            RegisterAbility("Magnus Mox", "Megamox");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While a card bearing this sigil is on the board, it provides an orange gem, a blue gem and a green gem to its owner.", "Enquanto uma carta que possua este selo estiver no tabuleiro, ela fornece uma joia laranja, uma azul e uma verde ao seu dono.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Resurrection", "Ressurreição", Language.BrazilianPortuguese);
            RegisterAbility("Resurrection", "Ressurreição");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a non-gem card perishes, the dead card will be brought back to life, but this card loses 3 health.", "Quando uma carta que não seja de joia morre, ela é trazida de volta à vida, mas esta carta perde 3 de vida.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rerolls", "Poder dos Dados", Language.BrazilianPortuguese);
            RegisterAbility("Rerolls", "Poder dos Dados");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of every turn, a card bearing this sigils' base power will be increased by a random value between 0 and 3.", "Ao fim de cada turno, o poder básico de uma carta que possua este selo passa a ser um valor aleatório entre 0 e 3.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Steel Trap", "Armadilha de Aço", Language.BrazilianPortuguese);
            RegisterAbility("Steel Trap", "Armadilha de Aço");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, the opposing card also perishes.", "Quando uma carta que possua este selo morre, a carta diante dela também morre.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Shield", "Escudo de Joias", Language.BrazilianPortuguese);
            RegisterAbility("Gem Shield", "Escudo de Joias");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, all gems on the board gain a shield.", "Quando uma carta que possua este selo entra em jogo, todas as joias no tabuleiro ganham um escudo.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plating Work", "Trabalho de Revestimento", Language.BrazilianPortuguese);
            RegisterAbility("Plating Work", "Trabalho de Revestimento");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While a card bearing this sigil is on the board, all gems on your side of the board gain the Sharp Quills sigil, and 2 health.", "Enquanto uma carta que possua este selo estiver no tabuleiro, todas as joias do seu lado do tabuleiro ganham o selo Espinhos Afiados e 2 de vida.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Animator", "Animador de Marionetes", Language.BrazilianPortuguese);
            RegisterAbility("Animator", "Animador de Marionetes");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While a card bearing this sigil is on the board, all non-mox cards with 0 power gain 2 power", "Enquanto uma carta que possua este selo estiver no tabuleiro, todas as cartas que não sejam mox e tenham 0 de poder ganham 2 de poder.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Absorber", "Absorvedor de Joias", Language.BrazilianPortuguese);
            RegisterAbility("Gem Absorber", "Absorvedor de Joias");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, all gems on your side of the board will perish. For each gem absorbed, gain 1 power and 2 health.", "Quando uma carta que possua este selo entra em jogo, todas as joias do seu lado do tabuleiro morrem. Para cada joia absorvida, esta carta ganha 1 de poder e 2 de vida.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Submerge", "Submergir", Language.BrazilianPortuguese);
            RegisterAbility("Submerge", "Submergir");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, a card bearing this sigil will submerge. Upon resubmerging, this card will become a random Tentacle Card.", "Ao fim do turno, uma carta que possua este selo submerge. Ao voltar à superfície, transforma-se em uma carta de Tentáculo aleatória.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Familiar", "Familiar", Language.BrazilianPortuguese);
            RegisterAbility("Familiar", "Familiar");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will perish if there are no non-gem cards on the board.", "Uma carta que possua este selo morre se não houver nenhuma carta que não seja de joia no tabuleiro.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fading", "Desvanecer", Language.BrazilianPortuguese);
            RegisterAbility("Fading", "Desvanecer");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will perish at the end of the turn.", "Uma carta que possua este selo morre ao fim do turno.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Morph", "Metamorfo", Language.BrazilianPortuguese);
            RegisterAbility("Morph", "Metamorfo");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, it will mimic the card opposing it. If there is no card opposing it, this card will perish.", "Quando uma carta que possua este selo entra em jogo, imita a carta diante dela. Se não houver nenhuma, esta carta morre.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiplication", "Multiplicação", Language.BrazilianPortuguese);
            RegisterAbility("Multiplication", "Multiplicação");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, draw another of this card, but with a different gem cost.", "Quando uma carta que possua este selo entra em jogo, compre outra igual, mas com um custo de joias diferente.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Cycle", "Ciclo Mox", Language.BrazilianPortuguese);
            RegisterAbility("Mox Cycle", "Ciclo Mox");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of every turn, all the mox on the board will cycle into different gems.", "Ao fim de cada turno, todos os mox no tabuleiro alternam para outros tipos de joia.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Strafe", "Deslocamento Mox", Language.BrazilianPortuguese);
            RegisterAbility("Mox Strafe", "Deslocamento Mox");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, this card will move to the direction inscrybed on the sigil, and leave behind a mox.", "Ao fim do turno, esta carta se move na direção indicada no selo e deixa um mox para trás.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Purist", "Purismo", Language.BrazilianPortuguese);
            RegisterAbility("Purist", "Purismo");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Any card directly opposing this one will have all it's sigils removed.", "Qualquer carta diretamente diante desta perde todos os seus selos.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brewery", "Cervejaria", Language.BrazilianPortuguese);
            RegisterAbility("Brewery", "Cervejaria");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of every turn, you automatically draw a mox card from your side deck.", "Ao fim de cada turno, você compra automaticamente uma carta de mox do seu baralho secundário.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ignite", "Incendiar", Language.BrazilianPortuguese);
            RegisterAbility("Ignite", "Incendiar");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, every empty opposing slot will be filled with flames. A flame is defined as a 0/1, Annoying.", "Quando uma carta que possua este selo entra em jogo, todos os espaços adversários vazios são preenchidos com chamas. Uma chama tem 0/1 e Irritante.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Projection", "Projeção Estelar", Language.BrazilianPortuguese);
            RegisterAbility("Projection", "Projeção Estelar");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is stuck, it will move and leave behind an astral projection of itself.", "Quando uma carta que possua este selo é atingida, ela se move e deixa para trás uma projeção astral de si.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell Book", "Livro de Feitiços", Language.BrazilianPortuguese);
            RegisterAbility("Spell Book", "Livro de Feitiços");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, draw a random spell card.", "Quando uma carta que possua este selo entra em jogo, compre uma carta de feitiço aleatória.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scholar", "Estudioso de Feitiços", Language.BrazilianPortuguese);
            RegisterAbility("Scholar", "Estudioso de Feitiços");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, draw a random one of Bleene's Books.", "Quando uma carta que possua este selo entra em jogo, compre um dos Livros de Azulerde aleatoriamente.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Midas' Touch", "Toque de Midas", Language.BrazilianPortuguese);
            RegisterAbility("Midas' Touch", "Toque de Midas");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil attacks another card, the attacked card will lose all of it's attack and turn to gold.", "Quando uma carta que possua este selo ataca outra carta, o alvo perde todo o ataque e vira ouro.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Made of Gold", "Feito de Ouro", Language.BrazilianPortuguese);
            RegisterAbility("Made of Gold", "Feito de Ouro");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, the killer will gain 2 crystals.", "Quando uma carta que possua este selo morre, quem a matou ganha 2 cristais.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summon Runes", "Runas de Invocação Explosiva", Language.BrazilianPortuguese);
            RegisterAbility("Summon Runes", "Runas de Invocação Explosiva");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, it will summon two runes beside it. A rune is defined as 0 power, 1 health, Detonator.", "Quando uma carta que possua este selo entra em jogo, invoca duas runas ao seu lado. Uma runa tem 0 de poder, 1 de vida e Estrondo.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell of Health", "Feitiço de Vida", Language.BrazilianPortuguese);
            RegisterAbility("Spell of Health", "Feitiço de Vida");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, all cards on your side of the board gain +2 health.", "Quando um feitiço que possua este selo é jogado, todas as cartas do seu lado do tabuleiro ganham +2 de vida.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell of Attack", "Feitiço de Ataque", Language.BrazilianPortuguese);
            RegisterAbility("Spell of Attack", "Feitiço de Ataque");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, all cards on your side of the board gain +1 attack.", "Quando um feitiço que possua este selo é jogado, todas as cartas do seu lado do tabuleiro ganham +1 de ataque.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frost Spell", "Feitiço de Geada", Language.BrazilianPortuguese);
            RegisterAbility("Frost Spell", "Feitiço de Geada");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, all cards belonging to the opponent will have their attack set to 0, but given +2 health.", "Quando um feitiço que possua este selo é jogado, o ataque de todas as cartas adversárias passa a ser 0, mas elas ganham +2 de vida.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell of Wind", "Feitiço de Vento", Language.BrazilianPortuguese);
            RegisterAbility("Spell of Wind", "Feitiço de Vento");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, all cards on your side of the board will become airborne.", "Quando um feitiço que possua este selo é jogado, todas as cartas do seu lado do tabuleiro recebem Aéreo.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruckus", "Algazarra", Language.BrazilianPortuguese);
            RegisterAbility("Ruckus", "Algazarra");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, all cards on the board will move clockwise.", "Quando uma carta que possua este selo entra em jogo, todas as cartas no tabuleiro se movem no sentido horário.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell of Water", "Feitiço de Água", Language.BrazilianPortuguese);
            RegisterAbility("Spell of Water", "Feitiço de Água");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, every card on the board will have their sigils erased.", "Quando um feitiço que possua este selo é jogado, todas as cartas no tabuleiro têm seus selos apagados.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell of Flame", "Feitiço de Chama", Language.BrazilianPortuguese);
            RegisterAbility("Spell of Flame", "Feitiço de Chama");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a side of the board, every card on that side will lose 2 health (without perishing) and have their attack increased by 1.", "Escolha um lado do tabuleiro. Todas as cartas desse lado perdem 2 de vida, sem morrer, e ganham 1 de ataque.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Set Ablaze", "Incendiar", Language.BrazilianPortuguese);
            RegisterAbility("Set Ablaze", "Incendiar");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every card on the opposite side will lose 2 health (without perishing) and have their attack increased by 1.", "Todas as cartas do lado oposto perdem 2 de vida, sem morrer, e ganham 1 de ataque.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One Time Spell", "Feitiço de Uso Único", Language.BrazilianPortuguese);
            RegisterAbility("One Time Spell", "Feitiço de Uso Único");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When the turn ends, a spell bearing this sigil will perish and be removed from your deck.", "Quando o turno termina, um feitiço que possua este selo morre e é removido do seu baralho.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vase of Greed", "Vaso da Ganância", Language.BrazilianPortuguese);
            RegisterAbility("Vase of Greed", "Vaso da Ganância");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, discard your current hand and draw 4 new cards.", "Quando um feitiço que possua este selo é jogado, descarte sua mão atual e compre 4 cartas novas.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gnomification", "Gnomificação", Language.BrazilianPortuguese);
            RegisterAbility("Gnomification", "Gnomificação");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a slot to summon a Gnome card in.", "Escolha um espaço para invocar uma carta de Gnomo.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cursed", "Amaldiçoado", Language.BrazilianPortuguese);
            RegisterAbility("Cursed", "Amaldiçoado");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, it will immediately perish.", "Quando um feitiço que possua este selo é jogado, ele morre imediatamente.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inspiration", "Inspiração", Language.BrazilianPortuguese);
            RegisterAbility("Inspiration", "Inspiração");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card to give Airborne + Looter for 1 turn.", "Escolha uma carta para receber Aéreo + Espólios por 1 turno.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Calculus", "Cálculo", Language.BrazilianPortuguese);
            RegisterAbility("Calculus", "Cálculo");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card to swap stats.", "Escolha uma carta para trocar seus atributos entre si.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rage", "Frenesi", Language.BrazilianPortuguese);
            RegisterAbility("Rage", "Frenesi");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card to kill. The opponent of the card will recieve damage equal to the amount of health the card had.", "Escolha uma carta para matar. O adversário dessa carta sofre dano igual à vida que ela tinha.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fireball", "Bola de Fogo", Language.BrazilianPortuguese);
            RegisterAbility("Fireball", "Bola de Fogo");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card to take 2 damage.", "Escolha uma carta para sofrer 2 de dano.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cold to the Touch", "Toque Gélido", Language.BrazilianPortuguese);
            RegisterAbility("Cold to the Touch", "Toque Gélido");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigils attack another card, that card will lose 1 attack.", "Quando uma carta que possua este selo ataca outra carta, o alvo perde 1 de ataque.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frozen", "Congelado", Language.BrazilianPortuguese);
            RegisterAbility("Frozen", "Congelado");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of each turn, this card will lose its frozen health. When all frozen health is depleted, or this card is struck, it will defrost.", "Ao fim de cada turno, esta carta perde sua vida congelada. Quando toda a vida congelada se esgota, ou quando esta carta é atingida, ela descongela.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strong Pull", "Puxão Forte", Language.BrazilianPortuguese);
            RegisterAbility("Strong Pull", "Puxão Forte");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every opposing card will be inclined to hit this card instead of any other.", "Todas as cartas adversárias tendem a atacar esta carta em vez de qualquer outra.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Displacement", "Deslocamento", Language.BrazilianPortuguese);
            RegisterAbility("Displacement", "Deslocamento");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is drawn, another of this card will be added randomly into your deck", "Quando uma carta que possua este selo é comprada, outra igual é adicionada em uma posição aleatória do seu baralho.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Reckoning", "Acerto de Contas das Joias", Language.BrazilianPortuguese);
            RegisterAbility("Gem Reckoning", "Acerto de Contas das Joias");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of each turn, if the owner of this card does not control any gems, the leftmost card in your hand is discarded.", "Ao fim de cada turno, se o dono desta carta não controlar nenhuma joia, a carta mais à esquerda da sua mão é descartada.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Power", "Poder Mox", Language.BrazilianPortuguese);
            RegisterAbility("Mox Power", "Poder Mox");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of Mox Cards that the owner has on their side of the table.", "O valor representado por este selo é igual ao número de cartas de mox no lado da mesa de seu dono.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Health", "Vida Mox", Language.BrazilianPortuguese);
            RegisterAbility("Mox Health", "Vida Mox");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of Mox Cards that the owner has on their side of the table.", "O valor representado por este selo é igual ao número de cartas de mox no lado da mesa de seu dono.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Candle Proximity", "Proximidade da Vela", Language.BrazilianPortuguese);
            RegisterAbility("Candle Proximity", "Proximidade da Vela");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to how close this card is to the Candle on the table.", "O valor representado por este selo depende da proximidade desta carta com a vela na mesa.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Murder Power", "Poder Assassino", Language.BrazilianPortuguese);
            RegisterAbility("Murder Power", "Poder Assassino");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal the total amount of power on the opponents board.", "O valor representado por este selo é igual ao poder total do lado do tabuleiro do adversário.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to half the total amount of power on your board.", "O valor representado por este selo é igual à metade do poder total do seu lado do tabuleiro.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell Power", "Poder dos Feitiços", Language.BrazilianPortuguese);
            RegisterAbility("Spell Power", "Poder dos Feitiços");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to total amount of spells played during this current dungeon.", "O valor representado por este selo é igual ao total de feitiços jogados nesta masmorra.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to total amount of spells played during the battle.", "O valor representado por este selo é igual ao total de feitiços jogados durante a batalha.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Counterbattery Power", "Poder de Contra-ataque", Language.BrazilianPortuguese);
            RegisterAbility("Counterbattery Power", "Poder de Contra-ataque");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the amount of damage taken by you this battle, divided by two.", "O valor representado por este selo é igual à metade do dano que você sofreu nesta batalha.", Language.BrazilianPortuguese);
            foreach (Ability ability in Enum.GetValues(typeof(Ability)))
            {
                var info = AbilitiesUtil.GetInfo(ability);
                if (info == null || info.rulebookName == null || Abilities.ContainsKey(info.rulebookName))
                {
                    Debug.LogWarning($"Ability {ability} 没有有效的info，已跳过。");
                    continue;
                }
                if (info.rulebookName == null || Abilities.ContainsKey(info.rulebookName))
                {
                    Debug.LogWarning($"Ability {ability} 没有有效的rulebookName，或本身已注册，已跳过。");
                    continue;
                }
                RegisterAbility(info.rulebookName, BrazilianPortugueseLanguagePack.Localize(info.rulebookName));
            }

            // Card
