            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bleene's Scholar", "Aprendiz de Azulerde", Language.BrazilianPortuguese);
            RegisterCard("Bleene's Scholar", "Aprendiz de Azulerde", "A scholar in training, currently studying the works of Master Bleene.", "Um estudioso em formação, que atualmente estuda as obras do Mestre Azulerde.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A scholar in training, currently studying the works of Master Bleene.", "Um estudioso em formação, que atualmente estuda as obras do Mestre Azulerde.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Goranj's Warrior", "Guerreiro de Verdaranja", Language.BrazilianPortuguese);
