            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A foe mentored by Master Goranj, proficient at dual striking.", "Um adversário orientado pelo Mestre Verdaranja, hábil em golpear duas vezes.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cider Mage", "Mago da Sidra", Language.BrazilianPortuguese);
            RegisterCard("Cider Mage", "Mago da Sidra", "This mage has a secret formula of cider that nullifies the opponents spells..", "Este mago tem uma receita secreta de sidra que anula os feitiços do adversário...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This mage has a secret formula of cider that nullifies the opponents spells..", "Este mago tem uma receita secreta de sidra que anula os feitiços do adversário...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brewer Sage", "Sábio Cervejeiro", Language.BrazilianPortuguese);
            RegisterCard("Brewer Sage", "Sábio Cervejeiro", "A sage, sitting still and perfecting his art of brewing..", "Um sábio que permanece imóvel, aperfeiçoando sua arte de preparar poções...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A sage, sitting still and perfecting his art of brewing..", "Um sábio que permanece imóvel, aperfeiçoando sua arte de preparar poções...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soda Mage", "Mago do Refrigerante", Language.BrazilianPortuguese);
            RegisterCard("Soda Mage", "Mago do Refrigerante", "This pathetic mage melted away from drinking too much carbonated liquid..", "Este mago patético derreteu depois de beber líquido gaseificado demais...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This pathetic mage melted away from drinking too much carbonated liquid..", "Este mago patético derreteu depois de beber líquido gaseificado demais...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whitesmith", "Ourives", Language.BrazilianPortuguese);
            RegisterCard("Whitesmith", "Ourives", "Their life's work was dedicated to reinforcing gems.", "Dedicou a vida a reforçar joias.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Their life's work was dedicated to reinforcing gems.", "Dedicou a vida a reforçar joias.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Puppeteer", "Mestre das Marionetes", Language.BrazilianPortuguese);
            RegisterCard("Puppeteer", "Mestre das Marionetes", "Its mastery of control magicks lets even Practice Wizards contribute.", "Seu domínio da magia de controle permite que até os Bruxos de Treino contribuam.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its mastery of control magicks lets even Practice Wizards contribute.", "Seu domínio da magia de controle permite que até os Bruxos de Treino contribuam.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Juggler", "Malabarista", Language.BrazilianPortuguese);
            RegisterCard("Juggler", "Malabarista", "It juggles around your mox cards, as if they were juggling balls..", "Faz malabarismos com suas cartas de mox, como se fossem bolinhas...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It juggles around your mox cards, as if they were juggling balls..", "Faz malabarismos com suas cartas de mox, como se fossem bolinhas...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Joker", "Coringa", Language.BrazilianPortuguese);
            RegisterCard("Joker", "Coringa", "Dedicated to the art of fun.. though most only find it annoying.", "Dedicado à arte da diversão... embora a maioria só ache irritante.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dedicated to the art of fun.. though most only find it annoying.", "Dedicado à arte da diversão... embora a maioria só ache irritante.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Valkyrie", "Valquíria", Language.BrazilianPortuguese);
            RegisterCard("Valkyrie", "Valquíria", "A student that has trained under Master Orlu. It has become an expert in airborne magicks.", "Um aluno que treinou com a Mestra Laranul. Tornou-se especialista em magia aérea.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A student that has trained under Master Orlu. It has become an expert in airborne magicks.", "Um aluno que treinou com a Mestra Laranul. Tornou-se especialista em magia aérea.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Valkyrie Thief", "Valquíria Ladra", Language.BrazilianPortuguese);
            RegisterCard("Valkyrie Thief", "Valquíria Ladra", "liar liar chicken friar.", "mentiroso, mentiroso, frade do galinheiro.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "liar liar chicken friar.", "mentiroso, mentiroso, frade do galinheiro.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Maniac", "Maníaco da Esmeralda", Language.BrazilianPortuguese);
            RegisterCard("Emerald Maniac", "Maníaco da Esmeralda", "A crazed maniac.. Drawing out health from the mox..", "Um louco desvairado... Extrai vida dos mox...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A crazed maniac.. Drawing out health from the mox..", "Um louco desvairado... Extrai vida dos mox...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruby Daemon", "Demônio de Rubi", Language.BrazilianPortuguese);
            RegisterCard("Ruby Daemon", "Demônio de Rubi", "If not properly sustained, it will destroy your hand to fuel itself..", "Se não receber sustento adequado, destrói sua mão para alimentar a si mesmo...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If not properly sustained, it will destroy your hand to fuel itself..", "Se não receber sustento adequado, destrói sua mão para alimentar a si mesmo...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Friend", "Amigo das Joias", Language.BrazilianPortuguese);
            RegisterCard("Gem Friend", "Amigo das Joias", "fren", "miguxo");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "fren", "miguxo", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Druid", "Druida", Language.BrazilianPortuguese);
            RegisterCard("Druid", "Druida", "Just look at what you've done..", "Veja só o que você fez...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just look at what you've done..", "Veja só o que você fez...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chained Legs", "Pernas Acorrentadas", Language.BrazilianPortuguese);
            RegisterCard("Chained Legs", "Pernas Acorrentadas", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sealed Body", "Corpo Selado", Language.BrazilianPortuguese);
