            RegisterCard("Imprisoned Tyrant", "Tirano Aprisionado", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiplication mage", "Mago da Multiplicação", Language.BrazilianPortuguese);
            RegisterCard("Multiplication mage", "Mago da Multiplicação", "This cycle can go on forever..", "Este ciclo pode durar para sempre...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This cycle can go on forever..", "Este ciclo pode durar para sempre...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Invisible mage", "Mago Invisível", Language.BrazilianPortuguese);
            RegisterCard("Invisible mage", "Mago Invisível", "It drank the wrong potion and ended up invisible. How clumsy.", "Bebeu a poção errada e acabou invisível. Que desastrado.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It drank the wrong potion and ended up invisible. How clumsy.", "Bebeu a poção errada e acabou invisível. Que desastrado.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crystal Sage", "Sábio dos Cristais", Language.BrazilianPortuguese);
            RegisterCard("Crystal Sage", "Sábio dos Cristais", "A young scholar, profoundly studying mana crystals.", "Um jovem estudioso que se aprofunda na pesquisa de cristais de mana.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A young scholar, profoundly studying mana crystals.", "Um jovem estudioso que se aprofunda na pesquisa de cristais de mana.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Guardian", "Guarda-joias", Language.BrazilianPortuguese);
            RegisterCard("Gem Guardian", "Guarda-joias", "The inverse of the Gem Detonator, this one seeks to protect all mox.", "O oposto do Estrondo de Joias. Este procura proteger todos os mox.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The inverse of the Gem Detonator, this one seeks to protect all mox.", "O oposto do Estrondo de Joias. Este procura proteger todos os mox.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gembound Ripper", "Ceifador Engastado", Language.BrazilianPortuguese);
            RegisterCard("Gembound Ripper", "Ceifador Engastado", "It is unstable, but such is the price for unending power.", "É instável, mas esse é o preço do poder sem fim.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is unstable, but such is the price for unending power.", "É instável, mas esse é o preço do poder sem fim.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Absorber", "Devorador de Joias", Language.BrazilianPortuguese);
            RegisterCard("Gem Absorber", "Devorador de Joias", "It seeks out to consume all mana within Mox to grow stronger.", "Procura consumir toda a mana dos mox para ficar mais forte.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seeks out to consume all mana within Mox to grow stronger.", "Procura consumir toda a mana dos mox para ficar mais forte.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skelemagus", "Magossada", Language.BrazilianPortuguese);
            RegisterCard("Skelemagus", "Magossada", "Great power for a few, fleeting moments..", "Grande poder por alguns breves instantes...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Great power for a few, fleeting moments..", "Grande poder por alguns breves instantes...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skelesage", "Sábio dos Ossos", Language.BrazilianPortuguese);
            RegisterCard("Skelesage", "Sábio dos Ossos", "One of my own Junior Sages, lost and revived.", "Um dos meus próprios Aprendizes de Sábio, perdido e revivido.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One of my own Junior Sages, lost and revived.", "Um dos meus próprios Aprendizes de Sábio, perdido e revivido.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Erratic Scholar", "Estudioso Errático", Language.BrazilianPortuguese);
            RegisterCard("Erratic Scholar", "Estudioso Errático", "A panicked scholar.. Always running from its problems..", "Um estudioso em pânico... Sempre fugindo dos próprios problemas...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A panicked scholar.. Always running from its problems..", "Um estudioso em pânico... Sempre fugindo dos próprios problemas...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Mage", "Mago Mox", Language.BrazilianPortuguese);
            RegisterCard("Mox Mage", "Mago Mox", "A Mox disguised as a mage.. It's not going to fool anyone.", "Um mox disfarçado de mago... Não vai enganar ninguém.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Mox disguised as a mage.. It's not going to fool anyone.", "Um mox disfarçado de mago... Não vai enganar ninguém.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aurumtact", "Toque de Ouro", Language.BrazilianPortuguese);
            RegisterCard("Aurumtact", "Toque de Ouro", "An elder scholar, cursed for his greed, entombing anything he touches in pure gold.", "Um estudioso idoso, amaldiçoado pela própria ganância, que sepulta em ouro puro tudo o que toca.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An elder scholar, cursed for his greed, entombing anything he touches in pure gold.", "Um estudioso idoso, amaldiçoado pela própria ganância, que sepulta em ouro puro tudo o que toca.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chained Mox", "Mox Acorrentado", Language.BrazilianPortuguese);
            RegisterCard("Chained Mox", "Mox Acorrentado", "A collection of 3 moxen, tangled together, combining their mana energy.", "Um conjunto de 3 mox entrelaçados, combinando sua energia de mana.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A collection of 3 moxen, tangled together, combining their mana energy.", "Um conjunto de 3 mox entrelaçados, combinando sua energia de mana.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maux", "Maux", Language.BrazilianPortuguese);
            RegisterCard("Maux", "Maux", "In all my years, I have NEVER seen an imitation cruder than this.", "Em todos os meus anos, NUNCA vi imitação mais tosca que esta.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In all my years, I have NEVER seen an imitation cruder than this.", "Em todos os meus anos, NUNCA vi imitação mais tosca que esta.", Language.BrazilianPortuguese);
            RegisterCard("Stim Mage", "Mago Estimulado", "It strives to grow stronger, disregarding its own wellbeing..", "Busca ficar mais forte, sem se importar com o próprio bem-estar...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It strives to grow stronger, disregarding its own wellbeing..", "Busca ficar mais forte, sem se importar com o próprio bem-estar...", Language.BrazilianPortuguese);
            RegisterCard("Gourmage", "Magourmand", "A gluttonous mage who devours the corpses of your fallen to grow stroner.. Disgusting.", "Um mago glutão que devora os cadáveres dos seus caídos para ficar mais forte... Repugnante.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A gluttonous mage who devours the corpses of your fallen to grow stroner.. Disgusting.", "Um mago glutão que devora os cadáveres dos seus caídos para ficar mais forte... Repugnante.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dunce", "Mago Tolo", Language.BrazilianPortuguese);
            RegisterCard("Dunce", "Mago Tolo", "This one can never seem to hit its target..", "Este parece nunca acertar o alvo...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This one can never seem to hit its target..", "Este parece nunca acertar o alvo...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grootslang", "Grootslang", Language.BrazilianPortuguese);
            RegisterCard("Grootslang", "Grootslang", "The mere graze of its fangs is enough to kill any creature. No matter the size.", "Basta um leve roçar das suas presas para matar qualquer criatura, não importa o tamanho.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The mere graze of its fangs is enough to kill any creature. No matter the size.", "Basta um leve roçar das suas presas para matar qualquer criatura, não importa o tamanho.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bookworm", "Traça-dos-livros", Language.BrazilianPortuguese);
            RegisterCard("Bookworm", "Traça-dos-livros", "A rare kind of insect that absorbs knowledge out of books.", "Um inseto raro que absorve conhecimento dos livros.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A rare kind of insect that absorbs knowledge out of books.", "Um inseto raro que absorve conhecimento dos livros.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alchemist", "Alquimista", Language.BrazilianPortuguese);
            RegisterCard("Alchemist", "Alquimista", "A supporting one. It brews potions to empower your cards.", "Um apoio. Prepara poções para fortalecer suas cartas.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A supporting one. It brews potions to empower your cards.", "Um apoio. Prepara poções para fortalecer suas cartas.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chime Mage", "Mago dos Sinos", Language.BrazilianPortuguese);
            RegisterCard("Chime Mage", "Mago dos Sinos", "Its chime can prove to be quite annoying..", "Seu tilintar pode ser bem irritante...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its chime can prove to be quite annoying..", "Seu tilintar pode ser bem irritante...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Revivor", "Ressurgido", Language.BrazilianPortuguese);
            RegisterCard("Revivor", "Ressurgido", "It brings a mage back from the dead, at the cost of its own health.", "Traz um mago de volta dos mortos ao custo da própria vida.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It brings a mage back from the dead, at the cost of its own health.", "Traz um mago de volta dos mortos ao custo da própria vida.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rune Mage", "Mago das Runas", Language.BrazilianPortuguese);
            RegisterCard("Rune Mage", "Mago das Runas", "It conjures explosive runes alongside it when summoned. Not a good idea, I must say.", "Quando é invocado, conjura runas explosivas ao seu lado. Devo dizer que não é uma boa ideia.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It conjures explosive runes alongside it when summoned. Not a good idea, I must say.", "Quando é invocado, conjura runas explosivas ao seu lado. Devo dizer que não é uma boa ideia.", Language.BrazilianPortuguese);
            RegisterCard("--~~--~~--", "--~~--~~--", "So it arrives.", "E assim chega.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So it arrives.", "E assim chega.", Language.BrazilianPortuguese);
            RegisterCard("~-~-~-~-~-~", "~-~-~-~-~-~", "I foresaw its arrival.", "Previ sua chegada.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I foresaw its arrival.", "Previ sua chegada.", Language.BrazilianPortuguese);
            RegisterCard("~~--~~--~~", "~~--~~--~~", "At last, it is here.", "Enfim, chegou.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At last, it is here.", "Enfim, chegou.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sniper Sage", "Sábio Atirador", Language.BrazilianPortuguese);
            RegisterCard("Sniper Sage", "Sábio Atirador", "A mage whose training allows it to cast spells from afar.", "Um mago cujo treinamento permite conjurar feitiços de longe.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mage whose training allows it to cast spells from afar.", "Um mago cujo treinamento permite conjurar feitiços de longe.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rune", "Runa", Language.BrazilianPortuguese);
            RegisterCard("Rune", "Runa", "This is the last call, for alcohol.", "Esta é a última chamada para bebidas alcoólicas.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is the last call, for alcohol.", "Esta é a última chamada para bebidas alcoólicas.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flame", "Chama Mágica", Language.BrazilianPortuguese);
            RegisterCard("Flame", "Chama Mágica", "This is the last call, for alcohol.", "Esta é a última chamada para bebidas alcoólicas.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is the last call, for alcohol.", "Esta é a última chamada para bebidas alcoólicas.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rabbit", "Coelho", Language.BrazilianPortuguese);
            RegisterCard("Rabbit", "Coelho", "This is the last call, for alcohol.", "Esta é a última chamada para bebidas alcoólicas.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is the last call, for alcohol.", "Esta é a última chamada para bebidas alcoólicas.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is the last call, for booze.", "Esta é a última chamada para a bebida.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is the last call, for ale.", "Esta é a última chamada para cerveja.", Language.BrazilianPortuguese);
            RegisterCard("Master Goranj", "Mestre Verdaranja", "The towering Master Goranj. Not only a caster of fearsome Magicks, but possessed of a sturdy poise as well.", "O imponente Mestre Verdaranja. Além de conjurar magias temíveis, possui uma postura firme.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The towering Master Goranj. Not only a caster of fearsome Magicks, but possessed of a sturdy poise as well.", "O imponente Mestre Verdaranja. Além de conjurar magias temíveis, possui uma postura firme.", Language.BrazilianPortuguese);
            RegisterCard("Master Bleene", "Mestre Azulerde", "The selfless Master Bleene. It shall help you in times of dire need… At the cost of its own ability to defend itself. Admirable.", "O altruísta Mestre Azulerde. Ele o ajudará na hora de maior necessidade... ao custo da própria capacidade de defesa. Admirável.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The selfless Master Bleene. It shall help you in times of dire need… At the cost of its own ability to defend itself. Admirable.", "O altruísta Mestre Azulerde. Ele o ajudará na hora de maior necessidade... ao custo da própria capacidade de defesa. Admirável.", Language.BrazilianPortuguese);
            RegisterCard("Master Orlu", "Mestra Laranul", "The great Master Orlu, soaring on pale wings, it attacks from above and draws in cards from below..", "A grande Mestra Laranul, que voa em asas pálidas, ataca do alto e atrai cartas de baixo...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The great Master Orlu, soaring on pale wings, it attacks from above and draws in cards from below..", "A grande Mestra Laranul, que voa em asas pálidas, ataca do alto e atrai cartas de baixo...", Language.BrazilianPortuguese);
            RegisterCard("Master Magnus", "Grande Mestre Magnus", "my name is.. Shake-Zula! The Mic rula! The Old Schoola! You want a trip? I'll bring it to ya...", "Meu nome é... Shake-Zula! Rei do microfone! Da velha escola! Quer uma viagem? Eu levo até você...");
