            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flood", "Inundação", Language.BrazilianPortuguese);
            RegisterCard("Flood", "Inundação", "When used, it will summon a tsunami that wipes away the sigils of every card on the board.", "Ao ser usado, invoca um tsunami que apaga os selos de todas as cartas no tabuleiro.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When used, it will summon a tsunami that wipes away the sigils of every card on the board.", "Ao ser usado, invoca um tsunami que apaga os selos de todas as cartas no tabuleiro.", Language.BrazilianPortuguese);
