            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The spirit of the brave Master Bleene.", "O espírito do corajoso Mestre Azulerde.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fireball", "Bola de Fogo", Language.BrazilianPortuguese);
            RegisterCard("Fireball", "Bola de Fogo", "Conjure up a fireball, and shoot it towards your enemy.", "Conjure uma bola de fogo e dispare-a contra o inimigo.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Conjure up a fireball, and shoot it towards your enemy.", "Conjure uma bola de fogo e dispare-a contra o inimigo.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Potion", "Poção", Language.BrazilianPortuguese);
            RegisterCard("Potion", "Poção", "Conjure up a fireball, and shoot it towards your enemy.", "Conjure uma bola de fogo e dispare-a contra o inimigo.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Conjure up a fireball, and shoot it towards your enemy.", "Conjure uma bola de fogo e dispare-a contra o inimigo.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gnome", "Gnomo", Language.BrazilianPortuguese);
