            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "joem", "joem", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scuba Gnome", "Gnomo Mergulhador", Language.BrazilianPortuguese);
