            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Huber", "Huber", Language.BrazilianPortuguese);
            RegisterCard("Free Legs", "Pernas Livres", "", "");
