            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death Knight, the assassin in hell.", "Cavaleiro da Morte, o assassino do inferno.", Language.BrazilianPortuguese);
