            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Ferry Crow", "Corvo Barqueiro Desperto", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The mournful cry of looking down upon the undead after death.", "O grito de lamento de quem, após a morte, observa os mortos-vivos do alto.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grave", "Sepultura", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I hope no one will disturb it.", "Espero que ninguém o perturbe.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Headless Man", "Homem sem Cabeça", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An incompetent headless person, as if searching for something he had lost.", "Um incompetente sem cabeça, como se procurasse algo que perdeu.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Kennel", "Canil Desperto", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A dog house, hopefully no one will mess with the things inside.", "Uma casinha de cachorro. Espero que ninguém mexa no que há dentro.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pharmacist", "Farmacêutico", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Pharmacist", "Farmacêutico Desperto", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A dead pharmacist who poisons all creations that oppose him.", "Um farmacêutico morto que envenena todas as criações que se opõem a ele.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeleader", "Esquelelíder", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A skeleton leader, once on stage, is surrounded by skeletons.", "Um líder esqueleto que, ao entrar em cena, é cercado de esqueletos.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Skeleader", "Esquelelíder Desperto", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeleton Sniper", "Atirador Esqueleto", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A dead sniper.", "Um atirador morto.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Skeleton Sniper", "Atirador Esqueleto Desperto", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Threaded Skeleton", "Esqueleto de Fios", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Some people are born puppets, while others still control others after death.", "Algumas pessoas já nascem marionetes, enquanto outras continuam controlando os outros mesmo após a morte.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Threaded Skeleton", "Esqueleto de Fios Desperto", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undead Elk", "Alce Morto-vivo", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The undead elk, a former husk of of what it once was.", "O alce morto-vivo, uma casca do que um dia foi.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undead Elk Cub", "Filhote de Alce Morto-vivo", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even death carries vitality and desire.", "Mesmo na morte, carrega vitalidade e desejo.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undead Moose", "Alce-gigante Morto-vivo", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A rotting carcass of a long-departed imposing beast.", "A carcaça apodrecida de uma fera imponente que morreu há muito tempo.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Undead Moose", "Alce-gigante Morto-vivo Desperto", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undead Predator", "Predador Morto-vivo", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warriors who die in war will never bow down.", "Guerreiros que morrem na guerra nunca se curvam.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Undead Predator", "Predador Morto-vivo Desperto", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undead RedHart", "Cervo-vermelho Morto-vivo", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "its decaying mind retains the strength of sacrifice.", "Sua mente em decomposição conserva a força do sacrifício.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Undead RedHart", "Cervo-vermelho Morto-vivo Desperto", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undead Snapper", "Restos de Tartaruga-mordedora", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Undead Snapper", "Restos de Tartaruga-mordedora Despertos", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The corpse of a stiff terrestrial creation.", "O cadáver de uma criação terrestre enrijecida.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeleton Dragon", "Dragão Esqueleto", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeleton Dragon, its remaining skeletons still roar with the destructive fury of old.", "Dragão Esqueleto. Seus ossos remanescentes ainda rugem com a fúria destrutiva de outrora.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Skeleton Dragon", "Dragão Esqueleto Desperto", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Free Revenant", "Espírito Livre", Language.BrazilianPortuguese);
