            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeleader", "Esquelelíder", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When placing [creature], skeleton cards will appear in nearby empty spaces. Skeleton has: 1 power, 1 health, Brittle.", "Ao colocar [creature], cartas de Esqueleto aparecem nos espaços vazios adjacentes. O Esqueleto tem: 1 de poder, 1 de vida e Fragilidade.", Language.BrazilianPortuguese);
