            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The cards for the Undead Tribe are in the original game.(ACT2)", "As cartas da tribo dos mortos-vivos estão no jogo original. (ATO 2)", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NonOriginal Undead Card", "Pacote de Mortos-vivos Não Originais", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The expansion cards for the Undead Tribe are not in the original game.", "As cartas de expansão da tribo dos mortos-vivos não estão no jogo original.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The cards for the Undead Tribe are in the ACT2 original game, It contains [count] cards.", "As cartas da tribo dos mortos-vivos estão no ATO 2 do jogo original. Contém [count] cartas.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The expansion cards for the Undead Tribe are not in the original game, It contains [count] cards.", "As cartas de expansão da tribo dos mortos-vivos não estão no jogo original. Contém [count] cartas.", Language.BrazilianPortuguese);

        }
