    public class CustomSideDeckMod
    {

        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for CustomSideDeck Mod");
            // Config
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How the mod should handle side deck card backs for side decks that don't add their own custom card back. If enabled, automatically generates a unique card back based on the side deck's main card's portrait. Otherwise, the default squirrel back will be used.", "Como o mod deve tratar os versos de cartas de baralhos secundários que não fornecem um verso personalizado. Se ativado, gera automaticamente um verso único com base no retrato da carta principal do baralho secundário. Caso contrário, usa o verso padrão de esquilo.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whether to automatically add an Aqua version of all custom side decks. Buggy, not recommended.", "Se deve adicionar automaticamente uma versão aquática de todos os baralhos secundários personalizados. Tem erros; não recomendado.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whether or not Aquasquirrels and custom side decks marked as `CSDIsAqua` should be shown as options even when the Squirrel Fish challenge isn't on.", "Se Esquilaquáticos e baralhos secundários personalizados marcados como `CSDIsAqua` devem aparecer como opções mesmo sem o desafio Peixe-esquilo ativado.", Language.BrazilianPortuguese);

            // ShowText
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select Side Deck", "Selecionar Baralho Secundário", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Configure Side Deck", "Configurar Baralho Secundário", Language.BrazilianPortuguese);
            for (int point = 0; point <= 100; point++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CURRENT SIDE DECK: <color=#eef4c6>" + point.ToString() + "</color> Challenge Points", "BARALHO SECUNDÁRIO ATUAL: <color=#eef4c6>" + point.ToString() + "</color> Pontos de Desafio", Language.BrazilianPortuguese);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CURRENT SIDE DECK: <color=#eef4c6>+" + point.ToString() + "</color> Challenge Points", "BARALHO SECUNDÁRIO ATUAL: <color=#eef4c6>+" + point.ToString() + "</color> Pontos de Desafio", Language.BrazilianPortuguese);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Total Challenge Points: <color=#eef4c6>" + point.ToString() + "</color>", "Total de Pontos de Desafio: <color=#eef4c6>" + point.ToString() + "</color>", Language.BrazilianPortuguese);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "\nContains {0} cards", "\nContém {0} cartas", Language.BrazilianPortuguese); // todo

        }
    }

    public class PackManagementMod
    {

        public static Dictionary<string, string> EncountersTitle = new();
        public static Dictionary<string, KeyValuePair<string, string>> EncountersDescription = new();

        public static void RegisterEncounter(string en, string zh, string endes, string zhdes)
        {
            EncountersTitle.Add(en, zh);
            EncountersDescription.Add(en, new KeyValuePair<string, string>(endes, zhdes));
        }
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for PackManagement Mod");
            // SetText
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select Card Packs", "Selecionar Pacotes de Cartas", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select Encounter Packs", "Selecionar Pacotes de Encontros", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose Active Packs", "Escolher Pacotes Ativos", Language.BrazilianPortuguese);

            // Packs
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inscryption: Beastly Card Expansion Pack", "Inscryption: Pacote de Expansão de Cartas de Feras", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The original set of cards featured in Leshy's cabin. Featuring wolves, mantises, and the occasional cockroach.", "O conjunto original de cartas da cabana de Leshy. Inclui lobos, louva-a-deus e uma ou outra barata.", Language.BrazilianPortuguese);
            RegisterEncounter("Inscryption: Beastly Card Expansion Pack", "Inscryption: Pacote de Expansão de Cartas de Feras", "The original set of cards featured in Leshy's cabin. Featuring wolves, mantises, and the occasional cockroach.", "O conjunto original de cartas da cabana de Leshy. Inclui lobos, louva-a-deus e uma ou outra barata.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inscryption: Techno Card Expansion Pack", "Inscryption: Pacote de Expansão de Cartas Tecnológicas", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The original set of robotic cards, exclusively using the energy mechanic.", "O conjunto original de cartas robóticas que usam exclusivamente a mecânica de energia.", Language.BrazilianPortuguese);
            RegisterEncounter("Inscryption: Techno Card Expansion Pack", "Inscryption: Pacote de Expansão de Cartas Tecnológicas", "The original set of robotic cards, exclusively using the energy mechanic.", "O conjunto original de cartas robóticas que usam exclusivamente a mecânica de energia.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inscryption: Undead Card Expansion Pack", "Inscryption: Pacote de Expansão de Cartas de Mortos-vivos", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GrimoraMod", "GrimoraMod", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Powered by the bones of the dead, these cards have come back from the grave to fight for you.", "Movidas pelos ossos dos mortos, estas cartas voltaram do túmulo para lutar por você.", Language.BrazilianPortuguese);
            RegisterEncounter("Inscryption: Undead Card Expansion Pack", "Inscryption: Pacote de Expansão de Cartas de Mortos-vivos", "Powered by the bones of the dead, these cards have come back from the grave to fight for you.", "Movidas pelos ossos dos mortos, estas cartas voltaram do túmulo para lutar por você.");
            RegisterEncounter("GrimoraMod", "GrimoraMod", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inscryption: Magickal Card Expansion Pack", "Inscryption: Pacote de Expansão de Cartas Mágicas", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Harness the might of the moxen to summon forth apprentices and fight in the most honorable of duels.", "Domine o poder dos mox para invocar aprendizes e travar os mais honrados duelos.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Harness the might of the moxen to summon forth apprentices and fight in the most honorable of duels. (Magnificus Mod Cards)", "Domine o poder dos mox para invocar aprendizes e travar os mais honrados duelos. (Cartas do Mod de Magnificus)", Language.BrazilianPortuguese);
            RegisterEncounter("Inscryption: Magickal Card Expansion Pack", "Inscryption: Pacote de Expansão de Cartas Mágicas", "Harness the might of the moxen to summon forth apprentices and fight in the most honorable of duels.", "Domine o poder dos mox para invocar aprendizes e travar os mais honrados duelos.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Miscellaneous Community Cards", "Cartas Diversas da Comunidade", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The unusual, unsorted, and unruly cards that have been added by mods but not properly sorted into packs.", "Cartas incomuns, desorganizadas e indisciplinadas adicionadas por mods, mas sem a classificação adequada em pacotes.", Language.BrazilianPortuguese);
            RegisterEncounter("Miscellaneous Community Cards", "Cartas Diversas da Comunidade", "The unusual, unsorted, and unruly cards that have been added by mods but not properly sorted into packs.", "Cartas incomuns, desorganizadas e indisciplinadas adicionadas por mods, mas sem a classificação adequada em pacotes.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inscryption: Beastly Encounters", "Inscryption: Encontros com Feras", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The original set of [summary] that Leshy has carefully curated for the ideal gaming experience.", "O conjunto original de [summary] cuidadosamente preparado por Leshy para a experiência de jogo ideal.", Language.BrazilianPortuguese);
            RegisterEncounter("Inscryption: Beastly Encounters", "Inscryption: Encontros com Feras", "The original set of [summary] that Leshy has carefully curated for the ideal gaming experience.", "O conjunto original de [summary] cuidadosamente preparado por Leshy para a experiência de jogo ideal.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unsorted Regions and Encounters", "Regiões e Encontros Não Classificados", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "These [summary] have been added by mods but not properly sorted into packs.", "Estes [summary] foram adicionados por mods, mas não foram classificados corretamente em pacotes.", Language.BrazilianPortuguese);
            RegisterEncounter("Unsorted Regions and Encounters", "Regiões e Encontros Não Classificados", "These [summary] have been added by mods but not properly sorted into packs.", "Estes [summary] foram adicionados por mods, mas não foram classificados corretamente em pacotes.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eri Card Expansion", "Expansão de Cartas de Eri", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "From the [randomcard] to the [randomcard], this pack contains [count] wild animals that feel right at home in the wild world of Inscryption.", "De [randomcard] a [randomcard], este pacote contém [count] animais selvagens que se sentem em casa no mundo indomado de Inscryption.", Language.BrazilianPortuguese); // todo
            RegisterEncounter("Eri Card Expansion", "Expansão de Cartas de Eri", "From the [randomcard] to the [randomcard], this pack contains [count] wild animals that feel right at home in the wild world of Inscryption.", "De [randomcard] a [randomcard], este pacote contém [count] animais selvagens que se sentem em casa no mundo indomado de Inscryption.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ara's Card Expansion", "Expansão de Cartas de Ara", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This expansion contains [count] cards that offer a unique twist on Inscryption's core gameplay. Cards like [randomcard] and [randomcard] will give a little additional spice to your next run.", "Esta expansão contém [count] cartas que dão um toque único à jogabilidade central de Inscryption. Cartas como [randomcard] e [randomcard] trarão um tempero a mais à sua próxima partida.", Language.BrazilianPortuguese); // todo
            RegisterEncounter("Ara's Card Expansion", "Expansão de Cartas de Ara", "This expansion contains [count] cards that offer a unique twist on Inscryption's core gameplay. Cards like [randomcard] and [randomcard] will give a little additional spice to your next run.", "Esta expansão contém [count] cartas que dão um toque único à jogabilidade central de Inscryption. Cartas como [randomcard] e [randomcard] trarão um tempero a mais à sua próxima partida.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hallownest Expansion", "Expansão de Hallownest", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A large expansion containing [count] creatures from Hollow Knight. Up from peaceful Crossroads, down into the Abyss.", "Uma grande expansão com [count] criaturas do jogo Hollow Knight. Da pacífica Encruzilhada às profundezas do Abismo.", Language.BrazilianPortuguese); // todo
            RegisterEncounter("Hallownest Expansion", "Expansão de Hallownest", "A large expansion containing [count] creatures from Hollow Knight. Up from peaceful Crossroads, down into the Abyss.", "Uma grande expansão com [count] criaturas do jogo Hollow Knight. Da pacífica Encruzilhada às profundezas do Abismo.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bitty's Regions", "Regiões de Bitty", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bitty's Regions adds [summary].", "Regiões de Bitty adiciona [summary].", Language.BrazilianPortuguese);
            RegisterEncounter("Bitty's Regions", "Regiões de Bitty", "Bitty's Regions adds [summary].", "Regiões de Bitty adiciona [summary].");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Void Region Expansion", "Expansão da Região do Vazio", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This region expansion from Void adds [summary].", "Esta expansão de regiões do Vazio adiciona [summary].", Language.BrazilianPortuguese);
            RegisterEncounter("Void Region Expansion", "Expansão da Região do Vazio", "This region expansion from Void adds [summary].", "Esta expansão de regiões do Vazio adiciona [summary].");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eri's Card Pack Encounters", "Encontros de Pacotes de Eri", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This expansion adds [summary] featuring cards from Eri's Card Expansion.", "Esta expansão adiciona [summary] com cartas da Expansão de Cartas de Eri.", Language.BrazilianPortuguese);
            RegisterEncounter("Eri's Card Pack Encounters", "Encontros de Pacotes de Eri", "This expansion adds [summary] featuring cards from Eri's Card Expansion.", "Esta expansão adiciona [summary] com cartas da Expansão de Cartas de Eri.");
            RegisterEncounter("Original Undead Card", "Carta Original de Morto-vivo", "The cards for the Undead Tribe are in the original game.(ACT2)", "As cartas da tribo dos mortos-vivos estão no jogo original. (ATO 2)"); // UndeadTempleINKCM
            RegisterEncounter("NonOriginal Undead Card", "Pacote de Mortos-vivos Não Originais", "The expansion cards for the Undead Tribe are not in the original game.", "As cartas de expansão da tribo dos mortos-vivos não estão no jogo original."); // UndeadTempleINKCM
            RegisterEncounter("Wilderness Legend", "Lenda da Natureza Selvagem", "Add some simple cards based on the original imprint.", "Adiciona algumas cartas simples com base nos selos originais."); // WildernessLegend
            RegisterEncounter("DLC_Fairy_Tale", "DLC Contos da Natureza: Contos de Fadas", "Added some cards based on myths, legends, and fictional elements.", "Adiciona algumas cartas baseadas em mitos, lendas e elementos fictícios."); // WildernessLegend
