    public class MagicExpansionMod
    {

        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for MagicExpansion Mod");
            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Angry Witch", "Bruxa da Ira", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Angry Witch", "Bruxa da Ira", "The witch in charge of anger will ignite flames in the opposite battlefield.", "A bruxa que comanda a ira acenderá chamas no campo de batalha adversário.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch in charge of anger will ignite flames in the opposite battlefield.", "A bruxa que comanda a ira acenderá chamas no campo de batalha adversário.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Arrogant Witch", "Bruxa da Soberba", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Arrogant Witch", "Bruxa da Soberba", "The witch who mastered the power of arrogance appeared with the demon.", "A bruxa que dominou o poder da arrogância apareceu com o demônio.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch who mastered the power of arrogance appeared with the demon.", "A bruxa que dominou o poder da arrogância apareceu com o demônio.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coffee Mage", "Mago do Café", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Coffee Mage", "Mago do Café", "Mages who love coffee use gems to regulate their breath.", "Magos que adoram café usam joias para regular a respiração.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mages who love coffee use gems to regulate their breath.", "Magos que adoram café usam joias para regular a respiração.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Funny MagiChiking", "Galinha Mágica Engraçada", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Funny MagiChiking", "Galinha Mágica Engraçada", "A smelly Rooster who has learned magic.", "Um galo fedido que aprendeu magia.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A smelly Rooster who has learned magic.", "Um galo fedido que aprendeu magia.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gluttonous Witch", "Bruxa da Gula", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Gluttonous Witch", "Bruxa da Gula", "The witch in charge of gluttony committed a terrible sin.", "A bruxa que comanda a gula cometeu um pecado terrível.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch in charge of gluttony committed a terrible sin.", "A bruxa que comanda a gula cometeu um pecado terrível.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greedy Witch", "Bruxa da Ganância", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Greedy Witch", "Bruxa da Ganância", "The witch who controls the power of greed, unfortunately, can only bring value to us after death.", "A bruxa que controla o poder da ganância, infelizmente, só nos traz valor após a morte.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch who controls the power of greed, unfortunately, can only bring value to us after death.", "A bruxa que controla o poder da ganância, infelizmente, só nos traz valor após a morte.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inquisitive Witch", "Bruxa da Avidez", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Inquisitive Witch", "Bruxa da Avidez", "Nothing is more powerful than her curiosity.", "Nada é mais poderoso que a curiosidade dela.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nothing is more powerful than her curiosity.", "Nada é mais poderoso que a curiosidade dela.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jealous Witch", "Bruxa da Inveja", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Jealous Witch", "Bruxa da Inveja", "The witch in charge of jealousy has powerful magic and power.", "A bruxa que comanda a inveja possui magia e poder formidáveis.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch in charge of jealousy has powerful magic and power.", "A bruxa que comanda a inveja possui magia e poder formidáveis.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lazy Witch", "Bruxa da Preguiça", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Lazy Witch", "Bruxa da Preguiça", "The witch in charge of the power of laziness is really a lazy guy.", "A bruxa que controla o poder da preguiça é mesmo preguiçosa.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch in charge of the power of laziness is really a lazy guy.", "A bruxa que controla o poder da preguiça é mesmo preguiçosa.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lust Witch", "Bruxa da Luxúria", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Lust Witch", "Bruxa da Luxúria", "The witch in charge of lust, don't look into her eyes.", "A bruxa que comanda a luxúria. Não olhe nos olhos dela.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch in charge of lust, don't look into her eyes.", "A bruxa que comanda a luxúria. Não olhe nos olhos dela.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nine Color Deer", "Cervo de Nove Cores", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Nine Color Deer", "Cervo de Nove Cores", "The colorful nine color deer has precious value.", "O colorido cervo de nove cores tem um valor precioso.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The colorful nine color deer has precious value.", "O colorido cervo de nove cores tem um valor precioso.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stinky MagiChiking", "Franguinho Mágico Fedido", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Stinky MagiChiking", "Franguinho Mágico Fedido", "Hatched by magic eggs.", "Nascido de ovos mágicos.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hatched by magic eggs.", "Nascido de ovos mágicos.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bomb Maniac", "Maníaco das Bombas", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Bomb Maniac", "Maníaco das Bombas", "Even if it detonates itself, it never surrenders to others.", "Mesmo que se exploda, jamais se rende aos outros.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even if it detonates itself, it never surrenders to others.", "Mesmo que se exploda, jamais se rende aos outros.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Earl Bunny", "Coelho Conde", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Earl Bunny", "Coelho Conde", "The versatile Earl Bunny, not everyone can comprehend this art.", "O versátil Coelho Conde. Nem todos compreendem essa arte.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The versatile Earl Bunny, not everyone can comprehend this art.", "O versátil Coelho Conde. Nem todos compreendem essa arte.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chinese Loong", "Dragão Chinês", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Chinese Loong", "Dragão Chinês", "Diving into the abyss will bring peace to the four seas, flying will protect all things and bring peace, and the dragon's journey of thousands of miles is a sign of good fortune.", "Ao mergulhar no abismo, acalma os quatro mares; ao voar, protege todas as coisas e traz paz. A jornada de mil léguas do dragão é sinal de boa sorte.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Diving into the abyss will bring peace to the four seas, flying will protect all things and bring peace, and the dragon's journey of thousands of miles is a sign of good fortune.", "Ao mergulhar no abismo, acalma os quatro mares; ao voar, protege todas as coisas e traz paz. A jornada de mil léguas do dragão é sinal de boa sorte.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cheese Wizard", "Mago do Queijo", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Cheese Wizard", "Mago do Queijo", "A humorous wizard who is proficient in cooking, his cheese has magical power.", "Um mago bem-humorado e mestre na cozinha. Seu queijo tem poderes mágicos.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A humorous wizard who is proficient in cooking, his cheese has magical power.", "Um mago bem-humorado e mestre na cozinha. Seu queijo tem poderes mágicos.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frost Golem", "Golem de Gelo", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Frost Golem", "Golem de Gelo", "Once on the field, there is a strong sense of oppression.", "Assim que entra no tabuleiro, causa uma forte sensação de opressão.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once on the field, there is a strong sense of oppression.", "Assim que entra no tabuleiro, causa uma forte sensação de opressão.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baseball Mage", "Mago do Beisebol", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Baseball Mage", "Mago do Beisebol", "His soul is bound under sportswear and can never be liberated.", "Sua alma está presa sob roupas esportivas e jamais poderá se libertar.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "His soul is bound under sportswear and can never be liberated.", "Sua alma está presa sob roupas esportivas e jamais poderá se libertar.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Raid Mage", "Mago da Incursão", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Raid Mage", "Mago da Incursão", "You will understand how terrifying it is for a robber to master magic.", "Você entenderá como é aterrorizante um ladrão dominar a magia.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You will understand how terrifying it is for a robber to master magic.", "Você entenderá como é aterrorizante um ladrão dominar a magia.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jade Turtle", "Tartaruga de Jade", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Jade Turtle", "Tartaruga de Jade", "A turtle draped in emeralds from head to toe—I can't help but marvel that such a painting even exists.", "Uma tartaruga coberta de esmeraldas da cabeça aos pés. Não posso deixar de me maravilhar com a existência de tal pintura.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A turtle draped in emeralds from head to toe—I can't help but marvel that such a painting even exists.", "Uma tartaruga coberta de esmeraldas da cabeça aos pés. Não posso deixar de me maravilhar com a existência de tal pintura.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magic Cheese", "Queijo Mágico", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Magic Cheese", "Queijo Mágico", "", "");
