            MagnificusMod.RegisterCard("Scarlet Cuckoo", "Cuco Escarlate", "The success or failure of the angry magic bird often depends on its face.", "O sucesso ou fracasso do pássaro mágico furioso costuma depender de sua expressão.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The success or failure of the angry magic bird often depends on its face.", "O sucesso ou fracasso do pássaro mágico furioso costuma depender de sua expressão.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spear Apprentice", "Aprendiz da Lança", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Spear Apprentice", "Aprendiz da Lança", "Apprentices of Spear Mages, wise people will leave behind their backs to prepare.", "Aprendizes de Magos da Lança. Os sábios sempre deixam um plano de reserva preparado.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Apprentices of Spear Mages, wise people will leave behind their backs to prepare.", "Aprendizes de Magos da Lança. Os sábios sempre deixam um plano de reserva preparado.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Eye of Darkness", "O Olho da Escuridão", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("The Eye of Darkness", "O Olho da Escuridão", "This precious pearl was once the devil's eye.", "Esta pérola preciosa já foi o olho do diabo.");
