            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MoxShield", "Escudo Mox", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("MoxShield", "Escudo Mox", "A magic shield inlaid with gemstones always provides a sense of security with its presence.", "Um escudo mágico incrustado de joias sempre traz uma sensação de segurança com sua presença.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A magic shield inlaid with gemstones always provides a sense of security with its presence.", "Um escudo mágico incrustado de joias sempre traz uma sensação de segurança com sua presença.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nebula Storm", "Tempestade Nebulosa", Language.BrazilianPortuguese);
