            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps you need more card assistance, and a soul contract is a great choice.", "Talvez você precise de mais ajuda das cartas. Um contrato de alma é uma ótima escolha.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wailing Wall", "Muro das Lamentações", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Wailing Wall", "Muro das Lamentações", "Such perseverance even moves the thorny walls to weep.", "Tal perseverança faz até as paredes de espinhos chorarem.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such perseverance even moves the thorny walls to weep.", "Tal perseverança faz até as paredes de espinhos chorarem.", Language.BrazilianPortuguese);
            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coffee Time", "Hora do Café", Language.BrazilianPortuguese);
            MagnificusMod.RegisterAbility("Coffee Time", "Hora do Café");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] receives the first damage, it gains 2 strength.", "Quando [creature] sofre dano pela primeira vez, ganha 2 de poder.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death of Arrogance", "Morte da Soberba", Language.BrazilianPortuguese);
            MagnificusMod.RegisterAbility("Death of Arrogance", "Morte da Soberba");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, adjacent cards gain 2 power.", "Quando [creature] morre, as cartas adjacentes ganham 2 de poder.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death of Greed", "Morte da Ganância", Language.BrazilianPortuguese);
            MagnificusMod.RegisterAbility("Death of Greed", "Morte da Ganância");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, adjacent cards gain 3 health.", "Quando [creature] morre, as cartas adjacentes ganham 3 de vida.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "God Made", "Criação Divina", Language.BrazilianPortuguese);
            MagnificusMod.RegisterAbility("God Made", "Criação Divina");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a Homunculus is created on each empty adjacent space. The Homunculus has : 1 power, 1 health, Familiar.", "Quando [creature] é jogado, um Homúnculo é criado em cada espaço vazio adjacente. O Homúnculo tem: 1 de poder, 1 de vida e Familiar.", Language.BrazilianPortuguese);
            MagnificusMod.RegisterAbility("Fir Caller", "Invocador de Abetos");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, the empty slot on the cardholder's side is filled with Great Firs. Great Fir has: 0 Power, 3 Health, Mighty Leap.", "Quando [creature] morre, os espaços vazios do lado do dono são preenchidos por Grandes Abetos. O Grande Abeto tem: 0 de poder, 3 de vida e Salto Pujante.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lingering Taste", "Sabor Persistente", Language.BrazilianPortuguese);
            MagnificusMod.RegisterAbility("Lingering Taste", "Sabor Persistente");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, adjacent cards gain 1 health.", "Quando [creature] morre, as cartas adjacentes ganham 1 de vida.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Love of Cheese", "Amor ao Queijo", Language.BrazilianPortuguese);
            MagnificusMod.RegisterAbility("Love of Cheese", "Amor ao Queijo");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, draw a cheese card, cheese has: 0 power, 2 health,Lingering Taste.", "Quando [creature] é jogado, compre uma carta de Queijo. O Queijo tem: 0 de poder, 2 de vida e Sabor Persistente.", Language.BrazilianPortuguese);
            // Other
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magic Expansion", "Expansão Mágica", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here comes the card of the fantasy world! More content will be added in the future!", "Aqui vêm as cartas do mundo da fantasia! Mais conteúdo será adicionado no futuro!", Language.BrazilianPortuguese);
        }
