            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "for now.", "por enquanto.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the ouroboros only grows stronger from death.", "o ouroboros só fica mais forte com a morte.", Language.BrazilianPortuguese);
