            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "what glittering wool,", "que lã reluzente,", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "attached to such a rare creature.", "em uma criatura tão rara.", Language.BrazilianPortuguese);
