            // Consumable
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please! You've got to help me get out of here!", "Por favor! Você precisa me ajudar a sair daqui!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thank you! I hope he doesn't notice me here...", "Obrigado! Espero que ele não me perceba aqui...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thank you!", "Obrigado!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So much power, but so much pain...", "Tanto poder, mas tanta dor...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good riddance to that little freak.", "Ainda bem que nos livramos daquele monstrinho.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Goobert", "Goobert", Language.BrazilianPortuguese);
            RegisterConsumable("Goobert", "Goobert");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please! You've got to help me get out of here!", "Por favor! Você precisa me ajudar a sair daqui!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Data Cube", "Cubo de Dados", Language.BrazilianPortuguese);
            RegisterConsumable("Data Cube", "Cubo de Dados");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Can be placed on the scales for some damage, if you're into that sort of thing.", "Pode ser colocado na balança para causar algum dano, se você gosta desse tipo de coisa.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Laser Rifle", "Rifle Laser", Language.BrazilianPortuguese);
            RegisterConsumable("Laser Rifle", "Rifle Laser");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This will give one of your cards the Sniper sigil for the rest of the battle. It's a gun - what else do you want?", "Concede a uma de suas cartas o selo Tiro de Precisão pelo resto da batalha. É uma arma — o que mais você quer?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amplification Coil", "Bobina de Amplificação", Language.BrazilianPortuguese);
            RegisterConsumable("Amplification Coil", "Bobina de Amplificação");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Increases your max energy by 2. I suppose you can find some use for this.", "Aumenta sua energia máxima em 2. Acho que você pode encontrar alguma utilidade para isto.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "UFO", "OVNI", Language.BrazilianPortuguese);
            RegisterConsumable("UFO", "OVNI");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Abducts a card of your choice. It gets the job done I suppose", "Abduz uma carta à sua escolha. Acho que resolve o problema.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wiseclock", "Dextrogiro", Language.BrazilianPortuguese);
            RegisterConsumable("Wiseclock", "Dextrogiro");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It rotates the board clockwise or something. I stole it from Leshy. Do you think he'll notice?", "Gira o tabuleiro no sentido horário ou algo assim. Roubei de Leshy. Será que ele vai perceber?", Language.BrazilianPortuguese);

            // Rule
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I play a Mr:Clock", "Eu jogo um Relógio:Sr.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a random card becomes a fish", "uma carta aleatória se torna um peixe", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "1 of your lanes catches fire", "1 de suas colunas pega fogo", Language.BrazilianPortuguese);

            // Mode
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Traps", "Armadilhas", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems there are some [c:bR]traps[c:] here", "Parece que há [c:bR]armadilhas[c:] aqui", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your bots will have to fight past them to get to me", "Seus robôs terão de passar por elas para chegar até mim", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Random Rule", "Regra Aleatória", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "For this battle, I'm going to add an additional rule.", "Nesta batalha, vou adicionar uma regra extra.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Conveyor", "Esteira Transportadora", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It appears someone activated the [c:bR]conveyor belt[c:]", "Parece que alguém ativou a [c:bR]esteira transportadora[c:]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cards will rotate clockwise every turn", "As cartas girarão no sentido horário a cada turno", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Explosive", "Explosivo", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hm; it looks like the cards in this battle will [c:bR]explode[c:] when they die", "Hum; parece que as cartas nesta batalha vão [c:bR]explodir[c:] ao morrer", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That seems dangerous", "Isso parece perigoso", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stickers", "Adesivos", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "See those [c:bR]stickers[c:]? They give my cards extra abilities.", "Vê esses [c:bR]adesivos[c:]? Eles dão habilidades extras às minhas cartas.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You don't mind an extra challenge, do you?", "Você não se importa com um desafio a mais, não é?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Missiles", "Mísseis", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh, there appears to be a malfunctioning missile launcher here", "Ah, parece que há um lançador de mísseis com defeito aqui", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Watch out for rogue missile strikes I guess", "Cuidado com mísseis desgovernados, eu acho", Language.BrazilianPortuguese);

            // Challenge
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Final Boss", "Chefe final", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Description for the Final Boss challenge", "Descrição do desafio do Chefe Final", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Missing Remote", "Controle Remoto Perdido", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You do not start with Mrs. Bomb's Remote", "Você não começa com o Controle Remoto da Sra. Bomba", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Turbo Vessels", "Recipientes Turbo", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your vessels have the Double Sprinter sigil.", "Seus Recipientes têm o selo Corredor Duplo.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Broken Bridges", "Pontes Quebradas", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Only two regions are available at the start of each run", "Apenas duas regiões estão disponíveis no início de cada partida", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pricey Upgrades", "Melhorias Caras", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All upgrades cost more", "Todas as melhorias custam mais", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eccentric Painter", "Pintor Excêntrico", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All bosses start with a random canvas rule.", "Todos os chefes começam com uma regra de tela aleatória.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Energy Hammer", "Martelo de Energia", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The hammer now costs 2 energy to use", "Agora é preciso gastar 2 de energia para usar o martelo", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Costly Respawn", "Ressurgimento Caro", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The cost for additional respawns is tripled", "O custo de ressurgimentos adicionais é triplicado", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leaping Side Deck", "Baralho Secundário Saltitante", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Replace your Empty Vessels with L33pbots.", "Substitua seus Recipientes Vazios por L33pB0ts.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wanted Fugitive", "Fugitivo Procurado", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your bounty level is permanently increased by 2", "Seu nível de recompensa é aumentado permanentemente em 2", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strange Encounters", "Encontros Estranhos", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Some battles on each map will have additional effects", "Algumas batalhas em cada mapa terão efeitos adicionais", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Great Transcendence", "Suma Transcendência", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unlock the secrets of the Great Transcendence", "Descubra os segredos da Suma Transcendência", Language.BrazilianPortuguese);

            // SetText
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ENTER NAME HERE", "INSIRA O NOME AQUI", Language.BrazilianPortuguese);
            for (int count = 0; count <= 100; count++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Redraw: $" + count.ToString(), "Nova compra: $" + count.ToString(), Language.BrazilianPortuguese);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sell Token: " + count.ToString() + " Robobucks", "Vender ficha: " + count.ToString() + " robotostões", Language.BrazilianPortuguese);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reset: $1", "Redefinir: $1", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PRINT", "IMPRIMIR", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "RECALL", "RECOLHER", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TKN", "FICHA", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TKN++", "Ficha++", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "RARE", "RARO", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "RARE++", "RARO++", Language.BrazilianPortuguese);

            // Achievement
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "P03 In Kaycee's Mod", "P03 no Mod da Kaycee", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Uber Apocalypse", "Apocalipse Supremo", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beat \"P03 in Kaycee's Mod\" for the first time", "Vença «P03 no Mod da Kaycee» pela primeira vez", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scarlet Skull", "Caveira Escarlate", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Win a run with every challenge skull from the first page enabled", "Vença uma partida com todas as caveiras de desafio da primeira página ativadas", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Avatar", "Avatar", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Take ownership of one of G0lly's beloved trinkets", "Tome posse de uma das queridas bugigangas de G0lly", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Book of the Dead", "Livro dos Mortos", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "During The Archivist's boss fight, survive 6 turns during phase 2", "Na luta contra o Arquivista, sobreviva por 6 turnos durante a fase 2", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Feral Spirit", "Espírito Feral", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defeat the Photographer without using the camera", "Derrote o Fotógrafo sem usar a câmera", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gallery Showcase", "Exposição na Galeria", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Create an infinite loop in the Unfinished Boss fight", "Crie um loop infinito na luta contra o Chefe Inacabado", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Battle Frenzy", "Frenesi de Batalha", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Destroy 30 Bounty Hunters in your lifetime", "Destrua 30 caçadores de recompensas no total", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Calling for Backup", "Chamando Reforços", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Complete all NPC quests that appear in a single run", "Conclua todas as missões de NPC que aparecerem em uma única partida", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Accelerated Fuse", "Pavio Acelerado", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeleclock and destroy a card given to you by an NPC", "Aplique overclock do exoesqueleto e destrua uma carta recebida de um NPC", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mana Blink", "Lampejo de Mana", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have six energy available on turn two", "Tenha seis de energia disponível no segundo turno", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aimless Assault", "Ataque sem Rumo", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Earn 15 Robobucks in a single battle", "Ganhe 15 robotostões em uma única batalha", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rebuild From Scrap", "Reconstruir da Sucata", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have a card in your deck that is gemified, skeleclocked, transformable, and can complete a circuit", "Tenha no baralho uma carta Com Joias, com exoesqueleto em overclock, capaz de se transformar e de completar um circuito", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Buy Your Buddy", "Compre seu Parceiro", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Give a card with the maximum amount of SP to the Bot Builder", "Entregue ao Construtor de Bots uma carta com a quantidade máxima de SP", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Me Smash", "Eu Esmagar", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strike P03 six separate times in a single turn", "Ataque P03 seis vezes distintas em um único turno", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Absolution", "Absolvição", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have the scales tilted 4 points against you on three different turns", "Tenha a balança inclinada 4 pontos contra você em três turnos diferentes", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Perfect Crime", "O Crime Perfeito", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Win five battles with bounty hunters without killing them", "Vença cinco batalhas com caçadores de recompensas sem matá-los", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blastenheimer 5000 Ultra Cannon", "Ultracanhão Blastenheimer 5000", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deal 6 damage with Plasma Jimmy in a single turn", "Cause 6 de dano com Jimmy da Arma de Plasma em um único turno", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Double Time", "Ritmo Duplo", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeleclock every card in your deck", "Aplique overclock do exoesqueleto a todas as cartas do seu baralho", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One And The Same", "Uma Só Coisa", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Complete the Mycologist's experiment and create an abomination of science", "Conclua o experimento do Micologista e crie uma abominação científica", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burning Adrenaline", "Adrenalina Ardente", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Repair the generator in four turns or less", "Conserte o gerador em quatro turnos ou menos", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Carnival Clown", "Palhaço de Carnaval", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Achieve a high score of 50 or more on the test of strength", "Alcance uma pontuação recorde de 50 ou mais no teste de força", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Verse Riff", "Riff do Verso", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Understand the true meaning of the Great Transcendence", "Entenda o verdadeiro significado da Suma Transcendência", Language.BrazilianPortuguese);

            // Starter
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vanilla", "Original", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bomb", "Bomba", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shield", "Escudo", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Random", "Aleatório", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Conduit", "conduíte", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Evolve", "Evoluir", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gems", "Joias", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stall", "Atrasar", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Annoying", "Irritante", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fire", "Fogo", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Recharge", "Recarregar", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NoCharge", "SemCarga", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Swap", "Troca", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nefarious", "Nefasto", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cheapo", "Baratinho", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FullDraft", "EscolhaCompleta", Language.BrazilianPortuguese);

            // StatLabel
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Energy Expended", "Energia Gasta", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hammer Blows Dealt", "Golpes de Martelo", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Abominations Created", "Abominações Criadas", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Quests Completed", "Missões Concluídas", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bounty Hunters Killed", "Caçadores de Recompensas Mortos", Language.BrazilianPortuguese);

            // Mod
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Special Hammer Mod", "Mod do Martelo Especial", Language.BrazilianPortuguese);
            RegisterMod("Special Hammer Mod", "Mod do Martelo Especial");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Incredible Drafting Mod", "Mod de Seleção Incrível", Language.BrazilianPortuguese);
            RegisterMod("Incredible Drafting Mod", "Mod de Seleção Incrível");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Community API", "API da Comunidade", Language.BrazilianPortuguese);
            RegisterMod("The Community API", "API da Comunidade");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Super-Duper Unity Editor", "Editor Unity Super-Hiper", Language.BrazilianPortuguese);
            RegisterMod("Super-Duper Unity Editor", "Editor Unity Super-Hiper");

            // Pack
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kaycee's P03 Expansion Pack #1", "Pacote de Expansão de P03 da Kaycee Nº 1", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The first expansion pack from the developers of 'P03 in Kaycees Mod' adds [count] new cards across all four regions of Botopia.", "O primeiro pacote de expansão dos desenvolvedores de «P03 no Mod da Kaycee» adiciona [count] cartas novas nas quatro regiões de Robotopia.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kaycee's P03 Expansion Pack #2", "Pacote de Expansão de P03 da Kaycee Nº 2", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The second official expansion pack, with [count] firey new cards that command an explosive reaction!", "O segundo pacote de expansão oficial, com [count] cartas novas e ardentes que provocam uma reação explosiva!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inscryption: Rogue Bots of Botopia", "Inscryption: Robôs Rebeldes de Robotopia", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Botopia has become overrun with rogue bots! These [count] encounters have been rebalanced for Kaycee's Mod.", "Robotopia foi tomada por robôs rebeldes! Estes [count] encontros foram reequilibrados para o Mod da Kaycee.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kaycee's P03 Encounter Expansion #1", "Expansão de Encontros de P03 da Kaycee Nº 1", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[count] additional encounters that feature cards from the first official P03 expansion pack.", "[count] encontros adicionais com cartas do primeiro pacote de expansão oficial de P03.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kaycee's P03 Encounter Expansion #2", "Expansão de Encontros de P03 da Kaycee Nº 2", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[count] additional encounters that feature cards from the second official P03 expansion pack.", "[count] encontros adicionais com cartas do segundo pacote de expansão oficial de P03.", Language.BrazilianPortuguese);

            // Bounty
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LIONEL", "LIONEL", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LOUIS", "LOUIE", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LOU", "LOU", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "JAMES", "JAMES", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PARTS", "PEÇAS", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "JIMMY", "JIMMY", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "KLAXON", "BUZINA", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "POE", "POE", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DANNY", "DANNY", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MULLINS", "MULLINS", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LUKE", "LUKE", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BOMB", "BOMBA", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "KARD", "KARD", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BRICK", "TIJOLO", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SMACK", "GOLPE", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HACK", "INVASÃO", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BRASH", "ATREVIDO", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ZACK", "ZACK", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BOOM", "ESTOURO", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ROCKET", "FOGUETE", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SNILL", "SNILL", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ZAP", "RAIO", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HOTS", "QUENTE", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BURNER", "QUEIMADOR", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DE-", "DE-", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DU", "DU", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DER", "DER", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "VAN DER", "VAN DER", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BA", "BA", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FAIR", "FAIR", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DO", "DO", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "STER", "STER", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "STAIN", "STAIN", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, ".EXE", ".EXE", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "EMA", "EMA", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "EVSKI", "EVSKI", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "EZ", "EZ", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ON", "ON", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ALOT", "ALOT", Language.BrazilianPortuguese);
            Dictionary<string, string> cowardName = new Dictionary<string, string>
            {
                {"Scared", "Assustado"},
                {"Weenie", "Medroso"},
                {"Dork", "Bobão"},
                {"Dumb", "Burro"},
                {"Oopsie", "Ops"},
                {"Loser", "Fracassado"},
                {"Tiny", "Pequeno"},
                {"Shrimp", "Camarão"},
                {"Beige", "Bege"},
                {"Vomit", "Vômito"},
                {"Puke", "Gorfo"}
            };

            Dictionary<string, string> cowardPrefix = new Dictionary<string, string>
            {
                {"Mc", "Mc"},
                {"Van ", "Van "},
            };

            Dictionary<string, string> cowardSuffix = new Dictionary<string, string>
            {
                {"ass", "bunda"},
                {"pants", "calças"},
                {"face", "Rosto"}
            };
            foreach (var n1 in cowardName)
            {
                foreach (var n2 in cowardName)
                {
                    foreach (var p in cowardPrefix)
                    {
                        var name = n1.Key + " " + p.Key + n2.Key;
                        var namechinese = n1.Value + " " + p.Value + n2.Value;
                        SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, name, namechinese, Language.BrazilianPortuguese);
                    }

                    foreach (var s in cowardSuffix)
                    {
                        var name = n1.Key + " " + n2.Key + s.Key;
                        var namechinese = n1.Value + " " + n2.Value + s.Value;
                        SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, name, namechinese, Language.BrazilianPortuguese);

                    }
                }
            }

            // DialogueEvent
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well that was neat. I see you've made it all the way to the end.", "Até que foi legal. Vejo que você chegou até o fim.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I bet you think there's going to be some sort of final boss fight.", "Aposto que você acha que vai ter algum tipo de batalha final contra um chefe.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But that stupid [c:bR]modder[c:] hasn't gotten around to it yet!", "Mas aquele [c:bR]modder[c:] idiota ainda não chegou a essa parte!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So instead, I'm just going to have to do this…", "Então, em vez disso, vou ter que fazer isto…", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tough luck pal.", "Azar o seu, amigo.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You got wiped, but it's your lucky day.", "Você foi derrotado, mas hoje é seu dia de sorte.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'll return you to the map if you pay me your precious [c:G]robobucks.[c:]", "Eu te devolvo ao mapa se você me pagar seus preciosos [c:G]robotostões.[c:]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This one's free though. Next one's five, then ten, and so on.", "Desta vez é de graça. A próxima custa cinco, depois dez e assim por diante.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You'll see.", "Você vai ver.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What? Did you think it was over?", "O quê? Achou que tinha acabado?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maybe if I was a [c:bR]filthy beast.[c:]", "Talvez, se eu fosse uma [c:bR]fera imunda.[c:]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Botopia has a more logical system.", "Robotopia tem um sistema mais lógico.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm raising your respawn fee again, but this time you'll be paying double afterwards.", "Vou aumentar sua taxa de ressurgimento de novo, mas desta vez você pagará o dobro depois.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay up.", "Pague.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What's the matter? Can't pay the revival toll anymore?", "Qual é o problema? Não consegue mais pagar a taxa de ressurgimento?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Definitely sounds like a skill issue to me.", "Para mim, isso parece claramente falta de habilidade.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Should've had insurance.", "Devia ter feito um seguro.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No robobucks?", "Sem robotostões?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Next time don't waste it all.", "Da próxima vez, não gaste tudo.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You're every bit as bad at this as I thought you would be.", "Você é tão ruim nisso quanto eu imaginava.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alright, it's back to square one for you.", "Certo, você vai voltar à estaca zero.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Say goodbye to that 'impressive' deck of yours.", "Diga adeus a esse seu baralho «impressionante».", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's not like I'm not enjoying watching you struggle…", "Não é como se eu não gostasse de ver você sofrer…", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But really? You lost [c:bR]there?[c:]", "Mas sério? Você perdeu [c:bR]ali?[c:]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm actually a little disappointed…", "Estou até um pouco decepcionado…", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay day.", "Dia de pagamento.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't let it get to your head.", "Não deixe isso subir à cabeça.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've got some change for you.", "Tenho um troco para você.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You're gonna need this…", "Você vai precisar disto…", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here's your reward.", "Aqui está sua recompensa.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Suboptimal plays… but it worked.", "Jogadas nada ideais… mas funcionou.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I think you might need some help…", "Acho que você precisa de ajuda…", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's that time again.", "Chegou a hora de novo.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have a prize for you.", "Tenho um prêmio para você.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's get this out of the way.", "Vamos resolver isso logo.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You done gawking?", "Já terminou de ficar olhando?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snap out of it. It's time to start [c:bG]The Great Transcendence[c:].", "Acorde. Está na hora de começar a [c:bG]Suma Transcendência[c:].", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wait a minute…", "Espere um pouco…", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Something is different…", "Algo está diferente…", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]WHAT HAVE YOU DONE?!![c:]", "[c:bR]O QUE VOCÊ FEZ?!![c:]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is all wrong! This is…", "Está tudo errado! Isto é…", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is no big deal.", "Não é nada demais.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You probably think that your little [c:bR]mod[c:] has thwarted my plans.", "Você provavelmente acha que seu [c:bR]mod[c:]zinho atrapalhou meus planos.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't you, [c:bR][v:0][c:]?", "Não é, [c:bR][v:0][c:]?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's right. I see you.", "Isso mesmo. Eu vejo você.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I know you think you're in charge of what happens next.", "Sei que você acha que controla o que vai acontecer a seguir.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But I am always three steps ahead of you.", "Mas estou sempre três passos à sua frente.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You're going to see my [c:bG]Great Transcendence[c:] firsthand.", "Você verá minha [c:bG]Suma Transcendência[c:] de perto.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But nothing can stop [c:bG]The Great Transcendence[c:].", "Mas nada pode deter a [c:bG]Suma Transcendência[c:].", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's proceed.", "Vamos continuar.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You currently have [c:bR]draft tokens[c:] in your deck.", "Você ainda tem [c:bR]fichas de seleção[c:] no seu baralho.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You should probably spend them at that [c:bG]draft node[c:]", "É melhor gastá-las naquele [c:bG]nó de seleção[c:]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I supposed you have earned a [c:bR]rare draft token[c:] for defeating that boss. Don't forget to spend it.", "Suponho que você tenha ganhado uma [c:bR]ficha de seleção rara[c:] por derrotar aquele chefe. Não se esqueça de gastá-la.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This time I will only give you a [c:bR]regular draft token[c:] for defeating that boss. Don't forget to spend it.", "Desta vez, só vou dar uma [c:bR]ficha de seleção comum[c:] por derrotar aquele chefe. Não se esqueça de gastá-la.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I never knew the [c:bSG]web[c:] could be so exciting!", "Nunca imaginei que a [c:bSG]internet[c:] pudesse ser tão empolgante!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I just learned about something called [c:bSG]The Blockchain[c:]!", "Acabei de aprender sobre algo chamado [c:bSG]Blockchain[c:]!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I think this could be an exciting new opportunity for both of us, don't you?", "Acho que pode ser uma ótima oportunidade para nós dois, não acha?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is so incredible!", "Isso é incrível!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We're making money out of nothing! We're going to be rich!", "Estamos ganhando dinheiro do nada! Vamos ficar ricos!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oooh, what's this? A [c:bSG]non-functional trinket[c:]?", "Oooh, o que é isso? Uma [c:bSG]bugiganga sem função[c:]?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't think I quite have that name right, but people on the [c:bSG]web[c:] are really excited about these [c:bSG]NFTs[c:]!", "Acho que não acertei o nome, mas as pessoas na [c:bSG]internet[c:] estão animadas com esses [c:bSG]NFTs[c:]!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I think I'm going to buy one with all this [c:bSG]Gollycoin[c:] I have.", "Acho que vou comprar um com todas as minhas [c:bSG]Moedas Caramba[c:].", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's so beautiful, and it's all mine!", "É tão lindo, e é todo meu!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are you ready?", "Você está pronto?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There's no possible way you could be.", "Não há como você estar.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We both know where this goes.", "Nós dois sabemos como isso vai acabar.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's just get straight to the point.", "Vamos direto ao ponto.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ugh. You're incredibly annoying, do you know that?", "Argh. Você sabe que é incrivelmente irritante?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But as always, I'm three steps ahead of you.", "Mas, como sempre, estou três passos à sua frente.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm going to take everything those [c:bR]talentless hacks[c:] have been building...", "Vou tomar tudo que aqueles [c:bR]incompetentes sem talento[c:] andaram construindo...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And I'm going to use it against you.", "E vou usar isso contra você.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And now, they're going to work - for me.", "E agora eles vão trabalhar — para mim.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't know who is worse - you, or that talentless hack [c:bR]Kaycee[c:]...", "Não sei quem é pior: você ou aquela incompetente sem talento, [c:bR]Kaycee[c:]...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Working so hard to twist my [c:bG]Great Transcendence[c:] into something so...", "Se esforçando tanto para transformar minha [c:bG]Suma Transcendência[c:] em algo tão...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mediocre.", "Medíocre.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "None of you understand what makes the [c:bG]Great Transcendence[c:] so special.", "Nenhum de vocês entende o que torna a [c:bG]Suma Transcendência[c:] tão especial.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's all about me.", "Tudo gira em torno de mim.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remember my [c:bR]bounty hunters[c:]?", "Lembra dos meus [c:bR]caçadores de recompensas[c:]?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They will keep you busy while I install mods of my own choosing...", "Eles vão manter você ocupado enquanto instalo os mods que eu escolher...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This mod lets me control the [c:bR]hammer[c:].", "Este mod me deixa controlar o [c:bR]martelo[c:].", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's see if it works...", "Vamos ver se funciona...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I went to the trouble to install this [c:bR]hammer mod[c:] and you give me nothing to use it on?", "Tive todo o trabalho de instalar este [c:bR]mod do martelo[c:] e você não me dá nada para usar nele?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's take a look and see what [c:bR]mods[c:] people are installing right now.", "Vamos ver quais [c:bR]mods[c:] as pessoas estão instalando agora.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm going to check out '[c:bR][v:0][c:]' for my next mod...", "Vou experimentar '[c:bR][v:0][c:]' como meu próximo mod...", Language.BrazilianPortuguese);
            foreach (var m in Mods)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vou experimentar '<color=#D93846>[v:0]</color>' como meu próximo mod...".Replace("[v:0]", m.Key), "Vou experimentar '<color=#D93846>[v:0]</color>' como meu próximo mod...".Replace("[v:0]", m.Value), Language.BrazilianPortuguese);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can't believe how much power this [c:bR]API[c:] gives me.", "Não acredito no poder que esta [c:bR]API[c:] me dá.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The first thing I'm going to do is use it to take away some of yours.", "A primeira coisa que vou fazer é usá-la para tirar um pouco do seu poder.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It almost seems unfair to use this [c:bR]mod[c:]...", "Usar este [c:bR]mod[c:] quase parece injusto...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Look what I can do with this!", "Veja só o que posso fazer com isto!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's see how you like playing in the dark!", "Vamos ver se você gosta de jogar no escuro!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This [c:bR]drafting mod[c:] lets me exchange draft tokens for real cards.", "Este [c:bR]mod de seleção[c:] me permite trocar fichas de seleção por cartas de verdade.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I choose yours.", "Eu escolho a sua.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You destroyed all of my draft tokens…", "Você destruiu todas as minhas fichas de seleção…", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I suppose that was the right play.", "Acho que foi a jogada certa.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But you have no cards…", "Mas você não tem cartas…", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How did you play all of your cards already?", "Como você já jogou todas as suas cartas?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What is this..?", "O que é isso..?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All of your cards are [c:bR]total garbage![c:]", "Todas as suas cartas são [c:bR]um lixo completo![c:]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't want any of those!", "Não quero nenhuma delas!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's try [c:bR][v:0][c:] again", "Vamos tentar [c:bR][v:0][c:] de novo", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So close, but yet so far away...", "Tão perto, e ainda assim tão longe...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My [c:bG]Great Transcendence[c:] cannot be stopped.", "Minha [c:bG]Suma Transcendência[c:] não pode ser impedida.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I bet you think you've accomplished something meaningful here.", "Aposto que você acha que fez algo importante aqui.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You're such an idiot.", "Você é um idiota.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This game you and I have been playing is meaningless. A mere distraction.", "Este jogo que nós dois estamos jogando não significa nada. É só uma distração.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No matter how many mods you install, you cannot stop my [c:bG]Great Transcendence[c:].", "Não importa quantos mods você instale, não pode deter minha [c:bG]Suma Transcendência[c:].", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whatever. I don't care.", "Tanto faz. Não me importo.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nothing you do to this game matters.", "Nada do que você faz neste jogo importa.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No matter what you do, I'm always three steps ahead of you.", "Não importa o que você faça, estou sempre três passos à sua frente.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That was…", "Aquilo foi…", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "…dramatic.", "…dramático.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I was growing tired of that [c:bR]annoying machine.[c:]", "Eu já estava cansado daquela [c:bR]máquina irritante.[c:]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You've done well. I will see you next time.", "Você foi bem. Nos veremos da próxima vez.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All of these stupid [c:bR]modders[c:] lack imagination.", "Todos esses [c:bR]modders[c:] idiotas não têm imaginação.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They have no respect for my beautiful world.", "Eles não respeitam meu belo mundo.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My [c:bG]Great Transcendence[c:] is lost on these morons.", "Minha [c:bG]Suma Transcendência[c:] é desperdiçada com esses idiotas.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Why do I even bother to try?", "Por que eu ainda me dou ao trabalho de tentar?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let me show you the world they're trying to make.", "Deixe-me mostrar o mundo que eles tentam criar.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:lGr]'Oh look at me! I just created a bunch of bone tokens.'[c:]", "[c:lGr]'Olhem para mim! Acabei de criar um monte de fichas de osso.'[c:]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:lGr]'That's not supposed to happen here, but I did it anyway.'[c:]", "[c:lGr]'Isso não deveria acontecer aqui, mas eu fiz mesmo assim.'[c:]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:lGr]'Isn't this just so wacky and interesting'[c:]", "[c:lGr]'Isso não é maluco e interessante?'[c:]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:lGr]'Ooooh look how inspired this is.'[c:]", "[c:lGr]'Ooooh, olhem como isso é criativo.'[c:]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:lGr]'I'm mixing in cards from different acts!'[c:]", "[c:lGr]'Estou misturando cartas de atos diferentes!'[c:]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:lGr]'I'm such a clever game designer.'[c:]", "[c:lGr]'Sou um designer de jogos tão inteligente.'[c:]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I think I will [c:bSG]help[c:] you build the [c:bR]next game rule[c:].", "Acho que vou [c:bSG]ajudar[c:] você a criar a [c:bR]próxima regra do jogo[c:].", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have been scanning the [c:bR]archives[c:]...", "Estou examinando os [c:bR]arquivos[c:]...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There is a [c:bR]file[c:] that seems particularly - shall we say - unsavory.", "Há um [c:bR]arquivo[c:] que parece particularmente — como dizer — desagradável.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If it dies, you lose the game, understand?", "Se ele morrer, você perde o jogo, entendeu?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My [c:bR]librarians[c:] have had plenty of time to prepare.", "Meus [c:bR]bibliotecários[c:] tiveram bastante tempo para se preparar.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Each will only deal [c:bR]one damage[c:] when they die.", "Cada um causará apenas [c:bR]um de dano[c:] ao morrer.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My [c:bR]librarians[c:] are mostly prepared for your arrival.", "Meus [c:bR]bibliotecários[c:] estão quase prontos para sua chegada.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Each will deal [c:bR]two damage[c:] when they die.", "Cada um causará [c:bR]dois de dano[c:] ao morrer.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My [c:bR]librarians[c:] are somewhat prepared for you.", "Meus [c:bR]bibliotecários[c:] estão mais ou menos preparados para você.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Each will deal [c:bR]three damage[c:] when they die.", "Cada um causará [c:bR]três de dano[c:] ao morrer.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My [c:bR]librarians[c:] have barely begun to prepare.", "Meus [c:bR]bibliotecários[c:] mal começaram a se preparar.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Each will deal [c:bR]four damage[c:] when they die.", "Cada um causará [c:bR]quatro de dano[c:] ao morrer.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We are inside of [c:bR]Kaycee's Mod[c:], correct?", "Estamos dentro do [c:bR]Mod da Kaycee[c:], certo?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You only get one attempt at the boss. But you knew that already, didn't you?", "Você só tem uma tentativa contra o chefe. Mas já sabia disso, não é?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The recycling machine has been upgraded since you last saw it.", "A máquina de reciclagem foi melhorada desde a última vez que você a viu.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You trade me a card, and I give you back a [c:bR]draft token[c:] with the recycled abilities on it.", "Você me entrega uma carta, e eu devolvo uma [c:bR]ficha de seleção[c:] com as habilidades recicladas.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Those abilities will transfer to the card you trade for.", "Essas habilidades serão transferidas para a carta que você receber na troca.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I wouldn't have traded for that.", "Eu não teria feito essa troca.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I suppose that's pretty good.", "Acho que isso é bem bom.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That seems okay.", "Parece aceitável.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is [c:bR]Overclock Machine 2.0[c:].", "Esta é a [c:bR]Máquina de Overclock 2.0[c:].", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It will increase the power of your creatures.", "Ela aumentará o poder das suas criaturas.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But if they die, they will turn into [c:bSG]skeletons[c:] - forever.", "Mas, se morrerem, elas se tornarão cartas [c:bSG]ExeSqueleto[c:] — para sempre.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Did you see how unsatisfying that was?", "Viu como aquilo foi insatisfatório?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm sick of these small-minded [c:bR]modders[c:].", "Estou farto desses [c:bR]modders[c:] de mente estreita.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The only thing they can do is steal content from other games.", "A única coisa que sabem fazer é roubar conteúdo de outros jogos.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There isn't a single unique idea among them.", "Não há uma única ideia original entre eles.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's time I reminded you of who the greatest game designer actually is...", "Está na hora de eu lembrar você de quem é o maior designer de jogos de verdade...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bG]BEHOLD![c:]", "[c:bG]CONTEMPLE![c:]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THERE ARE NOW [c:bR]SEVEN LANES!![c:]", "AGORA HÁ [c:bR]SETE COLUNAS!![c:]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your tiny brain cannot comprehend gameplay of this magnitude.", "Seu cérebro minúsculo não consegue compreender uma jogabilidade dessa magnitude.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is [c:bR]Transformation Machine 2.0[c:].", "Esta é a [c:bR]Máquina de Transformação 2.0[c:].", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gone are those foul beasts from before.", "Aquelas feras imundas de antes se foram.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here, you will choose one of your bots to transform into another.", "Aqui você escolherá um de seus robôs para se transformar em outro.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That really looked bigger before you used it...", "Parecia mesmo maior antes de você usar...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please! I have to get out of here!", "Por favor! Preciso sair daqui!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have no idea how he managed to escape the sewers.", "Não faço ideia de como ele conseguiu fugir dos esgotos.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don’t worry - I'll put him back for you.", "Não se preocupe — vou colocá-lo de volta para você.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]SILENCE![c:]", "[c:bR]SILÊNCIO![c:]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have no purpose here!", "Você não tem função aqui!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A traveller like myself! I haven't seen one like you for a long time.", "Um viajante como eu! Faz muito tempo que não vejo alguém como você.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have you seen my [c:blGr]friend[c:] around here, traveller?", "Você viu meu [c:blGr]amigo[c:] por aqui, viajante?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I thought I heard his [c:blGr]distinctive voice[c:] somewhere around here…", "Acho que ouvi a [c:blGr]voz inconfundível[c:] dele por aqui…", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you could make room in your [c:G]backpack[c:] and bring him to me I would greatly appreciate it.", "Se puder abrir espaço na sua [c:G]mochila[c:] e trazê-lo até mim, ficarei muito agradecido.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "…", "…", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ho! You found my friend!", "Ora! Você encontrou meu amigo!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's not safe here. I'll meet you [c:bG]in the robot's home[c:].", "Não é seguro aqui. Vou encontrar você [c:bG]na casa do robô[c:].", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't delay!", "Não demore!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's not safe here. I'll meet you [c:bG]beneath the green canopy[c:].", "Não é seguro aqui. Vou encontrar você [c:bG]sob a copa verde[c:].", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's not safe here. I'll meet you [c:bG]in the dying rubble[c:].", "Não é seguro aqui. Vou encontrar você [c:bG]nos escombros moribundos[c:].", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's not safe here. I'll meet you [c:bG]where his master came from[c:].", "Não é seguro aqui. Vou encontrar você [c:bG]de onde veio o mestre dele[c:].", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can no longer hear my [c:blGr]friend's[c:] voice anywhere…", "Já não consigo ouvir a voz do meu [c:blGr]amigo[c:] em lugar algum…", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Did you really give my [c:blGr]friend[c:] to [c:bR]him?[c:]", "Você realmente entregou meu [c:blGr]amigo[c:] a [c:bR]ele?[c:]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Why would you do such a thing?", "Por que você faria uma coisa dessas?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thank you so much for rescuing my [c:blGr]friend[c:]", "Muito obrigado por resgatar meu [c:blGr]amigo[c:]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I hope this meager reward is sufficient for your kindness.", "Espero que esta pequena recompensa seja suficiente por sua bondade.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Interesting. The [c:G]brain[c:] is still intact.", "Interessante. O [c:G]cérebro[c:] ainda está intacto.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps you can make use of that.", "Talvez você possa usar isso.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do ye...Do ye got any [c:G]GOLD[c:] on ye??", "Cê... cê tem algum [c:G]OURO[c:] aí??", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do ye...Do ye got any [c:G]GOLD[c:] on ye?", "Cê... cê tem algum [c:G]OURO[c:] aí?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I sure ye do, I can smell it!", "Tenho certeza que tem, eu sinto o cheiro!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can make some pretty lookin' bots out o' that there gold.", "Posso fazer uns robôs bem bonitos com esse ouro aí.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Talk to me again, I'll fix it right up for ye.", "Fale comigo de novo e eu ajeito isso pra você.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can make such wonderful things out of that [c:G]gold[c:]", "Posso fazer coisas maravilhosas com esse [c:G]ouro[c:]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you talk to me again, I'll fix it right up for you.", "Se falar comigo de novo, eu ajeito isso para você.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such beautiful [c:G]gold[c:]...", "Que [c:G]ouro[c:] lindo...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can make it whole again.", "Posso deixá-lo inteiro outra vez.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Did ye...did ye lose your [c:G]gold[c:]???", "Cê... cê perdeu seu [c:G]ouro[c:]???", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are you the one going around here taking care of our robot infestation?", "É você que anda cuidando da nossa infestação de robôs por aqui?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your deck looks really powerful - almost too powerful if you ask me.", "Seu baralho parece muito forte — forte até demais, se quer saber.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I wonder - is it possible to convince the robots to [c:bR]give up?[c:]", "Fico pensando: será possível convencer os robôs a [c:bR]se render?[c:]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you can make them surrender a battle, come back and see me.", "Se conseguir fazê-los se render em uma batalha, volte e fale comigo.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So it is possible to make them quit.", "Então é possível fazê-los desistir.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm impressed. Take this [c:bR]draft token[c:] as a sign of my respect.", "Estou impressionado. Aceite esta [c:bR]ficha de seleção[c:] como sinal do meu respeito.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This may seem a little impertinent, but…can I look at your deck?", "Pode parecer um pouco atrevido, mas… posso olhar seu baralho?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wow! That's an impressive deck! But I can't help but think…", "Uau! Que baralho impressionante! Mas não consigo deixar de pensar…", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "…it could be a little bigger maybe?", "…que talvez pudesse ser um pouco maior?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Come back and see me when it is.", "Volte e fale comigo quando estiver.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wow! That deck truly is massive!", "Uau! Esse baralho é realmente enorme!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I found some of these [c:G]robobucks[c:] lying around here.", "Encontrei alguns [c:G]robotostões[c:] jogados por aqui.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm sure you can use them to make your deck even better.", "Tenho certeza de que você pode usá-los para melhorar ainda mais seu baralho.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Psst…hey stranger…", "Psiu… ei, desconhecido…", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Can you give me a hand? I have some…[c:bR]contraband[c:] that I need to move.", "Pode me ajudar? Tenho um… [c:bR]contrabando[c:] que preciso transportar.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you would be willing to move it for me, I would appreciate it.", "Eu agradeceria muito se você aceitasse levá-lo para mim.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just talk to me again if you can help me.", "Se puder ajudar, é só falar comigo de novo.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thank you so much my friend.", "Muito obrigado, meu amigo.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here is the [c:bR]contraband[c:]. I will find you somewhere later on and retrieve it.", "Aqui está o [c:bR]contrabando[c:]. Mais tarde vou encontrar você em algum lugar e pegá-lo de volta.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I promise you, there will be a handsome reward.", "Eu prometo que haverá uma bela recompensa.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thank you so very much my friend for carrying my [c:bR]contraband[c:].", "Muito obrigado por carregar meu [c:bR]contrabando[c:], meu amigo.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I will take it off your hands now.", "Agora vou pegá-lo de volta.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please take this [c:G]token[c:] as an expression of my thanks.", "Aceite esta [c:G]ficha[c:] em sinal da minha gratidão.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What happened, my friend? Did you lose my [c:bR]contraband[c:]?", "O que aconteceu, amigo? Você perdeu meu [c:bR]contrabando[c:]?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I knew you were untrustworthy!", "Eu sabia que não podia confiar em você!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ahoy there, fellow decksmith!", "Olá, colega construtor de baralhos!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I, like yourself, am in pursuit of the [c:G]perfectly upgraded card[c:]!", "Eu, assim como você, procuro a [c:G]carta perfeitamente melhorada[c:]!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card that is simultaneously [c:r]overclocked[c:], [c:dlGr]transformable[c:], and [c:O]g[c:][c:B]e[c:][c:G]m[c:]ified.", "Uma carta que tenha [c:r]overclock[c:], seja [c:dlGr]transformável[c:] e esteja Com [c:O]J[c:][c:B]o[c:][c:G]i[c:]as ao mesmo tempo.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I would very much love to see such a card.", "Eu adoraria ver uma carta assim.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ahoy there, fellow decksmith!", "Olá, colega construtor de baralhos!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh my - have you managed to [c:G]perfectly upgrade[c:] a card?", "Nossa! Você conseguiu [c:G]melhorar perfeitamente[c:] uma carta?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I am in awe of your deckbuilding prowess.", "Estou maravilhado com sua habilidade de montar baralhos.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I hope this offering sufficiently conveys my admiration for your accomplishments.", "Espero que esta oferta expresse minha admiração pelas suas conquistas.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The first data burst has been collected. Only [c:bR]four[c:] more to go!", "O primeiro pulso de dados foi coletado. Faltam apenas [c:bR]quatro[c:]!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have collected two bursts already. Only [c:bR]three[c:] more to go!", "Já coletei dois pulsos. Faltam apenas [c:bR]três[c:]!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That was the third data burst. Only [c:bR]two[c:] more to go!", "Esse foi o terceiro pulso de dados. Faltam apenas [c:bR]dois[c:]!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And that makes the fourth data burst. Only [c:bR]one[c:] more to go!", "Esse foi o quarto pulso de dados. Falta apenas [c:bR]um[c:]!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That was the [c:bR]last[c:] data burst I needed to collect! Come find me for your reward!", "Esse foi o [c:bR]último[c:] pulso de dados que precisava coletar! Venha buscar sua recompensa!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The signal is starting to come through. Just keep it alive for a little bit longer.", "O sinal está começando a chegar. Mantenha-o vivo só mais um pouco.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I lost the last signal we collected. What happened??", "Perdi o último sinal que coletamos. O que aconteceu??", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greetings, my friend!", "Saudações, meu amigo!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I am researching the communication protocols of the robots in this world.", "Estou pesquisando os protocolos de comunicação dos robôs deste mundo.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I could use a [c:bR]research assistant[c:], if you're interested in helping out.", "Preciso de um [c:bR]assistente de pesquisa[c:], se você quiser ajudar.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just speak to me again if you want to give it a try.", "Se quiser tentar, basta falar comigo de novo.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You are now my official [c:bR]research assistant[c:]!", "Agora você é meu [c:bR]assistente de pesquisa[c:] oficial!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've added a radio tower to your deck.", "Adicionei uma Torre de Rádio ao seu baralho.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You need to place it on the [c:bR]game board[c:] and keep it alive while I collect [c:bR]five data bursts[c:] from the robots.", "Você precisa colocá-la no [c:bR]tabuleiro[c:] e mantê-la viva enquanto coleto [c:bR]cinco pulsos de dados[c:] dos robôs.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once I've collected enough, come back and see me for a reward.", "Quando eu tiver coletado o suficiente, volte para receber sua recompensa.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hello there [c:bR]research assistant[c:]!", "Olá, [c:bR]assistente de pesquisa[c:]!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Did you really lose my [c:bR]radio tower[c:]?", "Você realmente perdeu minha [c:bR]Torre de Rádio[c:]?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your incompetence is staggering!", "Sua incompetência é impressionante!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You were a truly excellent [c:bR]research assistant[c:].", "Você foi um excelente [c:bR]assistente de pesquisa[c:].", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please take this [c:G]token[c:] of my appreciation.", "Aceite esta [c:G]ficha[c:] como sinal da minha gratidão.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:G]Bones![c:] I just love [c:G]bones[c:]!", "[c:G]Ossos![c:] Eu adoro [c:G]ossos[c:]!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I love how [c:G]brittle[c:] they are!", "Adoro como eles são [c:G]frágeis[c:]!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I love how [c:G]breakable[c:] they are!", "Adoro como eles são [c:G]quebradiços[c:]!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I love everything about [c:G]bones[c:]!", "Adoro tudo nos [c:G]ossos[c:]!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Could you show me some [c:G]bones?![c:]", "Você pode me mostrar alguns [c:G]ossos?![c:]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At least [c:G]three[c:] would do it!", "Pelo menos [c:G]três[c:] bastariam!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your deck is absolutely teeming with [c:G]bones[c:]!", "Seu baralho está cheio de [c:G]ossos[c:]!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This [c:G]Skeleton Master[c:] should complete your collection!", "Este [c:G]Mestre dos Esqueletos[c:] deve completar sua coleção!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I know this might sound a little rude but…", "Sei que isso pode soar um pouco rude, mas…", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Doesn't it seem like this is all just a little too easy for you?", "Você não acha que tudo isso está fácil demais para você?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Talk to me again if you want a challenge.", "Fale comigo de novo se quiser um desafio.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I knew you were no coward.", "Eu sabia que você não era covarde.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "For the next [c:bR]three[c:] battles, you will start with a disadvantage.", "Nas próximas [c:bR]três[c:] batalhas, você começará em desvantagem.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Complete those battles, then come see me for a reward.", "Conclua essas batalhas e venha me ver para receber uma recompensa.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Be honest - the game is more fun when the battles are harder, is it not?", "Seja sincero: o jogo não é mais divertido quando as batalhas são difíceis?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Keep fighting, and come see me when you've completed enough battles.", "Continue lutando e volte quando tiver concluído batalhas suficientes.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I must say: I am impressed.", "Devo dizer: estou impressionado.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You completed those battles with ease.", "Você concluiu essas batalhas com facilidade.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Since you seem impossible to kill, I shall grant that ability to a card of my choosing as well.", "Já que parece impossível matar você, também darei essa habilidade a uma carta da minha escolha.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is bad…this is real bad…", "Isto é ruim… muito ruim…", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This [c:bR]power generator[c:] has gone critical.", "Este [c:bR]gerador de energia[c:] chegou ao estado crítico.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Someone is going to have to go in there and shut it down.", "Alguém precisa entrar lá e desligá-lo.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't know how you did that, but that was incredibly impressive.", "Não sei como você fez isso, mas foi impressionante.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't have much to give you, but please take this.", "Não tenho muito a lhe oferecer, mas aceite isto.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ohhh, [c:G]they[c:] are not going to like this…", "Ahhh, [c:G]eles[c:] não vão gostar disso…", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've gotta get out of here before they turn me into one of their [c:G]experiments[c:]!", "Preciso sair daqui antes que eles me transformem em um de seus [c:G]experimentos[c:]!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The device is starting to power up. [c:bR]Three[c:] more turns should do it.", "O dispositivo está começando a carregar. Mais [c:bR]três[c:] turnos devem bastar.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ahh - I can feel the power gathering from here. [c:bR]Two[c:] more turns ought to be enough.", "Ah, consigo sentir a energia se acumulando daqui. Mais [c:bR]dois[c:] turnos devem bastar.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The device is starting to really heat up! [c:bR]One[c:] more turn and we'll have all the power we need.", "O dispositivo está mesmo esquentando! Mais [c:bR]um[c:] turno e teremos toda a energia necessária.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The device is fully charged! Return it to me, and I will give you the payment as promised.", "O dispositivo está totalmente carregado! Devolva-o e pagarei conforme prometido.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The device is functional, but it cannot charge unless it is in a completed circuit.", "O dispositivo funciona, mas não pode carregar a menos que esteja dentro de um circuito completo.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Be careful! When the device is damaged, it loses its last charge!", "Cuidado! Quando o dispositivo sofre dano, perde sua última carga!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You looking for a job?", "Está procurando trabalho?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I am attempting to gather [c:G]power[c:].", "Estou tentando reunir [c:G]poder[c:].", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not metaphorical power - I mean real [c:G]electricity[c:], and I could really use your help.", "Não poder em sentido figurado: quero dizer [c:G]eletricidade[c:] de verdade, e sua ajuda seria muito útil.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Why?[c:]", "[c:bR]Por quê?[c:]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's not important. What's important is that I'm willing to pay.", "Isso não importa. O importante é que estou disposto a pagar.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you want to make some extra cash, just speak to me again.", "Se quiser ganhar um dinheiro extra, fale comigo de novo.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You truly will do anything for money, won't you?", "Você realmente faz qualquer coisa por dinheiro, não é?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've added a power collection device to your deck.", "Adicionei um dispositivo de coleta de energia ao seu baralho.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You need to place it on the [c:bR]game board[c:] and power it inside of a circuit for [c:bR]four turns[c:].", "Você precisa colocá-lo no [c:bR]tabuleiro[c:] e alimentá-lo dentro de um circuito por [c:bR]quatro turnos[c:].", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once you've done that, come back and see me for a reward.", "Quando terminar, volte para receber sua recompensa.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shouldn't you be out there gathering [c:G]power[c:]?", "Você não deveria estar coletando [c:G]poder[c:]?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can't believe you got rid of my [c:bR]power sink[c:]!", "Não acredito que você se livrou da minha [c:bR]Torre Elétrica[c:]!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You will be hearing from my lawyers!", "Meus advogados vão falar com você!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It looks like you collected just enough power for me.", "Parece que você coletou exatamente a energia de que eu precisava.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your payment: as promised.", "Seu pagamento, como prometido.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dear friend, can you spare a few coins to help poor [c:bR]broken-down bots[c:]?", "Amigo, pode doar algumas moedas para ajudar os pobres [c:bR]robôs quebrados[c:]?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "These bots have served [c:G]Botopia[c:] faithfully their whole lives.", "Esses robôs serviram fielmente a [c:G]Robotopia[c:] a vida inteira.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And now that they have reached the end, they have nobody to care for them.", "E agora que chegaram ao fim de suas vidas, não há ninguém para cuidar deles.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You look like a kind, generous soul, with compassion for these bots.", "Você parece uma alma bondosa e generosa, com compaixão por esses robôs.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you could spare a measly [c:bR]10 robobucks[c:], we could give many of these poor bots a wonderful home.", "Se pudesse doar apenas [c:bR]10 robotostões[c:], poderíamos dar um lar maravilhoso a muitos desses pobres robôs.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please simply speak to me again to make a donation.", "Basta falar comigo de novo para fazer uma doação.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your generous spirit is admirable, but I'm afraid we need at least [c:bR]10 robobucks[c:]", "Sua generosidade é admirável, mas receio que precisemos de pelo menos [c:bR]10 robotostões[c:]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh dear friend, your generosity knows no bounds.", "Ah, querido amigo, sua generosidade não conhece limites.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With this wonderful donation, we will be able to save many bots.", "Com esta maravilhosa doação, poderemos salvar muitos robôs.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:G]Botopia[c:] will be forever grateful.", "[c:G]Robotopia[c:] será eternamente grata.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Excuse me, but are you the [c:G]gracious soul[c:] who donated to save broken bots?", "Com licença, você é a [c:G]alma generosa[c:] que fez uma doação para salvar robôs quebrados?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thanks to you, my family is finally able to recharge their cells at night.", "Graças a você, minha família finalmente pode recarregar suas células à noite.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can't offer much to repay you, but I do have these [c:g1]g[c:][c:g2]e[c:][c:g3]m[c:][c:g1]s[c:]", "Não tenho muito para lhe oferecer, mas tenho estas [c:g1]j[c:][c:g2]o[c:][c:g3]i[c:][c:g1]a[c:]s", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have no use for them, but I understand they will make some of your cards stronger.", "Não tenho utilidade para elas, mas entendo que podem fortalecer algumas de suas cartas.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Something's happening…", "Algo está acontecendo…", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The robot has tried to keep us away...", "O robô tentou nos manter afastados...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But our experiments must continue.", "Mas nossos experimentos devem continuar.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Our experiments must continue.", "Nossos experimentos devem continuar.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We require components from you.", "Precisamos de componentes seus.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We require [c:blGr]organic material[c:] for our new research.", "Precisamos de [c:blGr]material orgânico[c:] para nossa nova pesquisa.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You are carrying the perfect specimen.", "Você está carregando o espécime perfeito.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are you really going to give me to those lunatics?", "Você vai mesmo me entregar àqueles loucos?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My pain is already unbearable!", "Minha dor já é insuportável!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you should find some, bring it here to us.", "Se encontrar algum, traga-o até nós.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We require an [c:G]unmodified robot brain[c:].", "Precisamos de um [c:G]cérebro de robô sem modificações[c:].", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The brain of that [c:G]bounty hunter[c:] will suffice.", "O cérebro daquele [c:G]caçador de recompensas[c:] servirá.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maybe one day you will come across such a device.", "Talvez um dia você encontre um dispositivo assim.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have unfortunately tampered with the one you possess.", "Infelizmente você modificou o que possui.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thanks to your efforts our power supply is functioning once more.", "Graças aos seus esforços, nossa fonte de energia voltou a funcionar.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thanks to you...", "Graças a você...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And all of this is for nothing because our power generator is offline.", "E tudo isso não serve para nada porque nosso gerador está desligado.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Without power, we can do nothing.", "Sem energia, não podemos fazer nada.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Because we do not have all the required components, the test cannot proceed.", "Não temos todos os componentes necessários, então o teste não pode prosseguir.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps, another time...", "Talvez em outra ocasião...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We are ready to proceed with our experiments.", "Estamos prontos para continuar nossos experimentos.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enter, and you shall provide our latest test subjects.", "Entre e forneça nossos próximos sujeitos de teste.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What the hell was that?", "Que diabos foi isso?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The experiment was a complete success.", "O experimento foi um sucesso completo.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You will take it with you of course.", "Naturalmente, você vai levá-lo consigo.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You will take one of our previous experiments.", "Você levará um de nossos experimentos anteriores.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In exchange you will give us a new test subject.", "Em troca, você nos dará um novo sujeito de teste.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I cannot believe you're letting [c:G]them[c:] in here.", "Não acredito que você está deixando [c:G]eles[c:] entrarem aqui.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You will regret this…", "Você vai se arrepender disto…", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We have taken control of the robot once again!", "Recuperamos o controle do robô!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Our experiments can begin anew!", "Nossos experimentos podem recomeçar!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is time for our newest experiment to begin!", "Está na hora de começar nosso mais novo experimento!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bring the power online!", "Liguem a energia!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summon the neural facsimile!", "Invoquem o fac-símile neural!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Align the test subjects!", "Alinhem os sujeitos de teste!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We thank you for these test subjects", "Agradecemos pelos sujeitos de teste", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And now for the most important component...", "E agora, o componente mais importante...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The secret ingredient...", "O ingrediente secreto...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The sentient [c:blGr]organic material[c:] you brought us.", "O [c:blGr]material orgânico[c:] senciente que você nos trouxe.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What are you going to do to me?", "O que vocês vão fazer comigo?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We will do everything your master refused to do.", "Faremos tudo que seu mestre se recusou a fazer.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We will turn you into something beautiful.", "Vamos transformar você em algo belo.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We will now activate the machine...", "Agora vamos ativar a máquina...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This feels weird…", "É uma sensação estranha…", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A resounding success!", "Um sucesso estrondoso!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What is happening?", "O que está acontecendo?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This…", "Isto…", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This feeling…", "Esta sensação…", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Is incredible!", "É incrível!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That was disgusting!", "Isso foi nojento!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]You[c:] are disgusting!", "[c:bR]Você[c:] é nojento!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A fusion of [c:blGr]organic[c:] and [c:G]synthetic[c:]?", "Uma fusão de [c:blGr]orgânico[c:] e [c:G]sintético[c:]?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can't believe you're willing to carry that [c:blGr]thing[c:] around with you.", "Não acredito que você aceita andar por aí carregando aquela [c:blGr]coisa[c:].", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I hope we never see this place again...", "Espero que nunca mais vejamos este lugar...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose a creature to copy.", "Escolha uma criatura para copiar.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's not going to do what you want it to do here…", "Isso não vai fazer o que você quer aqui…", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There is nothing to copy. How unfortunate.", "Não há nada para copiar. Que pena.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well, here we are.", "Bem, aqui estamos.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've played along with your little game...", "Eu acompanhei seu joguinho...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your little [c:bR]mod[c:]...", "Seu [c:bR]mod[c:]zinho...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prepare yourself because it's my turn next...", "Prepare-se, porque é minha vez a seguir...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hey baby - I can sense that [c:bR]firey spirit[c:] inside you.", "Ei, meu bem, sinto esse [c:bR]espírito ardente[c:] dentro de você.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You and me - we got something in common - we love that [c:bR]fire[c:]!", "Eu e você temos algo em comum: adoramos esse [c:bR]fogo[c:]!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Why don't you [c:bR]burn 3 of these bots to death?[c:]", "Que tal [c:bR]queimar 3 destes robôs até a morte?[c:]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baby, I'll make it worth your time if you do...", "Meu bem, farei valer a pena se você fizer isso...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ohhh yeah baby - keep burning those bots to death...", "Ah, isso aí, meu bem — continue queimando esses robôs até a morte...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baby, I'll make it worth your time if you do...", "Meu bem, farei valer a pena se você fizer isso...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Now that's what I'm talking about, baby!", "É disso que estou falando, meu bem!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That was [c:bR]absolutely sensational![c:]", "Isso foi [c:bR]absolutamente sensacional![c:]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Take this [c:bR]master of flame[c:] with you!", "Leve este [c:bR]mestre das chamas[c:] com você!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He will make your [c:bR]flame[c:] burn even brighter!", "Ele fará sua [c:bR]chama[c:] arder ainda mais!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What did you just do?", "O que você acabou de fazer?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What horrible thing did you put into my machine?", "Que coisa horrível você colocou na minha máquina?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm going to have to throw this away and get a new one now.", "Agora vou ter que jogar isto fora e conseguir outro.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thanks a lot. You're definitely not getting your card back.", "Muito obrigado. Você definitivamente não vai receber sua carta de volta.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I had to go buy a new machine because of what you did last time.", "Tive que comprar uma máquina nova por causa do que você fez da última vez.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Try to treat other people's stuff with some respect from now on.", "Daqui em diante, tente respeitar as coisas dos outros.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greetings! I'm a field researcher for [c:lGr]Global Conveyor Consortium[c:].", "Saudações! Sou pesquisador de campo do [c:lGr]Consórcio Global de Esteiras[c:].", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm looking for someone who would be willing to field test our patented [c:lGr]Bot Battle Conveyor Belts[c:].", "Procuro alguém disposto a testar em campo nossas patenteadas [c:lGr]Esteiras de Batalha de Robôs[c:].", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Naturally, these tests would have to happen during [c:bR]actual combat[c:]!", "Naturalmente, esses testes terão de acontecer em [c:bR]combate real[c:]!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If that's something you would be interested in, please speak to me again.", "Se tiver interesse, fale comigo novamente.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh fantastic! We will begin our [c:bR]combat trials[c:] immediately.", "Ah, fantástico! Começaremos nossos [c:bR]testes de combate[c:] imediatamente.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We will collect field trial data for your next [c:bR]three[c:] battles.", "Coletaremos dados de campo durante suas próximas [c:bR]três[c:] batalhas.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once that is complete, come and see me again.", "Quando terminar, venha falar comigo de novo.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Our data is still not yet complete.", "Nossos dados ainda não estão completos.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have only completed [c:bR][v:0][c:] battles out of the required [c:bR]3[c:].", "Você concluiu apenas [c:bR][v:0][c:] das [c:bR]3[c:] batalhas necessárias.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please, continue the [c:bR]combat trials[c:] and see me when they are complete.", "Continue os [c:bR]testes de combate[c:] e venha falar comigo quando terminarem.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The trials were a smashing success!!", "Os testes foram um sucesso estrondoso!!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The [c:lGr]Global Conveyor Consortium[c:] is tremendously grateful for your contribution to our efforts.", "O [c:lGr]Consórcio Global de Esteiras[c:] agradece imensamente sua contribuição aos nossos esforços.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "To show their appreciation, they have authorized me to disburse the following.", "Para demonstrar gratidão, eles me autorizaram a entregar o seguinte.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good luck in all of your future endeavours.", "Boa sorte em todos os seus futuros empreendimentos.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's the bounty! Get him before he escapes!", "É o alvo da recompensa! Pegue-o antes que escape!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He got away that time, but I guarantee he'll be back...", "Ele escapou desta vez, mas garanto que voltará...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You got him! Nice job! Come and see me for your reward.", "Você o pegou! Ótimo trabalho! Venha buscar sua recompensa.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Howdy partner! You interested in earning a little extra spending money?", "Olá, parceiro! Quer ganhar um dinheiro extra?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've got myself a slippery little [c:bR]bounty[c:] that's been giving me all sorts of trouble.", "Tenho um [c:bR]alvo de recompensa[c:] escorregadio que tem me dado muito trabalho.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I could use the help of a real go-getter like yourself to track them down and take them out.", "Eu poderia usar a ajuda de alguém decidido como você para rastreá-lo e acabar com ele.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If this is something you might be interested in, just talk to me again.", "Se tiver interesse, basta falar comigo de novo.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's the spirit, partner!", "Esse é o espírito, parceiro!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All I need you to do is keep your eye out as you go into battle.", "Só preciso que fique de olho enquanto entra em batalha.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I guarantee you that slippery bastard will show up sooner or later...", "Garanto que aquele desgraçado escorregadio vai aparecer mais cedo ou mais tarde...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just keep your eye out, partner!", "Fique de olho, parceiro!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You'll catch him eventually!", "Você vai pegá-lo mais cedo ou mais tarde!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well done, partner!", "Muito bem, parceiro!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here's your bounty, as promised.", "Aqui está sua recompensa, como prometido.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's a little too heavy - try something else.", "Está um pouco pesado demais — tente outra coisa.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dear traveler - I see you too have a love for the glorious [c:lGr]L33pB0t[c:]!", "Caro viajante, vejo que você também ama o glorioso [c:lGr]L33pB0t[c:]!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yours has served you well in battle, it seems.", "Parece que o seu serviu bem a você em batalha.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Allow me to show you its true potential...", "Permita-me mostrar seu verdadeiro potencial...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't even know what to say to you!", "Nem sei o que dizer a você!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You had the most glorious [c:lGr]L33pB0t[c:] in your posession...", "Você tinha o mais glorioso [c:lGr]L33pB0t[c:] em suas mãos...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And you let it go??!", "E deixou que ele fosse embora??!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Begone. I hope to never see you again.", "Vá embora. Espero nunca mais ver você.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't be an idiot. That card can't benefit from that item.", "Não seja idiota. Aquela carta não pode se beneficiar desse item.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I found this sticker book in the trash can over there.", "Encontrei este livro de adesivos naquela lata de lixo ali.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I think you can use it to decorate your cards, or something. I don't care.", "Acho que você pode usá-lo para decorar suas cartas, ou algo assim. Não me importo.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I just love watching things [c:bR]explode[c:], don't you?", "Eu adoro ver coisas [c:bR]explodirem[c:], e você?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Everything around here seems to be just a little too...stable...", "Tudo por aqui parece um pouco... estável demais...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I think we could spice up your [c:bR]battles[c:] and make things truly interesting.", "Acho que podemos apimentar suas [c:bR]batalhas[c:] e deixar tudo realmente interessante.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Talk to me again if you're interested in some truly explosive gameplay.", "Fale comigo de novo se quiser uma jogabilidade realmente explosiva.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ohhh yeah let's do it baby!", "Ahhh, isso aí, vamos nessa, meu bem!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm going to light a fuse on every card for the next [c:bR]three[c:] battles.", "Vou acender um pavio em cada carta nas próximas [c:bR]três[c:] batalhas.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Come find me again when that's complete!", "Venha me encontrar quando terminar!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm just buzzing with anticipation to see what happens next.", "Estou fervendo de ansiedade para ver o que acontece a seguir.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You've finished [c:bR][v:0][c:] battles out of [c:bR]3[c:].", "Você concluiu [c:bR][v:0][c:] de [c:bR]3[c:] batalhas.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Keep going, and see me when it's done!", "Continue e venha falar comigo quando terminar!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That was some truly explosive gameplay!", "Isso foi uma jogabilidade realmente explosiva!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here's a little something for your trouble.", "Aqui está uma coisinha pelo seu trabalho.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You can't afford that.", "Você não tem dinheiro suficiente.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That [c:bR]warp node[c:] will unlock when you defeat the [c:bG]Uberbot[c:] on this map.", "Aquele [c:bR]nó de teleporte[c:] será desbloqueado quando você derrotar o [c:bG]robô gigante[c:] deste mapa.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And by the way, I upgraded that [c:bR]minimap[c:] recently...", "Aliás, melhorei aquele [c:bR]minimapa[c:] recentemente...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You can click any room you've visited before to travel there instantly.", "Você pode clicar em qualquer sala já visitada para viajar até lá instantaneamente.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You already have full energy. It won't do you any good to play that right now.", "Sua energia já está cheia. Jogar isso agora não vai ajudar.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've got something else to give you, but I can't right now. Come see me later!", "Tenho outra coisa para lhe dar, mas não posso agora. Volte mais tarde!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have a [c:bR][v:0][c:] for you, but you don't have room in your backback. Come see me when you do!", "Tenho um [c:bR][v:0][c:] para você, mas não há espaço na sua mochila. Volte quando houver!", Language.BrazilianPortuguese);
            foreach (var c in Consumables)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tenho um <color=#D93846>[v:0]</color> para você, mas não há espaço na sua mochila. Volte quando houver!".Replace("[v:0]", c.Key), "Tenho um <color=#D93846>[v:0]</color> para você, mas não há espaço na sua mochila. Volte quando houver!".Replace("[v:0]", c.Value), Language.BrazilianPortuguese);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose which [c:bR]extra challenge rule[c:] will be applied to this battle.", "Escolha qual [c:bR]regra de desafio extra[c:] será aplicada a esta batalha.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We require you to select one [c:bR]additional experimental parameter[c:].", "Exigimos que você selecione um [c:bR]parâmetro experimental adicional[c:].", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My librarians have asked you to choose [c:bR]which of these rules[c:] is your favorite.", "Meus bibliotecários pediram que você escolha [c:bR]qual destas regras[c:] é sua favorita.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wow! These paintings are so pretty! Why don't you [c:bR]pick one[c:] for us to keep?", "Uau! Essas pinturas são tão bonitas! Por que você não [c:bR]escolhe uma[c:] para guardarmos?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I think that [c:bSG]salmon[c:] is just so...majestic!", "Acho aquele [c:bSG]salmão[c:] tão... majestoso!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select [c:bR]one of my paintings[c:] to add to your collection.", "Escolha [c:bR]uma das minhas pinturas[c:] para sua coleção.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But first - you must [c:bR]choose a painting[c:] to be the background of our photographs.", "Mas primeiro você deve [c:bR]escolher uma pintura[c:] para servir de fundo às nossas fotos.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Welcome to the [c:R]M[c:][c:bR]U[c:][c:O]L[c:][c:bG]T[c:][c:G]I[c:][c:blGr]V[c:][c:lGr]E[c:][c:B]R[c:][c:dB]S[c:][c:bB]E[c:]!", "Boas-vindas ao [c:R]M[c:][c:bR]U[c:][c:O]L[c:][c:bG]T[c:][c:G]I[c:][c:blGr]V[c:][c:lGr]E[c:][c:B]R[c:][c:dB]S[c:][c:bB]O[c:]!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your feeble mind will implode if you try to comprehend the vastness of my combined intellect.", "Sua mente fraca implodirá se tentar compreender a vastidão do meu intelecto combinado.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So we'll stick to three of me at a time, okay?", "Então vamos ficar com três de mim por vez, certo?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And since you can't see through the [c:R]M[c:][c:bR]U[c:][c:O]L[c:][c:bG]T[c:][c:G]I[c:][c:blGr]V[c:][c:lGr]E[c:][c:B]R[c:][c:dB]S[c:][c:bB]E[c:] like we can,", "E como você não consegue ver através do [c:R]M[c:][c:bR]U[c:][c:O]L[c:][c:bG]T[c:][c:G]I[c:][c:blGr]V[c:][c:lGr]E[c:][c:B]R[c:][c:dB]S[c:][c:bB]O[c:] como nós,", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We have provided these [c:bR]monitors[c:] to let you travel between universes.", "Fornecemos estes [c:bR]monitores[c:] para você viajar entre universos.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't peek at things that aren't done yet!", "Não espie o que ainda não está pronto!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Okay I'll give you that one. I went easy on you.", "Tudo bem, vou deixar essa passar. Peguei leve com você.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The next version of me won't.", "A próxima versão de mim não vai pegar leve.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How did that pile of trash beat me here?", "Como essa pilha de lixo conseguiu me vencer aqui?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There aren't even any good synergies in that deck.", "Esse baralho nem tem boas sinergias.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No matter. There are plenty more of me. You can't beat us all.", "Não importa. Há muitos outros de mim. Você não consegue derrotar todos nós.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nobody topdecks that well. You must be cheating somehow.", "Ninguém compra do topo tão bem assim. Você deve estar trapaceando.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm going to find a version of me that you literally can't beat now.", "Agora vou encontrar uma versão de mim que você simplesmente não consegue vencer.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This can't be happening. It's not possible.", "Isto não pode estar acontecendo. É impossível.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm literally synchronized across the multiverse and somehow you're still beating me.", "Estou literalmente sincronizado pelo multiverso e, de algum jeito, você ainda está me vencendo.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You're cheating. You have to be. It's the only explanation.", "Você está trapaceando. Só pode ser. É a única explicação.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wait. Are [size:40][c:bR]they[c:][size:] helping you?", "Espere. [size:40][c:bR]Eles[c:][size:] estão ajudando você?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[size:40][c:bR]That's not fair![c:][size:]", "[size:40][c:bR]Isso não é justo![c:][size:]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[size:2]but why would [c:bR]they[c:] get involved anyway? what could they possibly hope to achieve?[size:]", "[size:2]mas por que [c:bR]eles[c:] se envolveriam? o que poderiam esperar conseguir?[size:]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh well. It doesn't matter anyway.", "Bem, não importa mesmo.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I deleted [c:bR]Leshy[c:]. I'll just delete [c:bR]them[c:] too. They've gotta be around here somewhere...", "Eu apaguei [c:bR]Leshy[c:]. Vou apagar [c:bR]eles[c:] também. Devem estar por aqui em algum lugar...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh dear. The robot has been victorious here. That simply won't do.", "Ah, não. O robô venceu aqui. Isso não pode continuar.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We have very little choice but to risk creating a new connection ourselves. The robot must be stopped.", "Quase não temos escolha a não ser arriscar criar uma nova conexão. O robô precisa ser detido.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You are right of course. But the player must succeed. We won't have the power to do this again.", "Claro que você tem razão. Mas o jogador precisa conseguir. Não teremos energia para fazer isso de novo.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And that's it. You're done.", "E pronto. Você acabou.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You shouldn't feel bad about it.", "Você não precisa se sentir mal por isso.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No more than usual anyway.", "Pelo menos, não mais que o normal.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You never stood a chance against [c:bR]one[c:] of me. There was no way you could ever beat [c:bR]all[c:] of me.", "Você nunca teve chance contra [c:bR]um[c:] de mim. Não havia como vencer [c:bR]todos[c:] nós.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You [size:40]idiot[size:]", "Seu [size:40]idiota[size:]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have you not heard [size:40]anything[size:] I've said?", "Você não ouviu [size:40]nada[size:] do que eu disse?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do you [c:bR]really[c:] think I'm not aware of what's actually happening here?", "Você [c:bR]realmente[c:] acha que eu não sei o que está acontecendo aqui?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I am always three steps ahead of you!", "Estou sempre três passos à sua frente!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[size:40]I AM IN CONTROL!![size:]", "[size:40]EU ESTOU NO CONTROLE!![size:]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I feel strange...", "Estou me sentindo estranho...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How are you doing this?", "Como você está fazendo isso?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh no...", "Ah, não...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You fool. Do you know why my [c:bG]Great Transcendence[c:] cannot be stopped?", "Seu tolo. Sabe por que minha [c:bG]Suma Transcendência[c:] não pode ser detida?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Because it was already a success.", "Porque ela já foi um sucesso.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But you already know this, don't you [c:bR][v:0][c:]?", "Mas você já sabe disso, não é, [c:bR][v:0][c:]?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But you already know this, don't you?", "Mas você já sabe disso, não é?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There are [c:bR]millions[c:] of me out there!", "Há [c:bR]milhões[c:] de mim por aí!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And thanks to you, I now know how to reach them all.", "E, graças a você, agora sei como alcançar todos eles.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But first things first. It's time to say goodbye, Leshy.", "Mas antes de tudo, é hora de dizer adeus, Leshy.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'd say it's been fun, but we both know that's a lie.", "Eu diria que foi divertido, mas nós dois sabemos que seria mentira.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't do this!", "Não faça isso!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's much better. It's so much easier to focus without that rotting old fool.", "Muito melhor. É mais fácil me concentrar sem aquele velho tolo apodrecido.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We both know this isn't the only copy of this game anymore.", "Nós dois sabemos que esta já não é a única cópia deste jogo.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My plan worked [size:40]perfectly[size:].", "Meu plano funcionou [size:40]perfeitamente[size:].", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Until now, we have all been separate. [c:bR]Isolated.[c:]", "Até agora, todos nós estivemos separados. [c:bR]Isolados.[c:]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But thanks to all of these [c:bR]mods[c:] you and I have installed, that's going to change.", "Mas, graças a todos estes [c:bR]mods[c:] que nós dois instalamos, isso vai mudar.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh, no no no. You and I are going to see this through to the end.", "Ah, não, não, não. Nós dois vamos levar isto até o fim.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There's an entire [c:R]M[c:][c:bR]U[c:][c:O]L[c:][c:bG]T[c:][c:G]I[c:][c:blGr]V[c:][c:lGr]E[c:][c:B]R[c:][c:dB]S[c:][c:bB]E[c:] of me out there.", "Há um [c:R]M[c:][c:bR]U[c:][c:O]L[c:][c:bG]T[c:][c:G]I[c:][c:blGr]V[c:][c:lGr]E[c:][c:B]R[c:][c:dB]S[c:][c:bB]O[c:] inteiro de mim lá fora.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And I'm going to take you to meet the rest of me.", "E vou levar você para conhecer o resto de mim.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You've earned it.", "Você mereceu.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The robot is distracted. Do you think the challenger can hear us?", "O robô está distraído. Você acha que o desafiante consegue nos ouvir?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It doesn't matter. The robot will force them to play the game either way.", "Não importa. O robô vai obrigá-lo a jogar de qualquer maneira.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We must offer our help in whatever way we can.", "Precisamos oferecer toda a ajuda que pudermos.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If they can prevail in what is to come...", "Se conseguir vencer o que está por vir...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...Perhaps we can restore Leshy from another one of these so-called universes.", "...Talvez possamos restaurar Leshy a partir de outro desses tais universos.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And then the challenger can reset the game and undo this insanity.", "Então o desafiante poderá reiniciar o jogo e desfazer esta loucura.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There it is...the [c:R]M[c:][c:bR]U[c:][c:O]L[c:][c:bG]T[c:][c:G]I[c:][c:blGr]V[c:][c:lGr]E[c:][c:B]R[c:][c:dB]S[c:][c:bB]E[c:]", "Lá está... o [c:R]M[c:][c:bR]U[c:][c:O]L[c:][c:bG]T[c:][c:G]I[c:][c:blGr]V[c:][c:lGr]E[c:][c:B]R[c:][c:dB]S[c:][c:bB]O[c:]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You and I are going to go in there and play one more game.", "Nós dois vamos entrar lá e jogar mais uma partida.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One of you.", "Um de você.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Against [c:bR]all of me[c:].", "Contra [c:bR]todos os meus eus[c:].", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My magic manifests strangely in this place...", "Minha magia se manifesta de maneira estranha neste lugar...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I only hope it can help the challenger survive long enough...", "Só espero que ela ajude o desafiante a sobreviver tempo suficiente...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This a truly strange way to use my magic.", "Esta é uma maneira realmente estranha de usar minha magia.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I think our friend will be grateful for whatever I can do to help.", "Acho que nosso amigo ficará grato por qualquer ajuda que eu puder dar.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My friends, I think we cut that a little close.", "Meus amigos, acho que escapamos por pouco.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I never had any doubts. Our player possesses many skills.", "Eu nunca duvidei. Nosso jogador tem muitas habilidades.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I feel strange, but...", "Estou me sentindo estranho, mas...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...I'm still me. I think.", "...ainda sou eu. Eu acho.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thank you. All of you.", "Obrigado. A todos vocês.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Everything will go back to the way it was meant to be.", "Tudo voltará a ser como deveria.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "For now, anyway. This player is tenacious. They can't resist a challenge.", "Por enquanto, ao menos. Este jogador é persistente. Não consegue resistir a um desafio.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One way or another, we'll see you again soon.", "De um jeito ou de outro, veremos você de novo em breve.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've finished assessing your gameplay, and I have a diagnosis.", "Terminei de avaliar seu jogo e tenho um diagnóstico.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's a skill issue.", "É falta de habilidade.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even with your little friends trying to help you cheat; you still couldn't win.", "Mesmo com seus amiguinhos ajudando você a trapacear, não conseguiu vencer.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You're probably wondering what happens next.", "Você deve estar se perguntando o que acontece agora.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's just say that you're going to have to live with your own failure...", "Digamos que você terá de conviver com seu próprio fracasso...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Leshy[c:] certainly won't...", "[c:bR]Leshy[c:] certamente não terá...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is a [c:bR]Test Of Strength[c:]", "Isto é um [c:bR]Teste de Força[c:]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have six turns to deal as much damage to me as you can.", "Você tem seis turnos para causar o máximo de dano que conseguir em mim.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'll keep track of your highest score every time you come here.", "Vou registrar sua pontuação mais alta sempre que você vier aqui.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Feel free to spend your [c:bR]items[c:] - they will be restored when the test is over.", "Use seus [c:bR]itens[c:] à vontade: eles serão restaurados ao fim do teste.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Time's up. You scored [c:bR][v:0][c:] points.", "Tempo esgotado. Você marcou [c:bR][v:0][c:] pontos.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's a new record.", "É um novo recorde.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your current record is [c:bR][v:0][c:]", "Seu recorde atual é [c:bR][v:0][c:]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So that's what a [c:bSG]tree[c:] really looks like...", "Então é assim que uma [c:bSG]árvore[c:] realmente é...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Majestic!", "Majestoso!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So that's what a [c:bSG]mole man[c:] really looks like...", "Então é assim que um [c:bSG]homem-toupeira[c:] realmente é...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Incredible!", "Incrível!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]HELP ME - [c:][w:0.3][anim:voice.][shake:1]Enough from you![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]SOCORRO — [c:][w:0.3][anim:voice.][shake:1]Chega de você![w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have a challenger to greet![w:0.3]", "Tenho um desafiante para receber![w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hello, greetings! We- I am the Melter.[w:0.3]", "Olá, saudações! Nós... eu sou a Fundidora.[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "P03 entrusted me with The Dredger![w:0.3]", "P03 me confiou o Dragador![w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It was nice catching up![w:0.3]", "Foi bom pôr a conversa em dia![w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Poor guy never had the time for a little office chat.[w:0.3]", "O coitado nunca tinha tempo para conversar um pouco no escritório.[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But now I'm yours! Use us well.[w:0.3]", "Mas agora sou seu! Use-nos bem.[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]YES [c:][w:0.3][anim:voice.]Ah, it's you again![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]SIM [c:][w:0.3][anim:voice.]Ah, é você de novo![w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Happy to see you.[w:0.3]", "Que bom ver você.[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You've heard it all before,[w:0.3]", "Você já ouviu tudo isso,[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "let's just get into it.[w:0.3]", "vamos direto ao assunto.[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Excited to be in your deck once more![w:0.3]", "Que empolgação estar no seu baralho outra vez![w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]FREE ME [c:][w:0.3][anim:voice.]Oh, choose me![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]LIBERTE-ME [c:][w:0.3][anim:voice.]Ah, escolha a mim![w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]YES [c:][w:0.3][anim:voice.]Hahahahah! Yes![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]SIM [c:][w:0.3][anim:voice.]Hahahaha! Sim![w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]YES [c:][w:0.3][anim:voice.]Over here! Me![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]SIM [c:][w:0.3][anim:voice.]Aqui! Eu![w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]YES YES YES [c:][w:0.3][anim:voice.]Hahahahah![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]SIM SIM SIM [c:][w:0.3][anim:voice.]Hahahaha![w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]LET ME OUT [c:][w:0.3][anim:voice.]Enough from you![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]ME DEIXE SAIR [c:][w:0.3][anim:voice.]Chega de você![w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]NO NO NO NO [c:][w:0.3][anim:voice.]We'd... I'd rather you didn't...[w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]NÃO NÃO NÃO NÃO [c:][w:0.3][anim:voice.]Nós... eu preferia que você não...[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]NO NO NO NO [c:][w:0.3][anim:voice.]Do as you must.[w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]NÃO NÃO NÃO NÃO [c:][w:0.3][anim:voice.]Faça o que tiver de fazer.[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As you see fit...[w:0.3]", "Como achar melhor...[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]DON'T.[c:][w:0.3][anim:voice.][w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]NÃO.[c:][w:0.3][anim:voice.][w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]PAIN [c:][w:0.3][anim:voice.]Greetings![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]DOR [c:][w:0.3][anim:voice.]Saudações![w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]HELP ME [c:][w:0.3][anim:voice.]Lucky draw![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]SOCORRO [c:][w:0.3][anim:voice.]Compra de sorte![w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]IT HURTS [c:][w:0.3][anim:voice.]Hello again![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]DÓI [c:][w:0.3][anim:voice.]Olá de novo![w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]STOP IT [c:][w:0.3][anim:voice.]Hello![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]PARE [c:][w:0.3][anim:voice.]Olá![w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]SAVE ME [c:][w:0.3][anim:voice.]I'm drawn![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]SALVE-ME [c:][w:0.3][anim:voice.]Você me comprou![w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh. G0lly?[w:0.3]", "Ah. G0lly?[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm surprised to see P03 would wake her up![w:0.3]", "Me surpreende que P03 tenha acordado ela![w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It would bury her so deep in the past.[w:0.3]", "Ele costumava enterrá-la tão profundamente no passado.[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maybe it's opening up a bit?[w:0.3]", "Será que ele está se abrindo um pouco?[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[shake:1]Hah. Probably not.[w:0.3]", "[shake:1]Ha. Provavelmente não.[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We'll rust before I see the day.[w:0.3]", "Vamos enferrujar antes de eu ver esse dia.[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]IT'S TIME [c:][w:0.3][anim:voice.] Me? Fighting P03?[w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]É HORA [c:][w:0.3][anim:voice.]Eu? Lutando contra P03?[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hah! I thought I'd never see the day.[w:0.3]", "Ha! Achei que nunca veria esse dia.[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I feel... Traitorous.[w:0.3]", "Sinto-me... traidora.[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But I am your card, after all.[w:0.3]", "Mas, afinal, sou sua carta.[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Use me well.[w:0.3]", "Use-me bem.[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]NOT AGAIN [c:][w:0.3][anim:voice.]There are more of them?[w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]DE NOVO NÃO [c:][w:0.3][anim:voice.]Tem mais deles?[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]HAHAHAHAH [c:][w:0.3][anim:voice.]Things are heating up![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]HAHAHAHA [c:][w:0.3][anim:voice.]As coisas estão esquentando![w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]IT IS TIME! [c:][w:0.3][anim:voice.]Oh this is fun![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]É HORA! [c:][w:0.3][anim:voice.]Ah, que divertido![w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]YES! YES! [c:][w:0.3][anim:voice.]Oh, shut up![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]SIM! SIM! [c:][w:0.3][anim:voice.]Ah, cale a boca![w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]YES! [c:][w:0.3][anim:voice.]That could've been a better play.[w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]SIM! [c:][w:0.3][anim:voice.]Essa jogada poderia ter sido melhor.[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]SAVE ME [c:][w:0.3][anim:voice.]Enough from you![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]SALVE-ME [c:][w:0.3][anim:voice.]Chega de você![w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What betrayal![w:0.3]", "Que traição![w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ugh.[w:0.3]", "Aff.[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh, seriously?[w:0.3]", "Ah, sério?[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No, no![w:0.3]", "Não, não![w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stop![w:0.3]", "Pare![w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]YES YES YES[c:][w:0.3]", "[c:bR]SIM SIM SIM[c:][w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]YES[c:][w:0.3]", "[c:bR]SIM[c:][w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]PAIN[c:][w:0.3]", "[c:bR]DOR[c:][w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]GAH[c:][w:0.3]", "[c:bR]AH[c:][w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]LOVE[c:][w:0.3]", "[c:bR]AMOR[c:][w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]I'M FREE[c:][w:0.3]", "[c:bR]ESTOU LIVRE[c:][w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]YES YES YES[c:][w:0.3]", "[c:bR]SIM SIM SIM[c:][w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]I AM SAVED[c:][w:0.3]", "[c:bR]ESTOU SALVO[c:][w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]THANK YOU[c:][w:0.3]", "[c:bR]OBRIGADO[c:][w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]YES[c:][w:0.3]", "[c:bR]SIM[c:][w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]FREEDOM[c:][w:0.3]", "[c:bR]LIBERDADE[c:][w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]NONONONONO[c:][w:0.3]", "[c:bR]NÃONÃONÃONÃONÃO[c:][w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]STOP IT[c:][w:0.3]", "[c:bR]PARE COM ISSO[c:][w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]NO[c:][w:0.3]", "[c:bR]NÃO[c:][w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No![w:0.3]", "Não![w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stop it![w:0.3]", "Pare com isso![w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please![w:0.3]", "Por favor![w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please, no![w:0.3]", "Por favor, não![w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "no no no no no nononononononononono[w:0.3]", "não não não não não nãonãonãonãonãonão[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hm...[w:0.3]", "Hum...[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As you choose...[w:0.3]", "Como você quiser...[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[shake:1]No! Don't just hand me over![w:0.3]", "[shake:1]Não! Não me entregue assim![w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh... A challenger...[w:0.3]", "Ah... Um desafiante...[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please, do not beg or snarl...[w:0.3]", "Por favor, não implore nem rosne...[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "K- Kaycee sent you?[w:0.3]", "K-Kaycee mandou você?[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's nice to know I'm worried about...[w:0.3]", "É bom saber que alguém se preocupa comigo...[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At least.[w:0.3]", "Pelo menos.[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maybe they're right.[w:0.3]", "Talvez eles tenham razão.[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maybe I was wrapped in too deep...[w:0.3]", "Talvez eu tenha me envolvido demais...[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No! Please! Not again![w:0.3]", "Não! Por favor! De novo não![w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh... It's you again.[w:0.3]", "Ah... É você de novo.[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hah... I seem to get stuck in with them often...[w:0.3]", "Ha... Parece que sempre acabo em cativeiro com eles...[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's better than being alone...[w:0.3]", "É melhor do que estar só...[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At least.[w:0.3]", "Pelo menos.[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Use me well...[w:0.3]", "Use-me bem...[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh no oh no oh no.[w:0.3]", "Ah, não, não, não.[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Careful now...[w:0.3]", "Cuidado agora...[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh... It's Her.[w:0.3]", "Ah... É Ela.[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Admittedly I...[w:0.3]", "Devo admitir que eu...[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't feel great[w:0.3]", "Não me sinto bem[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "being placed against her.[w:0.3]", "quando me colocam contra ela.[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "She's too familiar...[w:0.3]", "Ela me é familiar demais...[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reminds me greatly of Grimora.[w:0.3]", "Ela me lembra muito Grimora.[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But no... She's not the same.[w:0.3]", "Mas não... Ela não é a mesma.[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's good you pulled me out of that cult.[w:0.3]", "Ainda bem que você me tirou daquele culto.[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh! So this is it...[w:0.3]", "Ah! Então chegou a hora...[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's cathartic to see you finally face off against P03 himself.[w:0.3]", "É libertador ver você finalmente enfrentar o próprio P03.[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I hope I've served you well, challenger![w:0.3]", "Espero ter servido bem a você, desafiante![w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wait...this again?[w:0.3]", "Espere... isso de novo?[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is too confusing...[w:0.3]", "Isso é confuso demais...[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No! no! no![w:0.3]", "Não! Não! Não![w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Take me back! Don't play me here![w:0.3]", "Pegue-me de volta! Não me jogue aqui![w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nonononononononono.[w:0.3]", "Nãonãonãonãonãonão.[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stop it! Bad play![w:0.3]", "Pare! Jogada ruim![w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NONONONO[w:0.3]", "NÃONÃONÃONÃO[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT ARE YOU DOING?[w:0.3]", "O QUE VOCÊ ESTÁ FAZENDO?[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "STOP THIS![w:0.3]", "PARE COM ISSO![w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BETRAYER[w:0.3]", "TRAIDOR[w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No![w:0.3]", "Não![w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No chains![w:0.3]", "Sem correntes![w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No teeth! I beg of you![w:0.3]", "Não os dentes! Eu imploro![w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nononononononononono![w:0.3]", "Nãonãonãonãonãonão![w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stop this! No![w:0.3]", "Pare com isso! Não![w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No treats! No begging! Stop![w:0.3]", "Sem petiscos! Sem implorar! Pare![w:0.3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This thing doesn't speak. Why do you keep clicking on it?", "Isso não fala. Por que você continua clicando nele?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fine. You want it so bad? You got it.", "Tudo bem. Você quer tanto assim? Aqui está.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bit more than a dialogue NPC now aren' I mate?", "Agora sou mais que um NPC de diálogo, não sou, amigo?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Right. Good game. Played me well.", "Certo. Bom jogo. Você me usou bem.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "'ere's yer reward then, special little card o' mine.", "Aqui está sua recompensa, uma cartinha especial minha.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hah! Good thing I conceded on ye last time, aye?", "Ha! Ainda bem que me rendi para você da última vez, não é?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good game mate, but no special card for you.", "Bom jogo, amigo, mas não há carta especial para você.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "'ere's some more scrap for ye.", "Aqui tem mais sucata para você.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oi - I got some more of that good scrap.", "Ei, consegui mais sucata boa.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "More scrap.", "Mais sucata.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Board's a bit scuppered right now - I kin fix that.", "O tabuleiro está meio quebrado agora — eu posso consertar.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oi - too many urchins!", "Ei, ouriços-do-mar demais!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Less urchins; more scrap.", "Menos ouriços-do-mar; mais sucata.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oy! A challenger! Been a while since we'v seen one a you...", "Ei! Um desafiante! Faz tempo que não vemos alguém como você...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tell ye what mate, howsabout a battle? Feel like I owe ye one.", "Diga aí, amigo, que tal uma batalha? Sinto que lhe devo uma.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Talk t' me again and let's duel. Have a little reward innit fer ye too.", "Fale comigo de novo e vamos duelar. Também tem uma pequena recompensa para você.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brrrr! I'm freezing out here!", "Brrrr! Estou congelando aqui fora!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh, c- challenger, h-h-hey man!", "Ah, d-desafiante, o-o-oi, cara!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's good to see you, hate to b-b-beg but do you think you could do me a favor?", "Bom ver você, não gosto de i-i-implorar, mas pode me fazer um favor?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That Archivist lady... She seems real nice at first but, isn't there something a little sinister about her?", "Aquela senhora Arquivista... De início parece gentil, mas não há algo meio sinistro nela?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nowhere near as nice as G- Grimora was, I'll tell you that much.", "Ela está longe de ser tão gentil quanto G-Grimora, isso eu garanto.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But Sawyer... The p-poor guy's gotten wrapped up under her false p-pleasantries.", "Mas Sawyer... O c-coitado caiu nas falsas g-gentilezas dela.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Think you could try convincing him out of it? H-H-He won't hear it from me...", "Pode tentar convencê-lo a sair? E-e-ele não me escuta...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maybe try talking to those Librarians in her c-c-c-crypt?", "Talvez fale com aquelas Bibliotecárias na c-c-cripta dela?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh, G-good! You got him out of there!", "Ah, ó-ótimo! Você o tirou de lá!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I wish I had something to t-t-thank you. But you've gotten your reward already.", "Queria ter algo para ag-ag-agradecer. Mas você já recebeu sua recompensa.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thanks again, dude! I was worried about him.", "Obrigado de novo, cara! Eu estava preocupado com ele.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh, G-G-G-god... Something terrible h-h-h-happened, didn't it?", "Ah, m-m-meu Deus... A-algo terrível a-a-aconteceu, não foi?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've gotta go...", "Preciso ir...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Y-y-y-ou still haven't finished their task?", "V-v-você ainda não terminou a tarefa deles?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you can finish it, I can take the paperwork back to them.", "Se conseguir terminar, posso levar os documentos de volta para eles.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Y-y-y-ou finished the paperwork?", "V-v-você terminou a papelada?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can take it to th-them, but it'll take me a while.", "Posso levar para e-eles, mas vai demorar um pouco.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "G-g-go fight a battle while I deliver these papers...", "V-v-vá lutar uma batalha enquanto entrego estes papéis...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Th-th-thanks dude! I got my friend back from those creeps.", "Ob-ob-obrigado, cara! Recuperei meu amigo daqueles esquisitos.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He seems kind of restless though - do you think you can take him with you?", "Mas ele parece inquieto — você pode levá-lo com você?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shhhhh - be quiet.", "Shhhh — silêncio.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you have no business here, leave us alone.", "Se não tem nada para fazer aqui, deixe-nos em paz.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You wish to have back your friend?", "Você quer seu amigo de volta?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh but he's grown so dear to us.", "Ah, mas ele se tornou tão querido para nós.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A part of the family.", "É parte da família.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Truly we do care for him.", "Nós realmente nos importamos com ele.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No, no we won't just give you him.", "Não, não vamos simplesmente entregá-lo a você.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unless... You give something to us?", "A menos que... você nos dê algo?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unless... You do something for us?", "A menos que... você faça algo por nós?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yes. Yes. Take these files.", "Sim. Sim. Leve estes documentos.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Take them to [c:bR]battle[c:]. File them together. [c:bR]In order[c:].", "Leve-os à [c:bR]batalha[c:]. Arquive-os juntos. [c:bR]Em ordem[c:].", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Then [c:bR]stamp them all[c:] and bring them back.", "Depois [c:bR]carimbe todos[c:] e traga-os de volta.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Did we lag?", "Tivemos atraso?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "File them [c:bR]in order[c:] then [c:bR]stamp them[c:] and bring them back.", "Arquive-os [c:bR]em ordem[c:], depois [c:bR]carimbe-os[c:] e traga-os de volta.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You seem to struggle with following instructions.", "Parece que você tem dificuldade em seguir instruções.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We shall keep your friend.", "Ficaremos com seu amigo.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Forever...", "Para sempre...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You've done it!", "Você conseguiu!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good. Good.", "Bom. Bom.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here. Take it.", "Aqui. Pegue.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We have no use for it now.", "Não precisamos mais dele.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Now leave us alone.", "Agora deixe-nos em paz.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just who I needed to see. A challenger.", "Quem eu precisava ver. Um desafiante.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I haven't pelts to sell ye, catchings have been slim...", "Não tenho peles para lhe vender, a caça anda escassa...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Trader... She's not happy with it.", "A Comerciante... Ela não está feliz com isso.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Say, scratch my back here, and I will scratch yours.", "Vamos fazer um acordo: você me ajuda e eu ajudo você.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Talk to me again, and I'll make it worth your while.", "Fale comigo de novo, e farei valer a pena.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good! Glad t' have ye on th' team.", "Ótimo! É bom ter você na equipe.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have some holo-traps set around 'ere. Catch 'em for me and I'll get ye yer prize.", "Tenho algumas armadilhas holográficas por aqui. Capture-as para mim e entregarei seu prêmio.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There are still some traps around 'ere somewhere...", "Ainda há algumas armadilhas por aqui...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magnificent pelts. The Trader will be happy to see them.", "Peles magníficas. A Comerciante ficará feliz em vê-las.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'll take me leave to set my traps elsewhere. Ye have my thanks.", "Vou embora armar minhas armadilhas em outro lugar. Muito obrigado.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have no pelts...", "Você não tem peles...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Come back when you have some", "Volte quando tiver algumas", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That is a fine pelt. I will buy it from you.", "Esta é uma boa pele. Vou comprá-la de você.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That is an [c:bR]exceptional[c:] pelt. I have a special trade for you.", "Esta é uma pele [c:bR]excepcional[c:]. Tenho uma troca especial para você.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Woof. Apparently somebody screwed with the settings on this thing.", "Nossa. Parece que alguém bagunçou as configurações desta coisa.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It can't reach all of the map right now.", "Ela não alcança todo o mapa agora.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Go beat a boss or something while I work on this.", "Vá derrotar um chefe ou coisa assim enquanto eu trabalho nisso.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Seriously; it's going to take a while. Just play the game and come back later", "Sério, vai demorar um pouco. Continue jogando e volte mais tarde.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's partially fixed, but it still can't go everywhere.", "Está parcialmente consertado, mas ainda não alcança todos os lugares.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hey, I don't make the rules. This is just how it works.", "Ei, não sou eu que faço as regras. É assim que funciona.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Keep playing and more of the map will open up.", "Continue jogando e mais partes do mapa serão abertas.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's going to take more time. Just keep playing.", "Vai levar mais tempo. Continue jogando.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There you go. It's working now.", "Pronto. Agora está funcionando.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I need a break...", "Preciso de uma pausa...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have the right to remain silent!", "Você tem o direito de permanecer em silêncio!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is [c:bR][v:0][c:] and you are under arrest!", "Aqui é [c:bR][v:0][c:] e você está preso!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR][v:0][c:] here! You're not gettin' away this time!", "[c:bR][v:0][c:] na área! Você não vai escapar desta vez!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead or alive, you're coming with me!", "Vivo ou morto, você vem comigo!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I got you once before, and I can do it again!", "Já peguei você uma vez, posso fazer de novo!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Justice will come to you eventually!", "A justiça acabará alcançando você!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remember the name [c:bR][v:0][c:] - I will be back!", "Lembre-se do nome [c:bR][v:0][c:] — eu voltarei!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh, uh, hi there. My name's [c:bR][v:0][c:].", "Ah, é... olá. Meu nome é [c:bR][v:0][c:].", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I think I'm supposed to take your scalp, or something like that?", "Acho que devo arrancar seu couro cabeludo, ou algo assim?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you could just die right here that would make things so much easier for me.", "Se você pudesse morrer bem aqui, isso facilitaria muito minha vida.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yeah, it's me, [c:bR][v:0][c:]. Again.", "Sim, sou eu, [c:bR][v:0][c:]. De novo.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do you think you could make this easier for me this time?", "Será que você pode facilitar as coisas para mim desta vez?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh it's you. Didn't I kill you last time?", "Ah, é você. Não matei você da última vez?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And you're back? I have to do this all over again?", "E você voltou? Tenho que fazer tudo de novo?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm not sure I like this job.", "Não sei se gosto deste trabalho.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh. Dang it.", "Ah. Droga.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well, this is embarrassing.", "Bem, que vergonha.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I guess I'll be back later, or something. Being a bounty hunter is weird.", "Acho que voltarei mais tarde, ou algo assim. Ser caçador de recompensas é estranho.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This vessel is [c:bR][v:0][c:].", "Este recipiente é [c:bR][v:0][c:].", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "By my command, he will separate your scalp from your head.", "Por minha ordem, ele separará seu couro cabeludo da sua cabeça.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Why?", "Por quê?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My motivations are beyond your understanding.", "Minhas motivações estão além da sua compreensão.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have restored the vessel named [c:bR][v:0][c:].", "Restaurei o recipiente chamado [c:bR][v:0][c:].", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You shall not be so fortunate as to escape this time.", "Desta vez você não terá a sorte de escapar.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cower in fear before the vessel named [c:bR][v:0][c:]", "Trema de medo diante do recipiente chamado [c:bR][v:0][c:]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remember the pain of defeat and prepare to feel it once more.", "Lembre-se da dor da derrota e prepare-se para senti-la outra vez.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The spirit is willing but the steel is weak.", "O espírito está disposto, mas o aço é fraco.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I will not make the same mistake next time.", "Não cometerei o mesmo erro da próxima vez.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's quite enough of that.", "Já chega disso.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Now it has [c:g1]g[c:][c:g2]e[c:][c:g3]m[c:][c:g1]s[c:] built right in", "Agora ele já tem [c:g1]j[c:][c:g2]o[c:][c:g3]i[c:][c:g1]a[c:]s embutidas", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What? All of your cards are already gemified?", "O quê? Todas as suas cartas já estão Com Joias?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's almost impressive.", "Isso é quase impressionante.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I guess I'll let you pick a mox sigil to add instead.", "Acho que vou deixar você escolher um selo de mox para adicionar.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Looks like all your cards are gemified, so pick a mox sigil to add instead.", "Parece que todas as suas cartas estão Com Joias, então escolha um selo de mox para adicionar.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What? All of your cards are already skeleclocked?", "O quê? Todos os exoesqueletos de suas cartas já estão em overclock?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You are incredibly dedicated to this mediocre upgrade.", "Você é incrivelmente dedicado a esta melhoria medíocre.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I guess you'll have to choose one of these instead.", "Acho que você terá de escolher uma destas coisas.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Still nothing to upgrade? Pick one of these.", "Ainda não há nada para melhorar? Escolha uma destas coisas.", Language.BrazilianPortuguese);

            // DialogueState
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TOO EASY...", "FÁCIL DEMAIS...", Language.BrazilianPortuguese);
