            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, play a Gunbot in all empty spaces on the board.", "Quando [creature] é jogado, jogue um Robô Armado em todos os espaços vazios do tabuleiro.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sticker Lord", "Senhor dos Adesivos", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, all friendly cards get a random sticker.", "Enquanto [creature] estiver no tabuleiro, todas as cartas aliadas recebem um adesivo aleatório.", Language.BrazilianPortuguese);

            // Pack
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kaycee's P03 Expansion Pack #3", "Pacote de Expansão de P03 da Kaycee Nº 3", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They said it would never happen, but it's here! The third official expansion pack breaks all of the rules, with [count] new cards that bring bones, blood, and gems to Botopia!", "Disseram que nunca aconteceria, mas aqui está! O terceiro pacote de expansão oficial quebra todas as regras, com [count] cartas novas que trazem ossos, sangue e joias para Robotopia!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kaycee's P03 Encounter Expansion #3", "Expansão de Encontros de P03 da Kaycee Nº 3", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[count] additional encounters that feature cards from the third official P03 expansion pack.", "[count] encontros adicionais com cartas do terceiro pacote de expansão oficial de P03.", Language.BrazilianPortuguese);

