    public class InGameCardCreatorMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for InGame_Card_Creator Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You entered the [c:bR]card creation[c:] mode.", "Você entrou no modo de [c:bR]criação de cartas[c:].", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It appears that you lost normally.", "Parece que você perdeu normalmente.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Only worthy challengers may access the Card Creator.", "Somente desafiantes dignos podem acessar o Criador de Cartas.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Try again, but this time open the backroom door normally.", "Tente novamente, mas desta vez abra a porta da sala dos fundos normalmente.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "current card", "carta atual", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You should give it a name.", "Você deve dar um nome a ela.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please type the description.", "Digite a descrição.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is time for you to return.", "É hora de você voltar.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loading portraits.", "Carregando retratos.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "previous page", "página anterior", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "next page", "próxima página", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And another. This time I will use its [c:bR]power[c:].", "E mais uma. Desta vez usarei seu [c:bR]poder[c:].", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose the [c:bR]complexity[c:] of card. This determines when it is unlocked in the tutorial.", "Escolha a [c:bR]complexidade[c:] da carta. Isso determina quando ela será desbloqueada no tutorial.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "free", "Grátis", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please, choose a card to draw the [c:bR]cost[c:] from.", "Escolha uma carta da qual extrair o [c:bR]custo[c:].", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do you want to add another [c:bR]cost[c:]?", "Deseja adicionar outro [c:bR]custo[c:]?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose which card it will evolve into.", "Escolha em qual carta ela evoluirá.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose which card it will create upon death.", "Escolha qual carta ela criará ao morrer.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]How many turns[c:] should it take for this card to evolve?", "[c:bR]Quantos turnos[c:] esta carta deve levar para evoluir?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And another. This time I will use its [c:bR]health[c:].", "E mais uma. Desta vez usarei sua [c:bR]vida[c:].", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "regular", "Comum", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "rare", "rara", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "hidden", "Oculto", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose the [c:bR]type[c:] of card.", "Escolha o [c:bR]tipo[c:] da carta.", Language.BrazilianPortuguese);
