    public class AgasMagnificusExpansionMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for AgasMagnificusExpansion Mod");

            // Pack
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aga's Magnificus Expansion", "Expansão de Magnificus de Aga", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An unofficial expansion to the Magnificus Mod featuring [count] unique and colourful mages", "Uma expansão não oficial do Mod de Magnificus, com [count] magos únicos e coloridos.", Language.BrazilianPortuguese);

            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ascension Mage", "Mago da Ascensão", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Ascension Mage", "Mago da Ascensão", "Utilising the power of time they grant knowledge and experience from far beyond", "Usando o poder do tempo, transmitem conhecimentos e experiências de muito além.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Utilising the power of time they grant knowledge and experience from far beyond", "Usando o poder do tempo, transmitem conhecimentos e experiências de muito além.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ash Mage", "Mago das Cinzas", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Ash Mage", "Mago das Cinzas", "Ashes he sheds from his own body, scorching any and all who oppose him", "Cinzas se desprendem de seu corpo, queimando todos os que se opõem a ele.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ashes he sheds from his own body, scorching any and all who oppose him", "Cinzas se desprendem de seu corpo, queimando todos os que se opõem a ele.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Broken Egg", "Ovo Quebrado", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Broken Egg", "Ovo Quebrado", "Only the greatest of trainers might find this treasure", "Só os maiores treinadores poderão encontrar este tesouro.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Only the greatest of trainers might find this treasure", "Só os maiores treinadores poderão encontrar este tesouro.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chosen One", "Escolhido", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Chosen One", "Escolhido", "My selected favourite. He still clings to his elders though...", "O meu favorito escolhido. Embora ainda seja apegado aos mais velhos...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My selected favourite. He still clings to his elders though...", "O meu favorito escolhido. Embora ainda seja apegado aos mais velhos...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cleanliness Mage", "Mago da Limpeza", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Cleanliness Mage", "Mago da Limpeza", "The proudest of all my pupils. None come close to his bath superpowers", "O mais orgulhoso dos meus pupilos. Ninguém se compara aos seus superpoderes de banho.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The proudest of all my pupils. None come close to his bath superpowers", "O mais orgulhoso dos meus pupilos. Ninguém se compara aos seus superpoderes de banho.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cleric", "Clérigo", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Cleric", "Clérigo", "With the virtue of his divine Magicks, he bears the pain of all and rids them of their wounds", "Graças à sua magia divina, ele assume a dor de todos e cura suas feridas.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With the virtue of his divine Magicks, he bears the pain of all and rids them of their wounds", "Graças à sua magia divina, ele assume a dor de todos e cura suas feridas.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Clock Mage", "Mago do Relógio", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Clock Mage", "Mago do Relógio", "A wizard with a mastery over time itself. When he nears his demise, he reverts to the past, and comes back to life", "Um mago que domina o próprio tempo. Ao se aproximar da morte, ele volta ao passado e retorna à vida.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A wizard with a mastery over time itself. When he nears his demise, he reverts to the past, and comes back to life", "Um mago que domina o próprio tempo. Ao se aproximar da morte, ele volta ao passado e retorna à vida.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creature Collector", "Colecionador de Criaturas", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Creature Collector", "Colecionador de Criaturas", "He had searched far and wide for his little companion, you see", "Ele procurou por toda parte seu pequeno companheiro, sabe?");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He had searched far and wide for his little companion, you see", "Ele procurou por toda parte seu pequeno companheiro, sabe?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Division Mage", "Mago da Divisão", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Division Mage", "Mago da Divergência", "So the card says at least... I assumed those freaks were long dealth with", "Pelo menos é o que a carta diz... Pensei que aqueles esquisitos já tivessem sido eliminados há muito tempo.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So the card says at least... I assumed those freaks were long dealth with", "Pelo menos é o que a carta diz... Pensei que aqueles esquisitos já tivessem sido eliminados há muito tempo.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Egg", "Ovo", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Egg", "Ovo", "Only the greatest of trainers might find this treasure", "Só os maiores treinadores poderão encontrar este tesouro.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Only the greatest of trainers might find this treasure", "Só os maiores treinadores poderão encontrar este tesouro.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Druid", "Druida", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Druid", "Druida", "Nature's primal devotee, feeding on sapped mana to cure his allies", "Um devoto primordial da natureza, que consome mana extraída para curar seus aliados.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nature's primal devotee, feeding on sapped mana to cure his allies", "Um devoto primordial da natureza, que consome mana extraída para curar seus aliados.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enchanter", "Encantador", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Enchanter", "Encantador", "He spews cosmic magicks upon his demise, enchanting everything nearby", "Ao morrer, ele expele magia cósmica, encantando tudo que está por perto.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He spews cosmic magicks upon his demise, enchanting everything nearby", "Ao morrer, ele expele magia cósmica, encantando tudo que está por perto.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "EveryMage", "Mago Universal", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("EveryMage", "Mago Universal", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "mage", "mago", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("mage", "mago", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Evoker", "Evocador", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Evoker", "Evocador", "The ominous crettin of disgusting teachings. It's summonable snakes are of the deadliest caliber", "Um pateta sinistro de ensinamentos repugnantes. As serpentes que ele invoca estão entre as mais mortais.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ominous crettin of disgusting teachings. It's summonable snakes are of the deadliest caliber", "Um pateta sinistro de ensinamentos repugnantes. As serpentes que ele invoca estão entre as mais mortais.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Serpent Summon", "Invocar Serpente", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Serpent Summon", "Invocar Serpente", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Firebender", "Dobrador de Fogo", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Firebender", "Dobrador de Fogo", "Chipper in the heat of battle, he is always on the hunt for the next victim of his fireballs", "Animado no calor da batalha, ele está sempre procurando a próxima vítima de suas bolas de fogo.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chipper in the heat of battle, he is always on the hunt for the next victim of his fireballs", "Animado no calor da batalha, ele está sempre procurando a próxima vítima de suas bolas de fogo.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Foresight Mage", "Mago da Previsão", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Foresight Mage", "Mago da Previsão", "As he gazes upon your future, attacks that may come his way he forever predicts", "Ao observar seu futuro, ele prevê todos os ataques que possam vir em sua direção.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As he gazes upon your future, attacks that may come his way he forever predicts", "Ao observar seu futuro, ele prevê todos os ataques que possam vir em sua direção.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Foresight Mage", "Mago da Previsão", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Foresight Mage", "Mago da Previsão", "Gazing into the future, he may see any body who dares make an approach", "Olhando para o futuro, ele pode ver qualquer um que ouse se aproximar.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gazing into the future, he may see any body who dares make an approach", "Olhando para o futuro, ele pode ver qualquer um que ouse se aproximar.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Glacier", "Geleira", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Glacier", "Geleira", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gashadokuro", "Gashadokuro", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Gashadokuro", "Gashadokuro", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Sentinel", "Sentinela de Joias", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Gem Sentinel", "Sentinela de Joias", "the elite warrior unit enchanted with the aura of my moxen", "A unidade de guerreiros de elite encantada com a aura dos meus mox.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the elite warrior unit enchanted with the aura of my moxen", "A unidade de guerreiros de elite encantada com a aura dos meus mox.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grand Astrologer", "Grande Astrólogo", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Grand Astrologer", "Grande Astrólogo", "The battlefield is forever his playground, and space is his weapon. All is bare before him.", "O campo de batalha é para sempre seu parquinho, e o espaço é sua arma. Tudo fica exposto diante dele.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The battlefield is forever his playground, and space is his weapon. All is bare before him.", "O campo de batalha é para sempre seu parquinho, e o espaço é sua arma. Tudo fica exposto diante dele.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gravity Mage", "Mago da Gravidade", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Gravity Mage", "Mago da Gravidade", "A master of the forces of gravity. Any and all mox bend to his unwavering will", "Um mestre das forças da gravidade. Todo mox se curva à sua vontade inabalável.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A master of the forces of gravity. Any and all mox bend to his unwavering will", "Um mestre das forças da gravidade. Todo mox se curva à sua vontade inabalável.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Illusion Mage", "Mago da Ilusão", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Illusion Mage", "Mago da Ilusão", "Dawning his tricks and disguises, there is none scarier. At first glance", "Com seus truques e disfarces, não há ninguém mais assustador. À primeira vista.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dawning his tricks and disguises, there is none scarier. At first glance", "Com seus truques e disfarces, não há ninguém mais assustador. À primeira vista.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Infestation Mage", "Mago da Infestação", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Infestation Mage", "Mago da Infestação", "I suppose a usurping challenger such as yourself could endulge in a dosage of skinwalking", "Suponho que um desafiante usurpador como você possa se entregar a uma dose de magia de metamorfose.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I suppose a usurping challenger such as yourself could endulge in a dosage of skinwalking", "Suponho que um desafiante usurpador como você possa se entregar a uma dose de magia de metamorfose.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Insulting Mirror", "Espelho Insultuoso", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Insulting Mirror", "Espelho Insultuoso", "The Magick Menace Flies About All Spitting Taunts And Hurling Cheeky Comments, Your Anger, It Channels Into A Strength Of It's Own", "A Ameaça Mágica voa por aí, soltando provocações e comentários insolentes. Sua raiva ela transforma em força própria.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Magick Menace Flies About All Spitting Taunts And Hurling Cheeky Comments, Your Anger, It Channels Into A Strength Of It's Own", "A Ameaça Mágica voa por aí, soltando provocações e comentários insolentes. Sua raiva ela transforma em força própria.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Iron Maiden", "Dama de Ferro", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Iron Maiden", "Dama de Ferro", "My finest of paladins working the finest of hours. No soul goes through his grand wall", "O melhor dos meus paladinos trabalha por longas horas. Nenhuma alma atravessa sua grande muralha.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My finest of paladins working the finest of hours. No soul goes through his grand wall", "O melhor dos meus paladinos trabalha por longas horas. Nenhuma alma atravessa sua grande muralha.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kickmoxer", "Chutamox", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Kickmoxer", "Chutamox", "He dedicated his life to the art of combat, and may adapt to whomever he faces", "Ele dedicou a vida à arte do combate e pode se adaptar a qualquer adversário.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He dedicated his life to the art of combat, and may adapt to whomever he faces", "Ele dedicou a vida à arte do combate e pode se adaptar a qualquer adversário.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mass Grave", "Vala Comum", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Mass Grave", "Vala Comum", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Master Agairan", "Mestre Agairan", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Master Agairan", "Mestre Agairan", "The Crimson Chimera. The teacher of alchemy instills the deadliest of toxins", "A Quimera Carmesim. O professor de alquimia infunde as toxinas mais mortais.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Crimson Chimera. The teacher of alchemy instills the deadliest of toxins", "A Quimera Carmesim. O professor de alquimia infunde as toxinas mais mortais.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Master Bluetwo", "Mestre Bluetwo", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Master Bluetwo", "Mestre Bluetwo", "The steel knight of sapphire. Even after death her psychic presence commands our foes", "A cavaleira de aço da safira. Mesmo depois da morte, sua presença psíquica comanda nossos inimigos.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The steel knight of sapphire. Even after death her psychic presence commands our foes", "A cavaleira de aço da safira. Mesmo depois da morte, sua presença psíquica comanda nossos inimigos.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Master Doublin", "Mestre Doublin", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Master Doublin", "Mestre Doublin", "The Bone Lord's messiah. The teacher of prayer has learned apt essence stealing.", "O messias do Lorde Ossário. O professor de oração aprendeu a roubar essências com destreza.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bone Lord's messiah. The teacher of prayer has learned apt essence stealing.", "O messias do Lorde Ossário. O professor de oração aprendeu a roubar essências com destreza.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Megawizard", "Megamago", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Megawizard", "Megamago", "Hulking he is in his menace, meanacing he is in his dim. Such raw power would never last an eternity", "Enorme em sua ameaça, ameaçador em sua tolice. Um poder tão bruto jamais duraria para sempre.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hulking he is in his menace, meanacing he is in his dim. Such raw power would never last an eternity", "Enorme em sua ameaça, ameaçador em sua tolice. Um poder tão bruto jamais duraria para sempre.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Meteorologist", "Meteorologista", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Meteorologist", "Meteorologista", "They carefully observe the universe, casting storms of meteors upon whom they see fit. Maybe they're cruel? Maybe not? Only they know", "Observam atentamente o universo e lançam tempestades de meteoros sobre quem julgarem apropriado. Serão cruéis? Ou não? Só eles sabem.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They carefully observe the universe, casting storms of meteors upon whom they see fit. Maybe they're cruel? Maybe not? Only they know", "Observam atentamente o universo e lançam tempestades de meteoros sobre quem julgarem apropriado. Serão cruéis? Ou não? Só eles sabem.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Miniwizard", "Minimago", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Miniwizard", "Minimago", "A mage accursed by it's miniscule size. Worry not though, to such ends he found a solution.", "Um mago amaldiçoado por seu tamanho minúsculo. Mas não se preocupe, ele encontrou uma solução.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mage accursed by it's miniscule size. Worry not though, to such ends he found a solution.", "Um mago amaldiçoado por seu tamanho minúsculo. Mas não se preocupe, ele encontrou uma solução.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Phantom Thief", "Ladrão Fantasma", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Phantom Thief", "Ladrão Fantasma", "A billowing cloud of crime, darting in and out, and stealing his foes", "Uma nuvem ondulante de crimes, entrando e saindo para roubar seus inimigos.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A billowing cloud of crime, darting in and out, and stealing his foes", "Uma nuvem ondulante de crimes, entrando e saindo para roubar seus inimigos.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Preformence Mage", "Mago do Prólogo", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Preformence Mage", "Mago do Prólogo", "Who knows to what ends his mystery rabbit has been through", "Quem sabe por tudo que seu coelho misterioso já passou?");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Who knows to what ends his mystery rabbit has been through", "Quem sabe por tudo que seu coelho misterioso já passou?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Queen's Familiar", "Familiar da Rainha", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Queen's Familiar", "Familiar da Rainha", "A majestic chimera of beautiful beasts. It keeps it's armies close inside", "Uma quimera majestosa de belas feras. Ela mantém seus exércitos bem guardados dentro de si.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A majestic chimera of beautiful beasts. It keeps it's armies close inside", "Uma quimera majestosa de belas feras. Ela mantém seus exércitos bem guardados dentro de si.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "RisingHunger", "Fome Crescente", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("RisingHunger", "Fome Crescente", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Roach Familiar", "Familiar Barata", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Roach Familiar", "Familiar Barata", "A spiritually manufacrued cockroach. It's will allows it ressurection abilities! that ultimately fail.", "Uma barata criada espiritualmente. Sua vontade lhe concede o poder de ressuscitar! Que acaba falhando.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A spiritually manufacrued cockroach. It's will allows it ressurection abilities! that ultimately fail.", "Uma barata criada espiritualmente. Sua vontade lhe concede o poder de ressuscitar! Que acaba falhando.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shadow Wizard", "Mago das Sombras", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Shadow Wizard", "Mago das Sombras", "A mobster of the underseen. He calls the shadows to gang on it's foes", "Um mafioso das sombras. Ele convoca as sombras para atacar seus inimigos em grupo.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mobster of the underseen. He calls the shadows to gang on it's foes", "Um mafioso das sombras. Ele convoca as sombras para atacar seus inimigos em grupo.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shinobi", "Shinobi", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Shinobi", "Shinobi", "Warrior of the dark, They strike from the unawares, where nobody lays claim or sight", "Guerreiros das trevas, atacam de surpresa, onde ninguém os vê nem reivindica espaço.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warrior of the dark, They strike from the unawares, where nobody lays claim or sight", "Guerreiros das trevas, atacam de surpresa, onde ninguém os vê nem reivindica espaço.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shower Mage", "Mago do Chuveiro", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Shower Mage", "Mago do Chuveiro", "The outcast of my school and rightfully so! His levels of stentch could only be described with magic...", "O excluído da minha escola, e com razão! Seu fedor só poderia ser descrito por meio da magia...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The outcast of my school and rightfully so! His levels of stentch could only be described with magic...", "O excluído da minha escola, e com razão! Seu fedor só poderia ser descrito por meio da magia...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sludge Mage", "Mago do Lodo", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Sludge Mage", "Mago do Lodo", "An entity of unknown origins, powered off the ill spreading plague to all", "Uma entidade de origem desconhecida, alimentada pela doença que espalha a praga a todos.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An entity of unknown origins, powered off the ill spreading plague to all", "Uma entidade de origem desconhecida, alimentada pela doença que espalha a praga a todos.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sui-Sage", "Sábio Sui", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Sui-Sage", "Sábio Sui", "The leader of a pack, soon to be packed away", "O líder de uma matilha, prestes a ser despachado.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The leader of a pack, soon to be packed away", "O líder de uma matilha, prestes a ser despachado.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summoner", "Invocador", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Summoner", "Invocador", "A mad man of the arts of life, he creates it out of thin air. And with frightning sensibilities", "Um louco das artes da vida, que a cria do nada. E com uma sensibilidade assustadora.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mad man of the arts of life, he creates it out of thin air. And with frightning sensibilities", "Um louco das artes da vida, que a cria do nada. E com uma sensibilidade assustadora.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Symmetrical Mage", "Mago Simétrico", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Symmetrical Mage", "Mago Simétrico", "Everyone has two sides to them, you see. Especially once they mess with my temper", "Todos têm dois lados, sabe? Especialmente quando mexem com o meu temperamento.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Everyone has two sides to them, you see. Especially once they mess with my temper", "Todos têm dois lados, sabe? Especialmente quando mexem com o meu temperamento.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Teleportation Mage", "Mago do Teleporte", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Teleportation Mage", "Mago do Teleporte", "A herald of endless portals, jolting around the battlefield in infinitum and negating incoming strikes", "Um arauto de portais infinitos, saltando eternamente pelo campo de batalha e anulando golpes recebidos.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A herald of endless portals, jolting around the battlefield in infinitum and negating incoming strikes", "Um arauto de portais infinitos, saltando eternamente pelo campo de batalha e anulando golpes recebidos.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Torrent Mage", "Mago da Torrente", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Torrent Mage", "Mago da Torrente", "An apprentice of the ocean utilising it to drown the lands and the terrain above", "Um aprendiz do oceano, que o usa para afogar as terras e o terreno acima.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An apprentice of the ocean utilising it to drown the lands and the terrain above", "Um aprendiz do oceano, que o usa para afogar as terras e o terreno acima.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Untamed Dragon", "Dragão Indomado", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Untamed Dragon", "Dragão Indomado", "Legends whisper this beast, was once a companion to the mox master Goranj", "As lendas sussurram que esta fera já foi companheira de Verdaranja, mestre dos mox.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Legends whisper this beast, was once a companion to the mox master Goranj", "As lendas sussurram que esta fera já foi companheira de Verdaranja, mestre dos mox.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warlock", "Bruxo", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Warlock", "Bruxo", "A blackened wizard pursuiting the studies of the blood magicks. Such bleeding he turns into a horrible weapon", "Um mago enegrecido que estuda as artes da magia de sangue. Ele transforma esse sangramento em uma arma terrível.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A blackened wizard pursuiting the studies of the blood magicks. Such bleeding he turns into a horrible weapon", "Um mago enegrecido que estuda as artes da magia de sangue. Ele transforma esse sangramento em uma arma terrível.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wicked Witch", "Bruxa Perversa", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Wicked Witch", "Bruxa Perversa", "A flying jesting witch, laughing your sorrows and posioning your armies", "Uma bruxa voadora e brincalhona, que ri de suas tristezas e envenena seus exércitos.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A flying jesting witch, laughing your sorrows and posioning your armies", "Uma bruxa voadora e brincalhona, que ri de suas tristezas e envenena seus exércitos.", Language.BrazilianPortuguese);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acid Aura", "Aura Ácida", Language.BrazilianPortuguese);
            MagnificusMod.RegisterAbility("Acid Aura", "Aura Ácida");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] deals 1 damage to the creature opposing it every turn", "[creature] causa 1 de dano à criatura oposta a cada turno.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakening", "Despertar", Language.BrazilianPortuguese);
            MagnificusMod.RegisterAbility("Awakening", "Despertar");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it's owner chooses an ally creature to evolve into a higher form.", "Quando [creature] é jogada, quem a possui escolhe uma criatura aliada para evoluir a uma forma superior.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Backfire Strike", "Golpe de Recuo", Language.BrazilianPortuguese);
            MagnificusMod.RegisterAbility("Backfire Strike", "Golpe de Recuo");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] damages creatures that oppose those it attacks.", "[creature] causa dano às criaturas do seu próprio lado que estiverem diante dos alvos que ela ataca.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Guzzler", "Bebe-sangue", Language.BrazilianPortuguese);
            MagnificusMod.RegisterAbility("Blood Guzzler", "Bebe-sangue");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] deals damage, it gains 1 health for each damage dealt.", "Quando [creature] causa dano, ela ganha 1 de vida para cada ponto de dano causado.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brute Parasite", "Parasita Brutal", Language.BrazilianPortuguese);
            MagnificusMod.RegisterAbility("Brute Parasite", "Parasita Brutal");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, an Egg is created on the opposing space.", "Quando [creature] é jogada, um Ovo é criado no espaço oposto.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deluge", "Dilúvio", Language.BrazilianPortuguese);
            MagnificusMod.RegisterAbility("Deluge", "Dilúvio");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, opponent creatures with 0 power drown and get given the Waterborne sigil.", "Quando [creature] é jogada, criaturas adversárias com 0 de poder submergem e recebem o selo Aquático.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Division", "Divisão", Language.BrazilianPortuguese);
            MagnificusMod.RegisterAbility("Division", "Divisão");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After attacking, [creature] splits into 2 identical clones, each bearing half of it's original stats.", "Após atacar, [creature] se divide em 2 clones idênticos, cada um com metade de seus atributos originais.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sentry", "Sentinela", Language.BrazilianPortuguese);
            MagnificusMod.RegisterAbility("Sentry", "Sentinela");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature moves into the space opposing [creature], they are dealt 1 damage.", "Quando uma criatura se move para o espaço oposto a [creature], ela recebe 1 de dano.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah, let one never underestimate the speed of a Foresight Mage.", "Ah, jamais subestime a velocidade de um Mago da Previsão.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Healing Aura", "Aura de Cura", Language.BrazilianPortuguese);
            MagnificusMod.RegisterAbility("Healing Aura", "Aura de Cura");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] heals nearby allied creatures. The healing is proportionate to it's power.", "[creature] cura criaturas aliadas próximas. A cura é proporcional ao seu poder.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heart Stealer", "Ladrão de Corações", Language.BrazilianPortuguese);
            MagnificusMod.RegisterAbility("Heart Stealer", "Ladrão de Corações");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "when [creature] kills a creature, it gets added to your hand.", "Quando [creature] mata uma criatura, a criatura morta é adicionada à sua mão.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ignis Incant", "Encantamento Ígneo", Language.BrazilianPortuguese);
            MagnificusMod.RegisterAbility("Ignis Incant", "Encantamento Ígneo");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 blood for [creature] to deal 2 damage to a chosen opposing slot.", "Pague 1 sangue para que [creature] cause 2 de dano a um espaço adversário escolhido.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Intimidate", "Intimidar", Language.BrazilianPortuguese);
            MagnificusMod.RegisterAbility("Intimidate", "Intimidar");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is placed on the board, the creature opposing it will flee to their right.", "Quando [creature] é colocada no tabuleiro, a criatura oposta foge para a própria direita.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lonesome", "Solitário", Language.BrazilianPortuguese);
            MagnificusMod.RegisterAbility("Lonesome", "Solitário");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gains +1 power for each adjacent empty space.", "[creature] ganha +1 de poder por espaço vazio adjacente.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magic Burst", "Explosão Mágica", Language.BrazilianPortuguese);
            MagnificusMod.RegisterAbility("Magic Burst", "Explosão Mágica");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After perishing, creatures adjascent to [creature] have their powers increased by 1.", "Depois que [creature] perece, o poder das criaturas adjacentes aumenta em 1.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Psystrike", "Golpe Psíquico", Language.BrazilianPortuguese);
            MagnificusMod.RegisterAbility("Psystrike", "Golpe Psíquico");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After [creature] perishes, it manipulates the creature opposing it to strike both of it's adjascent allies.", "Depois que [creature] perece, ela manipula a criatura oposta para que ataque os próprios aliados adjacentes.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Serpent Master", "Mestre das Serpentes", Language.BrazilianPortuguese);
            MagnificusMod.RegisterAbility("Serpent Master", "Mestre das Serpentes");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of every turn, [creature] spawns a Summon Serpent on a space of it's owner's choosing. A Summon Serpent is defined as: 1 power, 1 health.", "No início de cada turno, [creature] cria uma carta Invocar Serpente em um espaço escolhido por quem a possui. Invocar Serpente tem 1 de poder e 1 de vida.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shadow Strike", "Golpe das Sombras", Language.BrazilianPortuguese);
            MagnificusMod.RegisterAbility("Shadow Strike", "Golpe das Sombras");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] calls upon the shadows of creatures adjascent to it's target to strike it as well.", "[creature] convoca as sombras das criaturas adjacentes ao seu alvo para também atacá-lo.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tidal Lock", "Rotação Sincronizada", Language.BrazilianPortuguese);
            MagnificusMod.RegisterAbility("Tidal Lock", "Rotação Sincronizada");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the beginning of it's owner's turn, [creature] will pull small creatures, like squirrels, into it's orbit.", "No início do turno de quem a possui, [creature] atrai criaturas pequenas, como Esquilos, para sua órbita.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wizard's Heart", "Coração do Bruxo", Language.BrazilianPortuguese);
            MagnificusMod.RegisterAbility("Wizard's Heart", "Coração do Bruxo");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a Mox card corresponding to the current gems you control takes it's place.", "Quando [creature] perece, uma carta de mox correspondente às gemas que você controla ocupa seu lugar.", Language.BrazilianPortuguese);

        }
    }
    public class MagModExpansionMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for MagModExpansion Mod");

            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beaver's Defense", "Defesa do Castor", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Beaver's Defense", "Defesa do Castor", "Curating defensive dams upon use, not bad for a dire situation.", "Cria barragens defensivas ao ser usado. Nada mal para uma situação difícil.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Curating defensive dams upon use, not bad for a dire situation.", "Cria barragens defensivas ao ser usado. Nada mal para uma situação difícil.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bomb Sage", "Sábio das Bombas", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Bomb Sage", "Sábio das Bombas", "When attacked, this sage is known for blowing up.. Literally and metaphorically.", "Quando atacado, este sábio é conhecido por explodir... Literal e figurativamente.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When attacked, this sage is known for blowing up.. Literally and metaphorically.", "Quando atacado, este sábio é conhecido por explodir... Literal e figurativamente.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boxing Champ", "Campeão de Boxe", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Boxing Champ", "Campeão de Boxe", "Rejecting the use of wands, this champion prefers to settle things with his fists.", "Recusando-se a usar varinhas, este campeão prefere resolver as coisas com os punhos.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rejecting the use of wands, this champion prefers to settle things with his fists.", "Recusando-se a usar varinhas, este campeão prefere resolver as coisas com os punhos.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brontosaurus", "Brontossauro", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Brontosaurus", "Brontossauro", "I LOVE DINO MOD!!!!!", "EU AMO O MOD DE DINOSSAUROS!!!!!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I LOVE DINO MOD!!!!!", "EU AMO O MOD DE DINOSSAUROS!!!!!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cheese Wizard", "Mago do Queijo", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Cheese Wizard", "Mago do Queijo", "As trained Chef-Magi, Cheese Wizards use their intellect and Mysticality to accomplish their goals.", "Como Magos-Chefs treinados, os Magos do Queijo usam inteligência e misticismo para alcançar seus objetivos.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As trained Chef-Magi, Cheese Wizards use their intellect and Mysticality to accomplish their goals.", "Como Magos-Chefs treinados, os Magos do Queijo usam inteligência e misticismo para alcançar seus objetivos.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cheezling", "Queijinho", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Cheezling", "Queijinho", "With cheese like this, who needs friends?", "Com um queijo desses, quem precisa de amigos?");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With cheese like this, who needs friends?", "Com um queijo desses, quem precisa de amigos?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Telepathy", "Telepatia", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Telepathy", "Telepatia", "A pupil can gather all the resources they need through sheer will alone.", "Um pupilo pode reunir todos os recursos necessários apenas com sua força de vontade.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A pupil can gather all the resources they need through sheer will alone.", "Um pupilo pode reunir todos os recursos necessários apenas com sua força de vontade.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Direct Hit", "Acerto Direto", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Direct Hit", "Acerto Direto", "Upon being casted, your opponent will instantly take three damage.", "Ao ser lançado, seu adversário sofrerá imediatamente três pontos de dano.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Upon being casted, your opponent will instantly take three damage.", "Ao ser lançado, seu adversário sofrerá imediatamente três pontos de dano.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mysterious Egg", "Ovo Misterioso", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Mysterious Egg", "Ovo Misterioso", "Who knows what could hatch from this egg...", "Quem sabe o que pode sair deste ovo...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Who knows what could hatch from this egg...", "Quem sabe o que pode sair deste ovo...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Faceless", "Sem-rosto", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Faceless", "Sem-rosto", "A hollow shell of a mage, desperately looking for something to call its own.", "Uma casca vazia de mago, procurando desesperadamente algo para chamar de seu.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A hollow shell of a mage, desperately looking for something to call its own.", "Uma casca vazia de mago, procurando desesperadamente algo para chamar de seu.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Faker", "Falsificador", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Faker", "Falsificador", "Lie. Cheat. Deny. The lengths the Faker will go to in order to escape unharmed...", "Mentir. Trapacear. Negar. O Farsante faz de tudo para escapar ileso...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lie. Cheat. Deny. The lengths the Faker will go to in order to escape unharmed...", "Mentir. Trapacear. Negar. O Farsante faz de tudo para escapar ileso...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Figletar", "Figletar", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Figletar", "Figletar", "A wiz who brought an evil king to a terrible fate, this one knows a thing or two in the ring.", "Um mago que deu a um rei maligno um destino terrível; ele entende um bocado de luta no ringue.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A wiz who brought an evil king to a terrible fate, this one knows a thing or two in the ring.", "Um mago que deu a um rei maligno um destino terrível; ele entende um bocado de luta no ringue.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Firestarter", "Iniciador de Incêndio", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Firestarter", "Iniciador de Incêndio", "Careful when casting this one, pupils have reported that the dueling grounds can get a little toasty.", "Cuidado ao lançar este feitiço; alguns pupilos dizem que o campo de duelo pode ficar um pouco quente.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Careful when casting this one, pupils have reported that the dueling grounds can get a little toasty.", "Cuidado ao lançar este feitiço; alguns pupilos dizem que o campo de duelo pode ficar um pouco quente.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fridge Mage", "Mago da Geladeira", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Fridge Mage", "Mago da Geladeira", "Its cold atmosphere will chill foes, weakening their offensive power.", "Sua atmosfera gelada esfria os inimigos, enfraquecendo seu poder de ataque.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its cold atmosphere will chill foes, weakening their offensive power.", "Sua atmosfera gelada esfria os inimigos, enfraquecendo seu poder de ataque.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gembro", "Mano das Joias", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Gembro", "Mano das Joias", "The ability to tank any hit once, this pupil has high gusto.", "Capaz de aguentar qualquer golpe uma vez, este pupilo tem coragem de sobra.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ability to tank any hit once, this pupil has high gusto.", "Capaz de aguentar qualquer golpe uma vez, este pupilo tem coragem de sobra.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Tick", "Carrapato de Joias", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Gem Tick", "Carrapato de Joias", "An elusive tick, which grants power to others via its mox body.", "Um carrapato esquivo que concede poder aos outros por meio de seu corpo de mox.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An elusive tick, which grants power to others via its mox body.", "Um carrapato esquivo que concede poder aos outros por meio de seu corpo de mox.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ghost Dinosaur", "Dinossauro Fantasma", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Ghost Dinosaur", "Dinossauro Fantasma", "I LOVE DINO MOD!!!!!", "EU AMO O MOD DE DINOSSAUROS!!!!!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I LOVE DINO MOD!!!!!", "EU AMO O MOD DE DINOSSAUROS!!!!!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Third Eye", "Terceiro Olho", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Third Eye", "Terceiro Olho", "Harnessing the power of a third eye, the spell allows its caster to gain any card that it has.", "Usando o poder de um terceiro olho, o feitiço permite escolher uma carta do restante do seu baralho e adicioná-la à sua mão.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Harnessing the power of a third eye, the spell allows its caster to gain any card that it has.", "Usando o poder de um terceiro olho, o feitiço permite escolher uma carta do restante do seu baralho e adicioná-la à sua mão.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baseball Mage", "Mago do Beisebol", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Baseball Mage", "Mago do Beisebol", "This mage's wand doubles as a baseball bat as well. It's suprisingly durable.", "A varinha deste mago também serve como taco de beisebol. É surpreendentemente resistente.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This mage's wand doubles as a baseball bat as well. It's suprisingly durable.", "A varinha deste mago também serve como taco de beisebol. É surpreendentemente resistente.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ice Golem", "Golem de Gelo", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Ice Golem", "Golem de Gelo", "Hailing from an icy mountaintop, melting never seemed to phase this brute.", "Vinda do topo de uma montanha gelada, esta fera nunca pareceu se incomodar em derreter.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hailing from an icy mountaintop, melting never seemed to phase this brute.", "Vinda do topo de uma montanha gelada, esta fera nunca pareceu se incomodar em derreter.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Looting Bandit", "Bandido Saqueador", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Looting Bandit", "Bandido Saqueador", "A distant follower of the Master Orlu's Valkyries, training to become just like them.", "Uma seguidora distante das Valquírias da Mestra Laranul, treinando para se tornar como elas.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A distant follower of the Master Orlu's Valkyries, training to become just like them.", "Uma seguidora distante das Valquírias da Mestra Laranul, treinando para se tornar como elas.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mana Mage", "Mago de Mana", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Mana Mage", "Mago de Mana", "Brings together the energy that emits from Mana to deliver powerful strikes.", "Reúne a energia emitida pela Mana para desferir golpes poderosos.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brings together the energy that emits from Mana to deliver powerful strikes.", "Reúne a energia emitida pela Mana para desferir golpes poderosos.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pondering Pupil", "Aprendiz Pensativo", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Pondering Pupil", "Aprendiz Pensativo", "It draws from your gem pile using the powers of its mind alone.", "Compra cartas da sua pilha de gemas usando apenas os poderes da mente.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It draws from your gem pile using the powers of its mind alone.", "Compra cartas da sua pilha de gemas usando apenas os poderes da mente.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mirror Mage", "Mago do Espelho", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Mirror Mage", "Mago do Espelho", "Mirror, mirror, on the wall, who's the best Scrybe of them all?", "Espelho, espelho meu, qual é o melhor Patrono que já apareceu?");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mirror, mirror, on the wall, who's the best Scrybe of them all?", "Espelho, espelho meu, qual é o melhor Patrono que já apareceu?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whack-A-Mage", "Acerte-o-mago", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Whack-A-Mage", "Acerte-o-mago", "Always popping up to cause mischief whenever he can.", "Sempre aparece para causar confusão quando tem oportunidade.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Always popping up to cause mischief whenever he can.", "Sempre aparece para causar confusão quando tem oportunidade.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mononykus", "Monônico", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Mononykus", "Monônico", "I LOVE DINO MOD!!!!!", "EU AMO O MOD DE DINOSSAUROS!!!!!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I LOVE DINO MOD!!!!!", "EU AMO O MOD DE DINOSSAUROS!!!!!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PLUTO", "PLUTÃO", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("PLUTO", "PLUTÃO", "Hmph. So this is where that one went.", "Humph. Então foi parar aqui.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmph. So this is where that one went.", "Humph. Então foi parar aqui.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protect", "Proteger", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Protect", "Proteger", "In a tough spot? This spell will give one of your cards full immunity to the next attack it recieves.", "Em apuros? Este feitiço dá a uma das suas cartas imunidade completa ao próximo ataque que receber.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In a tough spot? This spell will give one of your cards full immunity to the next attack it recieves.", "Em apuros? Este feitiço dá a uma das suas cartas imunidade completa ao próximo ataque que receber.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pterodactyl", "Pterodáctilo", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Pterodactyl", "Pterodáctilo", "I LOVE DINO MOD!!!!!", "EU AMO O MOD DE DINOSSAUROS!!!!!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I LOVE DINO MOD!!!!!", "EU AMO O MOD DE DINOSSAUROS!!!!!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rabbid Sage", "Sábio Rabbid", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Rabbid Sage", "Sábio Rabbid", "A raving magician with a field of electricity at his disposal.", "Um mago ensandecido com um campo elétrico à sua disposição.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A raving magician with a field of electricity at his disposal.", "Um mago ensandecido com um campo elétrico à sua disposição.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skelemox", "Esquelemox", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Skelemox", "Esquelemox", "A poor skeleton being controlled by a Green Mox, I almost feel bad for it.", "Um pobre esqueleto controlado por um Mox Verde. Quase tenho pena dele.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A poor skeleton being controlled by a Green Mox, I almost feel bad for it.", "Um pobre esqueleto controlado por um Mox Verde. Quase tenho pena dele.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slime Wiz", "Mago de Gosma", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Slime Wiz", "Mago de Gosma", "It'll use the slime against the enemies, to drop their attack whence struck.", "Usa seu lodo contra os inimigos, reduzindo o ataque deles quando o atingem.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It'll use the slime against the enemies, to drop their attack whence struck.", "Usa seu lodo contra os inimigos, reduzindo o ataque deles quando o atingem.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Smug Witch", "Bruxa Convencida", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Smug Witch", "Bruxa Convencida", "The smuggest pupil in all the land. Legends say his Smug Throw is unrivaled.", "O pupilo mais convencido de toda a terra. Diz a lenda que seu Arremesso Convencido é incomparável.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The smuggest pupil in all the land. Legends say his Smug Throw is unrivaled.", "O pupilo mais convencido de toda a terra. Diz a lenda que seu Arremesso Convencido é incomparável.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summon Spear", "Lança de Invocação", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Summon Spear", "Lança de Invocação", "Roots up a spear from the ground, acting as a sturdy counter.", "Arranca uma lança do chão, servindo como uma defesa firme.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Roots up a spear from the ground, acting as a sturdy counter.", "Arranca uma lança do chão, servindo como uma defesa firme.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spike Mage", "Mago dos Espinhos", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Spike Mage", "Mago dos Espinhos", "This mage learned from the best of my Pike Mage's Scarecrows.", "Este mago aprendeu com o melhor dos Espantalhos do meu Mago da Lança.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This mage learned from the best of my Pike Mage's Scarecrows.", "Este mago aprendeu com o melhor dos Espantalhos do meu Mago da Lança.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "T-Rex", "Tiranossauro", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("T-Rex", "Tiranossauro", "I LOVE DINO MOD!!!!!", "EU AMO O MOD DE DINOSSAUROS!!!!!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I LOVE DINO MOD!!!!!", "EU AMO O MOD DE DINOSSAUROS!!!!!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Virtual King", "Rei Virtual", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Virtual King", "Rei Virtual", "Self-proclaimed ruler of the virtual lands who won't abide to measly “card game rules”.", "Autoproclamado governante das terras virtuais, que não se curva a meras “regras de jogo de cartas”.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Self-proclaimed ruler of the virtual lands who won't abide to measly “card game rules”.", "Autoproclamado governante das terras virtuais, que não se curva a meras “regras de jogo de cartas”.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moron Core", "Núcleo Idiota", Language.BrazilianPortuguese);
            MagnificusMod.RegisterCard("Moron Core", "Núcleo Idiota", "An odd core hailing from an abandoned factory, hates the word \"moron\".", "Um núcleo estranho vindo de uma fábrica abandonada. Odeia a palavra “idiota”.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An odd core hailing from an abandoned factory, hates the word \"moron\".", "Um núcleo estranho vindo de uma fábrica abandonada. Odeia a palavra “idiota”.", Language.BrazilianPortuguese);

            // Pack
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Smughtro's MagMod Expansion", "Expansão MagMod de Smughtro", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Adds 19 common cards, 7 rare cards, 7 spells, and 6 token cards to Magnificus Mod.", "Adiciona 19 cartas comuns, 7 cartas raras, 7 feitiços e 6 cartas de ficha ao Mod de Magnificus.", Language.BrazilianPortuguese);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death Assist", "Ajuda na Morte", Language.BrazilianPortuguese);
            MagnificusMod.RegisterAbility("Death Assist", "Ajuda na Morte");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it will deal 3 damage to the opponent.", "Quando uma carta com este selo perece, causa 3 de dano ao adversário.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emmental Elemental", "Elemental de Emmental", Language.BrazilianPortuguese);
            MagnificusMod.RegisterAbility("Emmental Elemental", "Elemental de Emmental");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, summon a Cheezling.", "Quando uma carta com este selo é jogada, invoca um Queijinho.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "First Strike", "Primeiro Golpe", Language.BrazilianPortuguese);
            MagnificusMod.RegisterAbility("First Strike", "Primeiro Golpe");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, it will instantly attack the opposing lane. If there are no opposing cards, no damage will be dealt.", "Quando uma carta com este selo é jogada, ataca imediatamente a coluna oposta. Se não houver carta adversária, nenhum dano será causado.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unknown Hatching", "Eclosão Desconhecida", Language.BrazilianPortuguese);
            MagnificusMod.RegisterAbility("Unknown Hatching", "Eclosão Desconhecida");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of your turn, a card bearing this sigil will hatch into a random dinosaur.", "No início do turno de quem a possui, uma carta com este selo eclode em um dinossauro aleatório.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Healthy Death", "Morte Saudável", Language.BrazilianPortuguese);
            MagnificusMod.RegisterAbility("Healthy Death", "Morte Saudável");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, the cards to the left and right of the sigil bearer heal 1 health.", "Quando uma carta com este selo perece, as cartas à sua esquerda e direita recuperam 1 de vida.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mana Mess", "Caos de Mana", Language.BrazilianPortuguese);
            MagnificusMod.RegisterAbility("Mana Mess", "Caos de Mana");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, draw a random non-rare Mana costing card.", "Quando uma carta com este selo é jogada, compre uma carta aleatória não rara que custe Mana.", Language.BrazilianPortuguese);

        }
    }
    public class FloweysMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for FloweysMod Mod");


            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flowey", "Flowey", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A fanatical leader hell-bent on bringing about the apocalypse by reviving the great Cthulhu through behind-the-scenes scheming.", "Um líder fanático, decidido a provocar o apocalipse ao ressuscitar o grande Cthulhu por meio de tramas nos bastidores.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You Idiot", "Seu Idiota", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You really are an Idiot if you think you can defeat me!", "Você é mesmo um idiota se acha que pode me derrotar!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Omega Flowey", "Flowey Ômega", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You really are an idiot.", "Você é mesmo um idiota.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Patience", "Paciência", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "patient.", "paciente.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bravery", "Bravura", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brave.", "Corajoso.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Integrity", "Integridade", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "integrant.", "Íntegro.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perseverence", "Perseverança", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Persevering.", "Perseverante.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kindness", "Bondade", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kind.", "Bondoso.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Justice", "Justiça", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Justice.", "Justiça.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Howdy- Uh i meant Are you ready to Die?", "Olá! Quer dizer... Está pronto para morrer?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Howdy! it's me Flowey, Flowey the Flower!", "Olá! Sou eu, Flowey, Flowey a Flor!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You know whats going on here, dont you?", "Você sabe o que está acontecendo aqui, não sabe?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You just wanted to see me suffer[c:0]!", "Você só queria me ver sofrer[c:0]!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do You know that ive been watching you?", "Você sabia que eu estava observando você?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well i took over Inscryption now!", "Pois bem, agora eu tomei conta de Inscryption!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "and i know what Secrets are hiding beneath Inscryption...", "E eu sei que segredos estão escondidos por trás de Inscryption...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Now nothing stands in my Way to take over the World now!", "Agora nada pode me impedir de dominar o mundo!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What do you think this Fight was about?", "O que você achou que era esta luta?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I just used it as a cover to snoop through Inscryptions Files!", "Eu só a usei como disfarce para fuçar nos arquivos de Inscryption!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And your PC of course!", "E o seu computador, é claro!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And you may have noticed, BUT iam now connected to the Internet!", "E talvez você tenha percebido, MAS agora estou conectado à internet!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So now its time to begin Uploading Inscryption!", "Então chegou a hora de começar a enviar Inscryption!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You REALLY are an Idiot!", "Você é MESMO um idiota!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't even need the Power of Human Souls if i just use the OLD_DATA!", "Nem preciso do poder das almas humanas se eu usar os DADOS_ANTIGOS!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Do you know what you are achieving by this? Nothing", "[c:bR]Sabe o que consegue com isso? Nada.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]You cant get rid of me! No matter what you do, i will always be there!", "[c:bR]Você não pode se livrar de mim! Não importa o que faça, estarei sempre aqui!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Th- The Souls?", "[c:bR]A-as almas?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]wh- where are my Powers?", "[c:bR]O-onde estão meus poderes?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]WHAT HAVE YOU DONE?!", "[c:bR]O QUE VOCÊ FEZ?!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Floweys Defence dropped to [c:bR]0!", "A defesa de Flowey caiu para [c:bR]0!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]NOOOOOO", "[c:bR]NÃÃÃÃO!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What just happened...", "O que acabou de acontecer...?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmph seemms you have won this time...", "Humph, parece que você venceu desta vez...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]NOBODY IS GOING TO HELP YOU!", "[c:bR]NINGUÉM VAI AJUDAR VOCÊ!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "STOP CALLING FOR [c:bR]HELP!", "PARE DE PEDIR [c:bR]AJUDA!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Did you really think id let you kill me so easily?", "[c:bR]Você realmente achou que eu deixaria você me matar tão facilmente?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]what the-", "[c:bR]Mas que...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Flowey thought they could just use me...", "[c:bR]Flowey achou que podia simplesmente me usar...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]He didnt even know what I am!", "[c:bR]Ele nem sabia o que eu sou!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]But now IAM in control...", "[c:bR]Mas agora EU estou no controle...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]How pathetic of him to not set his HP to Infinite... I won't make that mistake", "[c:bR]Que patético ele não ter definido sua vida como infinita... Eu não cometerei esse erro.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Try all you want you can't kill me!", "[c:bR]Tente o quanto quiser, você não pode me matar!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Now lets see what this does...", "[c:bR]Agora vamos ver o que isto faz...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]WHY CANT I UNDO THIS???", "[c:bR]POR QUE NÃO CONSIGO DESFAZER ISSO???", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SEEING YOU DIE OVER AND OVER AGIAN IS REALLY [c:bR]FUN!", "VER VOCÊ MORRER DE NOVO E DE NOVO É MUITO [c:bR]DIVERTIDO!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NOT EVEN A SINGLE POINT OF DAMAGE!", "NEM UM ÚNICO PONTO DE DANO!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SOMEONE LIKE [c:bR]YOUCANT BEAT ME!", "ALGUÉM COMO [c:bR]VOCÊ NÃO PODE ME VENCER!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Starvation wont interrupt this fight!", "[c:bR]A Inanição não vai interromper esta luta!", Language.BrazilianPortuguese);


        }
    }
    public class UndertaleMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for UndertaleMod Mod");

            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Card Pack:U", "Pacote de Cartas: Undertale", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aaron", "Aaron", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah yes, Aaron the bold, aaron the beautiful. can you manage to take your eyes off his muscles?", "Ah, sim, Aaron, o ousado, Aaron, o belo. Consegue tirar os olhos dos músculos dele?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alphys", "Alphys", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dr. Alphys is responsible for the creation of some of the more 'unnerving' individuals you've seen here... or should I say... MULTI-viduals.", "A Dra. Alphys é responsável pela criação de alguns dos indivíduos mais “perturbadores” que você viu aqui... Ou seria melhor dizer... MULTIvíduos?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loveable, yet pestulant. The duality of this creature is unparalleled.", "Adorável, mas irritante. A dualidade desta criatura é incomparável.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Asgore", "Asgore", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The king of monsters... he truly is an intimidating force of brute strength, but also... compassion?", "O rei dos monstros... Sua força bruta é intimidadora, mas ele também tem... compaixão?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "asriel dreemurr", "Asriel Dreemurr", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the most powerful being in the underground... hopefully you find some use for him.", "O ser mais poderoso do Subsolo... espero que você encontre alguma utilidade para ele.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Astigmatism", "Astigmatismo", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The frustrating astigmatism... it can't make up its mind.", "O frustrante Astigmatism... não consegue se decidir.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gaster Blaster", "Canhão de Gaster", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Block of Ice", "Bloco de Gelo", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A peculiarly large ice cube... Who knows what could be inside.", "Um cubo de gelo excepcionalmente grande... Quem sabe o que há dentro.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chara", "Chara", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dogamy", "Dogamy", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dogamy and his wife, Dogaressa, love to tag-team the battlefield. Just don't let one of them perish...", "Dogamy e sua esposa, Dogaressa, adoram lutar em dupla. Só não deixe nenhum dos dois perecer...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dogaressa", "Dogaressa", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Doggo", "Doggo", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah, the blind doggo... He leaps towards any sound of movement.", "Ah, o cão cego... Ele salta em direção a qualquer som de movimento.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "doodlebog", "Doodlebog", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dummy", "Boneco", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the bland dummy... not as charismatic as its 'mad' counterpart", "O boneco sem graça... não é tão carismático quanto seu equivalente “zangado”.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amalgamate", "Amálgama", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Endogeny", "Endogeny", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "null", "nulo", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Final Froggit", "Froggit Final", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah yes, the ultimate boss of froggits... Still as easily fooled as its lesser evolved kin.", "Ah, sim, o líder supremo dos Froggits... Ainda tão fácil de enganar quanto seus parentes menos evoluídos.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frisk", "Frisk", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Froggit", "Froggit", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah yes, as shy as they come... the froggit wishes not to engage in conflict. how unfortunate.", "Ah, tão tímido quanto possível... o Froggit não deseja entrar em conflito. Que pena.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "W.D.Gaster", "W.D. Gaster", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "glyde", "Glyde", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such a narcisist, it can only attack if a card is in front of it to watch.", "Tão narcisista que só ataca se houver uma carta à sua frente para assistir.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greater Dog", "Cachorro Maior", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "truly and nobly adequate, it is the highest form of evolution a canine can become.", "Verdadeiramente nobre e competente, é a forma mais evoluída que um canino pode alcançar.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gyftrot", "Gyftrot", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Be kind to this creature, it has gone through enough.", "Seja gentil com esta criatura, ela já passou por muita coisa.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ice Wolf", "Lobo de Gelo", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah yes, this buff creature spawns a block of ice upon death.", "Ah, sim, esta criatura musculosa cria um bloco de gelo ao morrer.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Icecap", "Icecap", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jerry", "Jerry", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just ditch him already.", "Deixe-o de lado de uma vez.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Knight Knight", "Cavaleiro Noturno", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ah, the forboding knight knight... a sentinel of sleep. She is relentless in her conquest..", "Ah, a ameaçadora Knight Knight... uma sentinela do sono. Ela é implacável em sua conquista...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lemon Bread", "Pão de Limão", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lesser Dog", "Cachorro Menor", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mediocre canine at best... at least in its current form.", "Um cão medíocre, no máximo... pelo menos em sua forma atual.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loox", "Loox", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The cunning Loox EyeWalker... you would be wise not to pick on him.", "O esperto Loox EyeWalker... seria sensato não provocá-lo.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mad Dummy", "Boneco Louco", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dummy?", "Boneco?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Looks can be deceiving...", "As aparências enganam...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Madjick", "Madjick", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "quite the magician...", "Um mágico e tanto...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Memoryhead", "Cabeça de Memória", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mettaton", "Mettaton", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A hyper-intelligent, systematic, complex data analyzer... reminds me of an old 'friend'.", "Um analisador de dados extremamente inteligente, sistemático e complexo... Lembra um velho “amigo”.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mettaton Ex", "Mettaton EX", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Migosp", "Migosp", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the irritable Migosp... its attack increases in a crowd.", "O irritável Migosp... seu ataque aumenta em meio à multidão.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Migospel", "Migospel", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moldbygg", "Moldbygg", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moldsmal", "Moldsmal", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This one's giving me imposter vibes.", "Este aqui parece um impostor.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moldessa", "Moldessa", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ah, the gelatinous moldsmal. you probably never wondered what it's made of.", "Ah, o gelatinoso Moldsmal. Você provavelmente nunca se perguntou do que ele é feito.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Muffet", "Muffet", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah yes, the spider queen. her rapid play game is remarkable.", "Ah, sim, a rainha das aranhas. Sua rapidez ao jogar é impressionante.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Napstablook", "Napstablook", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The most melancholy of ghosts... it cares not of battle, but still fights to impress.", "O mais melancólico dos fantasmas... não liga para a batalha, mas ainda luta para impressionar.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "onionsan", "Onionsan", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not much strategy with one... It becomes a random tentcle card one the second turn.", "Não há muita estratégia aqui... No segundo turno, ele se transforma em uma carta de tentáculo aleatória.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A boney brute, papyrus is. He will generate bones like nobody's business.", "Papyrus é um brutamontes de ossos. Ele gera ossos como ninguém.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parsnik", "Parsnik", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pyrope", "Pyrope", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Pyrope wants nothing more than to crank up the heat, let's see how fatal that can be.", "Pyrope só quer aumentar o calor. Vamos ver quanto isso pode ser fatal.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reaper Bird", "Pássaro Ceifador", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Royal Guards", "Guardas Reais", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "two star-crossed lovers... will they ever focus on what's important?", "Dois amantes de destino cruel... Será que algum dia vão se concentrar no que importa?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "if you pick this card, i feel like i'm going to have a bad time.", "Se escolher esta carta, acho que vou passar maus bocados.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shyren", "Shyren", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The musically inclined shyren... strike her bells to watch her sing.", "A musical Shyren... toque seus sinos para ouvi-la cantar.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snowdrake", "Snowdrake", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The laughable Snowdrake... striving to prove his father wrong. Will you let him succeed?", "O engraçado Snowdrake... tentando provar que seu pai está errado. Você vai deixá-lo conseguir?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So Cold", "Tanto Frio", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "so sorry", "me desculpe", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "he's very sorry", "ele sente muito", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Temmie", "Temmie", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Temmie the immortal cat... at least i think she's a feline. Nothing to lose, everything to gain.", "Temmie, a gata imortal... ao menos acho que é um felino. Nada a perder, tudo a ganhar.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Toriel", "Toriel", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The keeper of the ruins... She will protect your side of the board to the best of her ability.", "A guardiã das ruínas... Ela protegerá seu lado do tabuleiro com todas as forças.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tsunderplane", "Tsunderplane", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "She can't decide between wanting your attention and wanting you to back off... i suggest the latter.", "Ela não consegue decidir se quer sua atenção ou que você se afaste... Sugiro a segunda opção.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undyne", "Undyne", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How could I forget Undyne? She is a true warrior, with an almighty aim on her spear.", "Como eu poderia me esquecer de Undyne? Uma verdadeira guerreira, com uma mira formidável para sua lança.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vegetoid", "Vegetoid", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "eat your greens. (not monitored by the fda)", "Coma seus vegetais. (Não fiscalizado pela FDA.)", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vulkin", "Vulkin", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A very passionate creature, this one. It's not his intention to harm, but that doesn't stop him.", "Uma criatura muito entusiasmada. Ele não pretende machucar ninguém, mas isso não o impede.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whimsalot", "Whimsalot", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the noble whimsalot... pray that it deems your conquest riteous.", "O nobre Whimsalot... reze para que ele considere sua conquista justa.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whimsun", "Whimsun", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the insignificant whimsun... it flees the battle after a single attack.", "O insignificante Whimsun... ele foge da batalha depois de atacar uma única vez.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Woshua", "Woshua", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This creature has no lust for blood. His will lies with helping others. But it will fight if provoked.", "Esta criatura não tem sede de sangue. Ela quer ajudar os outros, mas lutará se for provocada.", Language.BrazilianPortuguese);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Antisocial", "Antissocial", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will gain an attack buff if you have at least 1 other card on your side of the board.", "Uma carta com este selo recebe um bônus de ataque se houver pelo menos 1 outra carta do seu lado do tabuleiro.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cleanser", "Purificador", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will heal every card on its owner's side of the board, except the sigil bearer, for 1 health, at the start of every turn.", "No início da fase de combate de seu dono, uma carta com este selo recupera 1 de vida de todas as outras cartas do lado dele no tabuleiro.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Determination", "Determinação", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will move to any open slot its owner chooses, it will also gain EXP and LV after a kill. But is that really what you want?", "Uma carta com este selo pode se mover para qualquer espaço vazio escolhido por quem a possui. Também ganha experiência e nível ao matar uma criatura. Mas é isso mesmo que você quer?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Incendiary", "Incendiário", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil damages a card, that card gains the \"ablaze\" sigil. While a card is ablaze, it will lose one health per turn.", "Quando uma carta com este selo ataca outra carta, o alvo recebe Em Chamas. Uma carta em chamas recebe 1 de dano no início da fase de combate de seu dono.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ablaze", "Em Chamas", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will take 1 damage at the start of its owner's turn.", "Uma carta com este selo recebe 1 de dano no início da fase de combate de seu dono.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Indecisive", "Indeciso", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is struck, it has a 50/50 chance to either gain a stat buff, or perish; creating a copy of this card in your hand.", "Quando uma carta com este selo é atingida, há uma chance de 50/50 de receber um bônus de atributo ou perecer e criar uma cópia de si na sua mão.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Everyone knows Jerry. Makes Turns 2 seconds longer. Cards gain a stat buff when Jerry is killed or sacrificed.", "Todo mundo conhece Jerry. Ele prolonga os turnos em 2 segundos. As cartas do seu lado do tabuleiro recebem um bônus de atributo quando Jerry é morto ou sacrificado.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mercy", "Misericórdia", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A 'Determined' card will be granted this sigil when the card opposing it has low health, prompting the player to make a moral decision.", "Uma carta com Determinação recebe este selo quando a carta oposta tem pouca vida, levando o jogador a tomar uma decisão moral.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Insight", "Perspicácia", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do you wanna have a bad time?", "Você quer passar maus bocados?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Doodler", "Rabiscador", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is struck, it will sometimes summon doodlebogs on adjacent spaces.", "Quando uma carta com este selo é atingida, às vezes invoca Doodlebogs nos espaços adjacentes.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Timid", "Tímido", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When an opponent card moves into the opposing space of a card bearing this sigil, the sigil bearer will try to move one space over.", "Quando uma carta adversária se move para o espaço oposto a uma carta com este selo, a portadora tenta se mover um espaço para o lado.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You ditched Jerry.", "Você deixou Jerry para trás.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wow, you guys SUCK at this.", "Uau, vocês são PÉSSIMOS nisso.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The wi-fi here sucks.", "O wi-fi aqui é horrível.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SHHHH! Im THINKING, guys!!", "XIIIU! Estou PENSANDO, pessoal!!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Get your own, twerp.", "Arrume o seu, pirralho.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Why are we doing this? What a fail.", "Por que estamos fazendo isso? Que fracasso.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guys. its COLD. Does ANYONE care?", "Gente, está FRIO. ALGUÉM se importa?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ka-SIGH", "Ai, ai...", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DUH! Who DOESNT know?", "DÃ! Quem NÃO sabe?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well... can YOU give me a ride home?", "Bem... VOCÊ pode me levar para casa?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awkwarrrd.", "Que constrangimento.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So, like, what are you even doing?", "Então, tipo, o que você está fazendo?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Huh? Did they ditch me...? SOME friends!", "Hã? Eles me abandonaram...? Que belos amigos!", Language.BrazilianPortuguese);



        }
    }
    public class RevenantMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for RevenantMod Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DanseMacabre", "Dança Macabra", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Bones to reverse this sigil effect. At the end of the owner's turn, all creatures on the board gain 1 health.", "Pague 2 Ossos para inverter o efeito deste selo. No fim do turno de quem o possui, todas as criaturas no tabuleiro ganham 1 de vida.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LifeDraw", "Saque Vital", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Blood to draw a card from your main deck.", "Pague 1 Sangue para comprar uma carta da sua pilha principal.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soulgate", "Portão das Almas", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Bone to gain 1 Energy, lose as much Max Energy at the end of the owner's turn.", "Pague 1 Osso para ganhar 1 Energia. No fim do turno de quem a possui, perca a mesma quantidade de energia máxima.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Evocation", "Evocação", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 3 Energy to return the oldest non-Brittle allied creature from the graveyard to your hand.", "Pague 3 Energia para devolver à sua mão a criatura aliada sem Fragilidade que há mais tempo está no cemitério.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dormant", "Adormecido", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay Bones equal to the Power of [creature] to disable this sigil for 1 turn. [creature] cannot attack normally.", "Pague Ossos iguais ao poder de [creature] para desativar este selo por 1 turno. [creature] não pode atacar normalmente.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Transmute", "Transmutar", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Bones to transform [creature] to its alternate form.", "Pague 2 Ossos para transformar [creature] em sua forma alternativa.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protector", "Protetor", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creatures adjacent to [creature] gain 1 max health.", "Criaturas adjacentes a [creature] ganham 1 de vida máxima.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CalamityEffusion", "Extravasamento da Calamidade", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, all creatures on the board lose 1 health.", "No fim do turno de quem a possui, todas as criaturas no tabuleiro perdem 1 de vida.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ComfortAura", "Aura de Conforto", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, creatures adjacent to [creature] heal 1 health.", "No fim do turno de quem a possui, as criaturas adjacentes a [creature] recuperam 1 de vida.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CorpseParty", "Festa dos Cadáveres", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a non-brittle creature on the owner's side perishes by combat, a Zombie enters your hand. A Zombie is defined as: 1 Power, 1 Health.", "Quando uma criatura sem Fragilidade do lado de quem possui este selo perece em combate, um Zumbi entra na sua mão. Um Zumbi tem 1 de Poder e 1 de Vida.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DeathKnock", "Batida dos Mortos", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes by combat, it strikes back then perishes.", "Quando [creature] perece em combate, ela contra-ataca antes de perecer.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DeathMetal", "Metal da Morte", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, adjacent creatures and opposing creatures to the left, right, and center of it take 1 damage. It gains 1 Power for each affected creature.", "Quando [creature] é jogada, as criaturas adjacentes e as criaturas opostas à esquerda, à direita e no centro recebem 1 de dano. Ela ganha 1 de Poder para cada criatura afetada.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defiler", "Profanador", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, draw a card then choose one to discard from your hand.", "Quando [creature] perece, compre uma carta e escolha uma carta da sua mão para descartar.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Encroachment", "Invasão", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] creates a copy of it in your hand after 2 turns on the board.", "Após 2 turnos no tabuleiro, [creature] cria uma cópia de si na sua mão.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeletonize", "Esqueletizar", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a Skeleton with its old sigils enters your hand. A Skeleton is defined as: 1 Power, 1 Health, Brittle.", "Quando [creature] perece, um Esqueleto com seus selos antigos entra na sua mão. Um Esqueleto tem 1 de Poder, 1 de Vida e Fragilidade.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exorcise", "Exorcizar", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, Bones equal to the Bone cost of the opposing creature are granted to the player.", "Quando [creature] é jogada, o jogador recebe Ossos iguais ao custo em Ossos da criatura oposta.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ExplodingCorpse", "Cadáver Explosivo", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes by combat, all empty spaces on the board are filled with a Guts card.", "Quando [creature] perece em combate, todos os espaços vazios do tabuleiro são preenchidos com cartas de Entranhas.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GrudgeCollector", "Coletor de Rancor", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gains 1 power for every 2 times opponent creatures deal direct damage to its owner.", "[creature] ganha 1 de poder a cada 2 vezes que criaturas adversárias causam dano direto a quem a possui.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chime Power", "Poder dos Sinos", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented by this sigil will be equal to the number of Bell cards on the board.", "O valor representado por este selo é igual ao número de cartas de Sino no tabuleiro.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Digger Power", "Poder da Fonte de Ossos", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented by this sigil will be equal to the number of Bone and Digger related sigils on the board.", "O valor representado por este selo é igual ao número de selos relacionados a Ossos e escavação no tabuleiro.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ignition", "Ignição", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gains 1 power at the cost of 1 health after each turn on the board.", "[creature] ganha 1 de poder ao custo de 1 de vida após cada turno no tabuleiro.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Digger Latch", "Trava Escavadora", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will generate 1 Bone. When it perishes, its owner chooses a creature to gain the Bone Digger sigil.", "No fim do turno de quem a possui, [creature] gera 1 Osso. Quando ela perece, quem a possui escolhe uma criatura para receber o selo Fonte de Ossos.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Primed Digger Latch", "Trava de Fonte de Ossos Aprimorada", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will generate 1 Bone. When it perishes, its owner chooses a creature to gain this sigil.", "No fim do turno de quem a possui, [creature] gera 1 Osso. Quando ela perece, quem a possui escolhe uma criatura para receber este selo.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rejuvenation", "Rejuvenescimento", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the Fledgling sigil.", "Quando [creature] perece, quem a possui escolhe uma criatura para receber o selo Infante.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skull Storm", "Desafios para dar e vender", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, this sigil is replaced with another sigil at random. When it perishes, its owner chooses a creature to gain this sigil.", "No fim do turno de quem possui este selo, ele é substituído por outro selo aleatório. Quando a carta perece, quem a possui escolhe uma criatura para receber este selo.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ignite", "Incendiar", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the Ignition sigil.", "Quando [creature] perece, quem a possui escolhe uma criatura para receber o selo Ignição.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MacabreBonePulse", "Pulso Ósseo Macabro", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it perishes immediately, dropping Bones equal to double the amount of creatures on the owner's side.", "Quando [creature] é jogada, ela perece imediatamente, deixando Ossos em quantidade igual ao dobro das criaturas do lado de quem a possui.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maternal", "Maternal", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creatures adjacent to [creature] are inscrybed by Waterborne.", "As criaturas adjacentes a [creature] recebem o selo Aquático.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Necrosis", "Necrose", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] loses 1 power and 1 max health after each turn on the board.", "[creature] perde 1 de poder e 1 de vida máxima após cada turno no tabuleiro.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Limbo", "Limbo", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, it returns to the top of your deck.", "Quando [creature] perece, ela retorna ao topo do seu baralho.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "RelentlessRevenant", "Espectro Incansável", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the owner's turn, creatures adjacent to [creature] transform into a Revenant. A Revenant is defined as: 3 Power, 1 Health, Brittle.", "No início do turno de quem a possui, criaturas adjacentes a [creature] se transformam em Espectros. Um Espectro tem 3 de Poder, 1 de Vida e Fragilidade.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Revedue", "Retorno dos Espectros", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After attacking, [creature] perishes, then shuffle 2 Revenants with its old sigils into your side deck. A Revenant is defined as: 3 Power, 1 Health, Brittle.", "Após atacar, [creature] perece. Em seguida, embaralhe 2 Espectros com seus antigos selos no seu baralho auxiliar. Um Espectro tem 3 de Poder, 1 de Vida e Fragilidade.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bad Omen", "Mau Presságio", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will deal 1 damage to the owner.", "No fim do turno de quem a possui, [creature] causa 1 de dano a essa pessoa.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rancor", "Rancor", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, it leaves a permanent 1 power buff in the space it occupied.", "Quando [creature] perece, ela deixa um bônus permanente de 1 de poder no espaço que ocupava.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SoothingMeadows", "Prados Serenos", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, all creatures on the board gain 1 health.", "No fim do turno de quem a possui, todas as criaturas no tabuleiro ganham 1 de vida.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PartingStroke", "Golpe de Despedida", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a non-brittle creature on the owner's side perishes by combat, its owner chooses a creature to lose all of its sigils.", "Quando uma criatura sem Fragilidade do lado de quem possui este selo perece em combate, essa pessoa escolhe uma criatura para perder todos os seus selos.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SplittingCorpse", "Cadáver Dividido", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes by combat, create a Dysmorphia on each empty adjacent space.", "Quando [creature] perece em combate, cria uma Dismorfia em cada espaço adjacente vazio.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Torpid", "Torpe", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] cannot attack normally.", "[creature] não pode atacar normalmente.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grim Epitaph", "Epitáfio Sombrio", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, you may choose a card that has already been put to rest, to bring back to your hand.", "Quando [creature] é jogada, você pode escolher uma carta já posta para descansar e devolvê-la à sua mão.", Language.BrazilianPortuguese);


            //card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bigfoot", "Pé-grande", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a mysterious creature lurking the forests, only few have claimed to see one.", "Uma criatura misteriosa que espreita nas florestas. Poucos dizem tê-la visto.", Language.BrazilianPortuguese);
            GrimoraMod.RegisterCard("Bigfoot", "Pé-grande");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Goblin", "Goblin", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A loyal barbaric beast, a fine addition to your army.", "Uma fera bárbara e leal, uma ótima adição ao seu exército.", Language.BrazilianPortuguese);
            GrimoraMod.RegisterCard("Goblin", "Goblin");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vila", "Vila", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Love at first sight, at least that's what it wants you to think.", "Amor à primeira vista. Pelo menos é o que ele quer que você pense.", Language.BrazilianPortuguese);
            GrimoraMod.RegisterCard("Vila", "Vila");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yaramayawho", "Yara-ma-yha-who", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This one can never seem to finish it's meals...", "Parece que este nunca consegue terminar suas refeições...", Language.BrazilianPortuguese);
            GrimoraMod.RegisterCard("Yaramayawho", "Yara-ma-yha-who");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Test Limbs", "Membros de Teste", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Those parts used to belong to someone, or now some thing...(Test)", "Essas partes já pertenceram a alguém, ou agora a alguma... coisa... (Teste)", Language.BrazilianPortuguese);
            GrimoraMod.RegisterCard("Test Limbs", "Membros de Teste");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Allip", "Allip", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The remnants of the insane! You never know what story lies behind that face, but it's sure to be filled with fervor.", "Os restos dos insanos! Nunca se sabe que história há por trás daquele rosto, mas ela certamente transborda fervor.", Language.BrazilianPortuguese);
            GrimoraMod.RegisterCard("Allip", "Allip");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amami Rabbit", "Coelho-de-amami", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hiding their young in holes, they wish for their best safety.", "Escondem seus filhotes em buracos para mantê-los o mais seguros possível.", Language.BrazilianPortuguese);
            GrimoraMod.RegisterCard("Amami Rabbit", "Coelho-de-amami");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ankhame", "Ankhame", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A relic that is drawn to your blood, perhaps you could give it a swing!", "Uma relíquia atraída pelo seu sangue. Talvez você possa tentar brandi-la!", Language.BrazilianPortuguese);
            GrimoraMod.RegisterCard("Ankhame", "Ankhame");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anneta", "Anneta", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That ink keeps on pouring, is she even there anymore? All that death promises is that you will wake up again.", "A tinta continua a jorrar. Será que ela ainda está ali? Tudo o que a morte promete é que você despertará outra vez.", Language.BrazilianPortuguese);
            GrimoraMod.RegisterCard("Anneta", "Anneta");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anorexia", "Anorexia", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Overflowing you with self loathing, you never know what form it may take on next.", "Ela afoga você em autodesprezo, e nunca se sabe que forma assumirá em seguida.", Language.BrazilianPortuguese);
            GrimoraMod.RegisterCard("Anorexia", "Anorexia");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lych Bell", "Sino do Lich", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems like they found a new way to use bells.", "Parece que encontraram uma nova maneira de usar sinos.", Language.BrazilianPortuguese);
            GrimoraMod.RegisterCard("Lych Bell", "Sino do Lich");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TheBloated", "O Inchado", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grotesque boils, ready to burst.", "Furúnculos grotescos, prontos para estourar.", Language.BrazilianPortuguese);
            GrimoraMod.RegisterCard("TheBloated", "O Inchado");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BrainJar", "Cérebro no Pote", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One shudders to imagine what inhuman thoughts lie inside that jar...", "Só de imaginar os pensamentos desumanos dentro daquele frasco já dá calafrios...", Language.BrazilianPortuguese);
            GrimoraMod.RegisterCard("BrainJar", "Cérebro no Pote");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Combustor", "Combustor", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh dear, what a fall from such a stimulatingly high status, now all that's left is a metal carcass, and the last of that watchful substance...", "Nossa, que queda de uma posição tão exaltada e estimulante. Agora resta apenas uma carcaça de metal e o último vestígio daquela substância vigilante...", Language.BrazilianPortuguese);
            GrimoraMod.RegisterCard("Combustor", "Combustor");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Misplayed Stoat", "Arminho Maljogado", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A decaying Stoat whose oh-so perfect strategies failed him tremendously.", "Um Arminho em decomposição, cujas estratégias supostamente perfeitas falharam miseravelmente.", Language.BrazilianPortuguese);
            GrimoraMod.RegisterCard("Misplayed Stoat", "Arminho Maljogado");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dysmorphia", "Dismorfia", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dysmorphia Left.", "Dismorfia Esquerda.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dysmorphia Right.", "Dismorfia Direita.", Language.BrazilianPortuguese);
            GrimoraMod.RegisterCard("Dysmorphia", "Dismorfia");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exorcist", "Exorcista", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He still thinks banishing the dammed will do him good, does he know where he is?", "Ele ainda pensa que banir os condenados lhe fará bem. Será que sabe onde está?", Language.BrazilianPortuguese);
            GrimoraMod.RegisterCard("Exorcist", "Exorcista");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flembones", "Ossos Purulentos", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wait until he plays with his webcam.", "Espere até ele brincar com sua webcam.", Language.BrazilianPortuguese);
            GrimoraMod.RegisterCard("Flembones", "Ossos Purulentos");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stein & Frank", "Stein e Frank", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even hell was not hot enough to split them.", "Nem mesmo o inferno foi quente o bastante para separá-los.", Language.BrazilianPortuguese);
            GrimoraMod.RegisterCard("Stein & Frank", "Stein e Frank");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FulmineSkull", "Crânio Trovejante", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you listen closely, you can still hear the cackling of flame on bone... as well as their voice.", "Se ouvir com atenção, ainda poderá escutar o crepitar das chamas sobre os ossos... e também a voz deles.", Language.BrazilianPortuguese);
            GrimoraMod.RegisterCard("FulmineSkull", "Crânio Trovejante");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FulurOssa", "Ossos Trovejantes", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It never truly left the electric chair.", "Ele nunca deixou de fato a cadeira elétrica.", Language.BrazilianPortuguese);
            GrimoraMod.RegisterCard("FulurOssa", "Ossos Trovejantes");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PrometheusFlame", "Chama de Prometeu", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This one is quite unique, the lingering spoils of a thief to benefit humanity! Fancy liver by chance?", "Este é bem único: o espólio duradouro de um ladrão que beneficiou a humanidade! Por acaso aceita um fígado?", Language.BrazilianPortuguese);
            GrimoraMod.RegisterCard("PrometheusFlame", "Chama de Prometeu");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guts", "Entranhas", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Annoying guts.", "Entranhas irritantes.", Language.BrazilianPortuguese);
            GrimoraMod.RegisterCard("Guts", "Entranhas");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Harbinger", "Precursor", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A powerful fiend that extols a heavy price for its servitude.", "Um demônio poderoso que exige um preço alto por seus serviços.", Language.BrazilianPortuguese);
            GrimoraMod.RegisterCard("Harbinger", "Precursor");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hastur", "Hastur", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He came from beyond the stars, gifting pieces of his reflection to kings and fools alike. Will you accept this piece?", "Ele veio de além das estrelas, presenteando reis e tolos com pedaços de seu reflexo. Você aceitará este pedaço?", Language.BrazilianPortuguese);
            GrimoraMod.RegisterCard("Hastur", "Hastur");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Common Imp", "Diabrete Comum", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A tiny creature known for causing trouble and mayhem wherever it goes, with its mischievous grin and playful nature!", "Uma criatura minúscula conhecida por causar confusão e tumulto por onde passa, com seu sorriso travesso e sua natureza brincalhona!", Language.BrazilianPortuguese);
            GrimoraMod.RegisterCard("Common Imp", "Diabrete Comum");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Orochimitama", "Espírito de Orochi", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh... He is not supposed to be here...", "Ah... Ele não deveria estar aqui...", Language.BrazilianPortuguese);
            GrimoraMod.RegisterCard("Orochimitama", "Espírito de Orochi");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inochi", "Inochi", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A soothing presence to heal your creatures, a calm before the storm.", "Uma presença reconfortante que cura suas criaturas, a calmaria antes da tempestade.", Language.BrazilianPortuguese);
            GrimoraMod.RegisterCard("Inochi", "Inochi");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trail of Torment.", "Trilha do Tormento.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Possessed Limbs", "Membros Possuídos", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once attached to a living person, they now belong to something else entirely.", "Antes ligadas a uma pessoa viva, agora pertencem a algo completamente diferente.", Language.BrazilianPortuguese);
            GrimoraMod.RegisterCard("Possessed Limbs", "Membros Possuídos");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mole Digger", "Toupeira Coveira", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The stalwart Mole... Digger? Whatever this is...", "A firme Toupeira... Coveira? Seja lá o que for...", Language.BrazilianPortuguese);
            GrimoraMod.RegisterCard("Mole Digger", "Toupeira Coveira");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nekros", "Nekros", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nekros possesses the board, challenger. Death is his playground.", "Nekros domina o tabuleiro, desafiante. A morte é seu parquinho.", Language.BrazilianPortuguese);
            GrimoraMod.RegisterCard("Nekros", "Nekros");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NekrosPrime", "Nekros Prime", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You will find no greater power... than the simple thought of your own name... inscrybed upon a grave.", "Você não encontrará poder maior... do que o simples pensamento do seu nome... gravado em um túmulo.", Language.BrazilianPortuguese);
            GrimoraMod.RegisterCard("NekrosPrime", "Nekros Prime");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nuckelavee", "Nuckelavee", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Administrator of its sea, you better hope it's breath doesn't taint your Thralls!", "O administrador de seu mar. Melhor torcer para que seu hálito não contamine seus servos!", Language.BrazilianPortuguese);
            GrimoraMod.RegisterCard("Nuckelavee", "Nuckelavee");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OdiousMass", "Massa Odiosa", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How unsightly.", "Que visão desagradável.", Language.BrazilianPortuguese);
            GrimoraMod.RegisterCard("OdiousMass", "Massa Odiosa");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Orochi", "Orochi", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrifices must be made.", "Sacrifícios precisam ser feitos.", Language.BrazilianPortuguese);
            GrimoraMod.RegisterCard("Orochi", "Orochi");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Master Ouro", "Mestre Ouro", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "From within the endless torment and suffering, they had somehow learned a way to see inside this poor broken thing... and take away its pain.", "Em meio a tormento e sofrimento sem fim, eles de alguma forma aprenderam a olhar dentro desta pobre criatura destruída... e a retirar sua dor.", Language.BrazilianPortuguese);
            GrimoraMod.RegisterCard("Master Ouro", "Mestre Ouro");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An endless cycle of life and death has taken a toll on these discarded remains. The pain was real, but death is never final!", "Um ciclo sem fim de vida e morte desgastou estes restos descartados. A dor foi real, mas a morte nunca é o fim!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GanCeann", "Gan Ceann", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Countless legends tell of the dullahan, but all fail to convey the true extent of its pique.", "Incontáveis lendas falam do dullahan, mas nenhuma consegue transmitir toda a extensão de sua fúria.", Language.BrazilianPortuguese);
            GrimoraMod.RegisterCard("GanCeann", "Gan Ceann");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dark Prince", "Príncipe das Trevas", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The power of fluffy bois shines within you.", "O poder dos fofinhos peludos brilha dentro de você.", Language.BrazilianPortuguese);
            GrimoraMod.RegisterCard("Dark Prince", "Príncipe das Trevas");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stillborn Raven", "Corvo Natimorto", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Feels good to be young again!", "É bom ser jovem de novo!", Language.BrazilianPortuguese);
            GrimoraMod.RegisterCard("Stillborn Raven", "Corvo Natimorto");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reanimated", "Reanimado", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BRINGING THE SCYTHE OF DEATH, THE REVENANT... WAIT, WHAT?", "TRAZENDO A FOICE DA MORTE, O ESPECTRO... ESPERE, O QUÊ?", Language.BrazilianPortuguese);
            GrimoraMod.RegisterCard("Reanimated", "Reanimado");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "RevenantEldritch", "RevenantEldritch", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The source of Calamity, relentless and unerring.", "A fonte da Calamidade, implacável e infalível.", Language.BrazilianPortuguese);
            GrimoraMod.RegisterCard("RevenantEldritch", "RevenantEldritch");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lazy Bones", "Ossos Preguiçosos", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A slothful skeleton with a knack for jokes. I adore him.", "Um esqueleto preguiçoso com talento para piadas. Eu o adoro.", Language.BrazilianPortuguese);
            GrimoraMod.RegisterCard("Lazy Bones", "Ossos Preguiçosos");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skelephone", "Esqueletone", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A way to communicate with the dead, for a price.", "Uma forma de se comunicar com os mortos, por um preço.", Language.BrazilianPortuguese);
            GrimoraMod.RegisterCard("Skelephone", "Esqueletone");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soulgate", "Portão das Almas", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A chance to enter the soul realm, how delightful? I hope you can afford the price.", "Uma chance de entrar no reino das almas, que maravilha! Espero que você possa pagar o preço.", Language.BrazilianPortuguese);
            GrimoraMod.RegisterCard("Soulgate", "Portão das Almas");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SpadeWarrior", "Guerreiro de Espadas", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This fearsome warrior will put you six feet under, in every possible sense.", "Este guerreiro temível vai enterrar você a sete palmos, em todos os sentidos.", Language.BrazilianPortuguese);
            GrimoraMod.RegisterCard("SpadeWarrior", "Guerreiro de Espadas");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "UndeadCivilian", "Civil Morto-vivo", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lost in eternal darkness, this poor soul desperately seeks a way out. Perhaps you can light his way?", "Perdida na escuridão eterna, esta pobre alma procura desesperadamente uma saída. Talvez você possa iluminar seu caminho?", Language.BrazilianPortuguese);
            GrimoraMod.RegisterCard("UndeadCivilian", "Civil Morto-vivo");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "UndeadVillage", "Vila dos Mortos-vivos", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Abandoned and forlorn, this village seeks new residents to fill its decrepit homes.", "Abandonada e desolada, esta vila procura novos moradores para preencher suas casas em ruínas.", Language.BrazilianPortuguese);
            GrimoraMod.RegisterCard("UndeadVillage", "Vila dos Mortos-vivos");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In every town, in every city, someone must work to bury the dead. In time, they too will be buried.", "Em toda vila e cidade, alguém precisa enterrar os mortos. Com o tempo, essas pessoas também serão enterradas.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dr.Bones", "Dr. Ossos", Language.BrazilianPortuguese);
            GrimoraMod.RegisterCard("Dr.Bones", "Dr. Ossos");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whatever doesn't kill you simply makes you, saner.", "O que não mata você apenas o torna mais são.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wendigo", "Wendigo", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Returned from the deep wilds, reminds me of a friend.", "Vindo das terras selvagens distantes, lembra-me um amigo.", Language.BrazilianPortuguese);
            GrimoraMod.RegisterCard("Wendigo", "Wendigo");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mister Win", "Senhor Vitória", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card that wins. It always wins. That's why it's called Mister Win.", "Uma carta que vence. Ela sempre vence. Por isso se chama Senhor Vitória.", Language.BrazilianPortuguese);
            GrimoraMod.RegisterCard("Mister Win", "Senhor Vitória");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not that one, I'm afraid.", "Receio que não seja essa.", Language.BrazilianPortuguese);

            // Dlg
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You... you murderous monster.", "Você... seu monstro assassino.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh Dear... The flow of Calamity will pursue you.", "Oh, céus... O fluxo da Calamidade perseguirá você.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hecatomb the village you once lived.", "Sacrifique a vila onde você viveu.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Seak for the shovel that digs forever.", "Procure a pá que cava para sempre.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bring me the lost one with a spark in hand.", "Traga-me o perdido com uma faísca na mão.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Compelled by the beckoning of an ancient entity,", "Movido pelo chamado de uma entidade ancestral,", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a forbidden ritual has been initiated.", "um ritual proibido foi iniciado.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The pain reaches the ancient great serpent of death.", "A dor alcança a antiga e grande serpente da morte.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrifices must be made.", "Sacrifícios precisam ser feitos.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh... There are no dead cards yet.", "Ah... Ainda não há cartas mortas.", Language.BrazilianPortuguese);

            // Pack
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Revenant Mod Card Pack", "Pacote de Cartas do Mod Revenant", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card pack consists of mainly cards that return to the player in a variety of ways.", "Este pacote consiste principalmente em cartas que retornam ao jogador de várias maneiras.", Language.BrazilianPortuguese);
        }
    }
    public class SquirrelBombMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for SquirrelBombMod Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pipis", "Pipis", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pipis.", "Pipis.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Help", "Ajuda", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn [creature] will sacrifice itself to heal the adjacent cards by 1.", "No fim do turno de quem a possui, [creature] se sacrifica para recuperar 1 de vida das cartas adjacentes.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pass-through", "Passagem Livre", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is about to get attacked by a card with an attack higher than this card's health, this card perishes.", "Quando [creature] está prestes a ser atacada por uma carta cujo ataque é maior que sua vida, ela perece.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spam Call", "Ligação Indesejada", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Empty spaces within a circuit completed by [creature] spawn Spam Mail at the end of the owner's turn.", "No fim do turno de quem possui [creature], os espaços vazios dentro de um circuito completado por ela geram Spam.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NEO Strike", "Golpe NEO", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike each opposing space that is occupied by a creature and additionally every side of the board occupied by a creature. It will strike directly if no creatures oppose it.", "[creature] ataca cada espaço adversário ocupado por uma criatura e também os dois espaços de cada metade do lado adversário que contenha uma criatura. Se não houver criaturas adversárias, ataca os dois espaços centrais.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Call for Help", "Um Pedido de Ajuda", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will call for help.", "No fim do turno de quem a possui, [creature] pede ajuda.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Run Forth", "Avançar", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Before [creature] attacks, its power will be set to at least 1.", "Antes de [creature] atacar, seu poder será definido como pelo menos 1.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flying Head", "Cabeça Voadora", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The most important part.", "A parte mais importante.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spam Cart", "Carrinho de Spam", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Filled with spam mail. Absorbs all kinds of attacks.", "Cheio de spam. Absorve todos os tipos de ataque.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spam Mail", "Spam", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Has all kinds of unforgettable deals.", "Tem todo tipo de oferta inesquecível.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Big Shooter", "Atirador Pesado", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shoots big shots.", "Dispara grandes tiros.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heart on a Chain", "Coração Acorrentado", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beautiful.", "Lindo.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spamgel", "Spamgel", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The result of pressing F1.", "O resultado de apertar F1.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hand Phone", "Telefone de Mão", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do you really need anyone else?", "Você realmente precisa de mais alguém?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE POWER OF NEO!!!", "O PODER DE NEO!!!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't you wanna be a big shot?", "Você não quer ser um figurão?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Receiver", "Receptor", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The voice runs out eventually.", "A voz acaba se apagando.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grizzlipis", "Grizzlipis", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grizzlipis.", "Grizzlipis.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bear Cart", "Carrinho de Ursos", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Filled with bears. Absorbs all kinds of attacks.", "Cheio de ursos. Absorve todos os tipos de ataque.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bear Mail", "Correio dos Ursos", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mail for bears.", "Correspondência para ursos.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bear on a Chain", "Urso Acorrentado", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bear Hand", "Pata de Urso", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Squirrel Bomb", "Bomba de Esquilo", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Squirrels explode when killed, dealing 10 damage to adjacent cards.", "Esquilos explodem ao ser mortos, causando 10 de dano às cartas adjacentes.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dance Party", "Festa Dançante", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your cards move each turn. The cards that can't move die.", "Suas cartas se movem a cada turno. As cartas que não conseguirem se mover morrem.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Again", "de novo", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All opponent cards attack twice.", "Todas as cartas adversárias atacam duas vezes.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Starving", "Faminto", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pray.", "Reze.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dogfish", "Cação", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Each battle starts with a Bait Bucket that has Guardian.", "Cada batalha começa com um Balde de Iscas que possui Cão de Guarda.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Annoying Totems", "Totens Irritantes", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Start each battle with an Annoying totem for your most used tribe.", "Comece cada batalha com um totem de Irritante para sua tribo mais usada.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Painful Draws", "Compras Dolorosas", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Drawing from the main deck deals 1 damage.", "Comprar da pilha principal causa 1 de dano.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Painful Squirrels", "Esquilos Dolorosos", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Drawing from the side deck deals 1 damage.", "Comprar da pilha auxiliar causa 1 de dano.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Runes", "Runas", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enemy cards of the dominant tribe get random sigils.", "Cartas adversárias da tribo dominante recebem selos aleatórios.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dentistry", "Odontologia", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Item events and Trinket Bearer cards only give pliers.", "Eventos de itens e cartas com Porta-coisas dão apenas Alicates.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Archived", "Arquivado", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A random card choice is hidden in every card choice event.", "Uma opção de carta aleatória fica oculta em cada evento de escolha de cartas.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Foundation", "Fundação", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All cards have 1 less attack. Side deck cards have Leader.", "Todas as suas cartas têm 1 de ataque a menos. Cartas do baralho auxiliar possuem Líder.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Final Boss v2", "Chefe Final v2", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Replaces Leshy as the final boss with a true BIG SHOT.", "Substitui Leshy como chefe final por um verdadeiro FIGURÃO.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You must dance! Don't stop dancing!!", "Você tem que dançar! Não pare de dançar!!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whoever stops dancing at my party will suffer the consequences.", "Quem parar de dançar na minha festa sofrerá as consequências.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Is that mechanic annoying?", "Essa mecânica é irritante?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perfect. That's the point of it.", "Perfeito. Essa é a ideia.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dance my puppet! Daaaance.", "Dance, minha marionete! Daaance.", Language.BrazilianPortuguese);
