            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's a squirrel that can block fliers", "Um Esquilo capaz de bloquear criaturas voadoras.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bee Drone", "Zangão", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "For when you need just one point of damage", "Para quando você só precisa de um ponto de dano.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ant Drone", "Formiga Macho", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bee Drone", "Zangão", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's not much, but it's an ant.", "Não é muita coisa, mas é uma formiga.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Puppy", "Filhote de Cão", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This energetic little puppy will dig up a fresh bone every turn", "Este filhote cheio de energia vai desenterrar um osso fresco a cada turno.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spare Tentacle", "Tentáculo Reserva", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've never seen that [c:bR]thing[c:] before, but I can tell there are no bones in it.", "Nunca vi essa [c:bR]coisa[c:] antes, mas sei dizer que não tem ossos.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One-Eyed Goat", "Cabra de Um Olho", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This goat generates additional blood...for a price", "Esta cabra gera sangue adicional... por um preço.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I didn't realize this thing came from eggs", "Não sabia que essa coisa vinha de ovos.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emptier Vessel", "Receptáculo Ainda Mais Vazio", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here you may replace the creatures in your [c:bR]side deck[c:]", "Aqui você pode substituir as criaturas do seu [c:bR]baralho auxiliar[c:].", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Side Deck Second Chance", "Segunda Chance do Baralho Auxiliar", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You are given the option to change your side deck on maps two and three", "Você pode trocar seu baralho auxiliar no segundo e no terceiro mapas.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leshy is ready to give us side deck options", "Leshy está pronto para nos oferecer opções de baralho auxiliar.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acceptable Sacrifice", "Sacrifício Aceitável", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrificing [creature] will count as if two creatures were sacrificed", "Sacrificar [creature] conta como se duas criaturas tivessem sido sacrificadas.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Painful Entrance", "Entrada Dolorosa", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will deal two damage to the player when it enters play.", "[creature] causa dois pontos de dano ao jogador quando entra em jogo.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gelatinous", "Gelatinoso", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] has no bones", "[creature] não tem ossos.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a Side Deck", "Escolha um Baralho Auxiliar", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Player selected sidedeck card", "Carta do baralho auxiliar escolhida pelo jogador", Language.BrazilianPortuguese);


        }
    }
    public class TalkingPossumMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Talking_Possum Mod");


            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh, this one. Right. You can keep it. Not much use to me, anyway.", "Ah, este aqui. Certo. Pode ficar com ele. Não me serve para muita coisa mesmo.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awesome Opossum", "Gambá Incrível", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Playing dead? What a despicable creature.", "Fingindo-se de morto? Que criatura desprezível.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not-So-Awesome Opossum", "Gambá Não Tão Incrível", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]Alright.[w:1]", "[e:anger]Certo.[w:1]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:neutral]You must be... [w:0.4][c:#280085]confused[c:][w:1].", "[e:neutral]Você deve estar... [w:0.4][c:#280085]confuso[c:][w:1].", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I get it.[w:0.2] I do.[w:0.2] It sucks.[w:0.4]", "Eu entendo.[w:0.2] Entendo mesmo.[w:0.2] É uma droga.[w:0.4]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]So, uh.[w:0.2] Hi.[w:0.2]", "[e:surprise]Então, ah.[w:0.2] Oi.[w:0.2]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We're...[w:0.6] [e:anger]stuck together, I suppose.[w:0.2]", "Estamos...[w:0.6] [e:anger]presos juntos, eu suponho.[w:0.2]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:neutral]It could be worse.[w:0.2]", "[e:neutral]Poderia ser pior.[w:0.2]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Look on the [c:#280085]bright side![c:][w:0.4]", "Veja pelo [c:#280085]lado bom![c:][w:0.4]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "... There's no bright side.", "... Não existe lado bom.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We're all doomed.[leshy:Quiet now.][w:2]", "Estamos todos condenados.[leshy:Quieto agora.][w:2]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good luck.[w:1]", "Boa sorte.[w:1]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]You know,[w:0.2] I was[w:0.4]", "[e:surprise]Sabe,[w:0.2] eu já fui[w:0.4]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]A [c:#280085]scrybe[c:] once.[w:1]", "[e:quiet]um [c:#280085]Patrono[c:].[w:1]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good times, good times.[w:0.6] Alas.[w:0.6]", "Bons tempos, bons tempos.[w:0.6] Ah, enfim.[w:0.6]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]Now I'm a fucking possum.[w:1]", "[e:surprise]Agora sou um maldito gambá.[w:1]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]... This man over there?[w:0.4]", "[e:anger]... Aquele homem ali?[w:0.4]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That guy?[w:0.6]", "Aquele cara?[w:0.6]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]He wasn't so bad before this.[w:1]", "[e:quiet]Ele não era tão ruim antes disso.[w:1]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I still think he has...[w:0.6]", "Ainda acho que ele tem...[w:0.6]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "... Some good in him.[w:0.4]", "... Algo de bom.[w:0.4]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]Some.[w:1]", "[e:anger]Algo.[w:1]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]... Anyway,[w:0.4] here's my plan-[leshy:Silence.][w:3]", "[e:quiet]... Enfim,[w:0.4] aqui está meu plano-[leshy:Silêncio.][w:3]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aight. Got the memo.[w:0.6]", "Tá. Entendi o recado.[w:0.6]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]Good luck, traveler.[w:1]", "[e:anger]Boa sorte, viajante.[w:1]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]I'm rooting for you.[w:1]", "[e:quiet]Estou torcendo por você.[w:1]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[a:anger]Here we go again.[w:1]", "[a:anger]Lá vamos nós de novo.[w:1]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Isn't this FUN?[w:1] [e:surprise]Nope.[w:0.4]", "Não é DIVERTIDO?[w:1] [e:surprise]Não.[w:0.4]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's not fun.[w:1]", "Não é divertido.[w:1]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:neutral]You know, I think[w:0.4]", "[e:neutral]Sabe, acho que[w:0.4]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]You have potential.[w:1]", "[e:quiet]você tem potencial.[w:1]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm rooting for you.[w:1]", "Estou torcendo por você.[w:1]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:neutral]Also,[w:0.2] if you[w:0.2], uh[w:0.4]", "[e:neutral]Além disso,[w:0.2] se você[w:0.2], ah[w:0.4]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you find an...[w:0.4] [c:#280085]odd-looking wolf...[c:][w:1]", "Se encontrar um...[w:0.4] [c:#280085]lobo de aparência estranha...[c:][w:1]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]... Tell him I-[leshy:Enough of that now.][w:2]", "[e:quiet]... Diga a ele que eu-[leshy:Chega disso.][w:2]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Killjoy.[w:1]", "Estraga-prazeres.[w:1]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]This is getting old.[w:1]", "[e:anger]Isso já está ficando velho.[w:1]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]... You know...[w:0.4]", "[e:anger]... Sabe...[w:0.4]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That old man over there?[w:0.4]", "Aquele velho ali?[w:0.4]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:neutral]He has no idea[w:0.2]", "[e:neutral]Ele não faz ideia[w:0.2]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He's biting[w:0.2] [e:anger]way[w:0.2] more[w:0.2]", "Ele está enfrentando[w:0.2] [e:anger]algo[w:0.2] muito[w:0.2]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]Than he can possibly chew.[w:1]", "[e:surprise]maior do que consegue suportar.[w:1]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:neutral]Listen to me now.[w:0.6]", "[e:neutral]Escute-me agora.[w:0.6]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]You have to-[leshy:Quiet, vermin.][w:2]", "[e:anger]Você precisa-[leshy:Quieto, verme.][w:2]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]... Vermin?[w:0.2] Excuse me?[w:0.4]", "[e:surprise]... Verme?[w:0.2] Como é?[w:0.4]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You know my name.[w:0.4]", "Você sabe meu nome.[w:0.4]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's-[leshy:I said quiet.][w:2]", "É-[leshy:Eu disse quieto.][w:2]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger][c:#280085]Lamb to the slaughter.[c:][w:1]", "[e:anger][c:#280085]Um cordeiro levado ao abate.[c:][w:1]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]NOT THE FACE!", "[e:surprise]NO ROSTO, NÃO!", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]LEAVE ME ALONE.", "[e:surprise]ME DEIXE EM PAZ.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]QUIT IT, GODDAMMIT.", "[e:surprise]PARE COM ISSO, DROGA.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]You're lucky I'm trapped as a marsupial.", "[e:surprise]Sua sorte é que estou preso como um marsupial.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]Okay, I see how it is--", "[e:surprise]Certo, já entendi como é--", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]AGAIN??", "[e:surprise]DE NOVO??", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]AGAIN?? REALLY??", "[e:surprise]DE NOVO?? SÉRIO??", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]Odd feeling.", "[e:surprise]Sensação estranha.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]Maybe skip me, perhaps?", "[e:quiet]Talvez possa me deixar de fora?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]I'd rather you didn't.", "[e:surprise]Preferia que você não fizesse isso.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]Have you seen a strange-looking wolf?", "[e:quiet]Você viu um lobo de aparência estranha?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:neutral]It'd be... acceptable.", "[e:neutral]Seria... aceitável.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]I mean, if you insist.", "[e:surprise]Quer dizer, se você insiste.", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]Would it suit me?", "[e:quiet]Isso ficaria bem em mim?", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]... Ah.[w:1]", "[e:surprise]... Ah.[w:1]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]The board.[w:0.4] Again.[w:0.6]", "[e:anger]O tabuleiro.[w:0.4] De novo.[w:0.6]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:#1e0040]Lamb to the slaughter.[c:][w:1]", "[c:#1e0040]Um cordeiro levado ao abate.[c:][w:1]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]I get it.[w:0.2]I do.[w:0.2]I do.[w:0.4]", "[e:surprise]Eu entendo.[w:0.2]Entendo.[w:0.2]Entendo.[w:0.4]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do as you must,[w:0.2] traveler.[w:1]", "Faça o que precisa,[w:0.2] viajante.[w:1]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:neutral]I'm rooting for you.[w:1]", "[e:neutral]Estou torcendo por você.[w:1]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]Ah.[w:0.2] The board, again.[w:0.2] I see.[w:1]", "[e:surprise]Ah.[w:0.2] O tabuleiro de novo.[w:0.2] Entendo.[w:1]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger][c:#1e0040]Lamb to the slaughter.[c:][w:1]", "[e:anger][c:#1e0040]Um cordeiro levado ao abate.[c:][w:1]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]... I suppose.[w:1]", "[e:surprise]... Suponho que sim.[w:1]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:quiet]Ah, this.[w:1] [e:surprise]Once again.[w:1]", "[e:quiet]Ah, isso.[w:1] [e:surprise]Mais uma vez.[w:1]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:anger]... I'm ready.[w:1]", "[e:anger]... Estou pronto.[w:1]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:surprise]You know what's funny?[w:0.4]", "[e:surprise]Sabe o que é engraçado?[w:0.4]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:neutral]I really liked animals[w:0.4]", "[e:neutral]Eu gostava muito de animais[w:0.4]", Language.BrazilianPortuguese);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Before all of this.[w:1]", "Antes de tudo isso.[w:1]", Language.BrazilianPortuguese);
