            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amber Dawn, searching for the perfect meals", "Amanhecer Âmbar, à procura das refeições perfeitas.", Language.BrazilianPortuguese);
